PIPER = {"etat": "absent", "progres": 0.0, "message": ""}
_PIPER_VERROU = threading.Lock()


def dossier_piper():
    return os.path.join(dossier_jarvis(), "piper")


def bibli_espeak():
    """espeak-ng, livre dans l'archive de Piper avec ses donnees : c'est lui
    qui transforme le texte en phonemes."""
    nom = "espeak-ng.dll" if os.name == "nt" else "libespeak-ng.so.1"
    return os.path.join(dossier_piper(), "piper", nom)


def fichier_voix(nom):
    return os.path.join(dossier_jarvis(), "voix", nom + ".onnx")


def voix_presente(nom):
    f = fichier_voix(nom)
    return os.path.isfile(f) and os.path.getsize(f) > 0 and os.path.isfile(f + ".json")


def voix_choisie(cfg):
    nom = str(cfg.get("jarvis_voix_modele", _jv.VOIX_DEFAUT) or _jv.VOIX_DEFAUT)
    return nom if nom == "windows" or nom in _jv.VOIX_PIPER else _jv.VOIX_DEFAUT


def piper_pret(cfg):
    """De quoi charger la voix neuronale, ou None. La voix choisie d'abord ;
    a defaut, celle de secours si elle est la."""
    nom = voix_choisie(cfg)
    if nom == "windows" or not os.path.isfile(bibli_espeak()):
        return None
    for n in (nom, _jv.VOIX_SECOURS):
        if voix_presente(n):
            f = fichier_voix(n)
            try:
                with open(f + ".json", encoding="utf-8") as fj:
                    conf = json.load(fj)
            except Exception:
                continue
            locuteur = _jv.VOIX_PIPER.get(n, {}).get("locuteur")
            ids = conf.get("speaker_id_map") or {}
            return {"nom": n, "bibliotheque": bibli_espeak(),
                    "donnees": os.path.join(dossier_piper(), "piper"),
                    "modele": f, "frequence": _jv.frequence_du_modele(f + ".json"),
                    "espeak": str((conf.get("espeak") or {}).get("voice") or "fr"),
                    "locuteur": int(ids.get(locuteur, 0)) if locuteur else 0}
    return None


def _telecharger(url, dst, ouvrir, part=None, etat=None):
    etat = PIPER if etat is None else etat
    with ouvrir(url) as r, open(dst + ".part", "wb") as f:
        total = int(r.headers.get("Content-Length") or 0)
        recu = 0
        while True:
            bout = r.read(1 << 20)
            if not bout:
                break
            f.write(bout)
            recu += len(bout)
            if part and total:
                etat["progres"] = part[0] + (part[1] - part[0]) * recu / total
    os.replace(dst + ".part", dst)


def _preparer_espeak(ouvrir, part=(0.0, 0.3), etat=None):
    """espeak-ng et ses donnees : l'archive du moteur Piper (21 Mo). Les deux
    voix en ont besoin -- c'est lui qui fait les phonemes."""
    if os.path.isfile(bibli_espeak()):
        return
    import zipfile
    os.makedirs(dossier_piper(), exist_ok=True)
    archive = os.path.join(dossier_piper(), "piper.zip")
    _telecharger(_jv.PIPER_MOTEUR, archive, ouvrir, part, etat)
    with zipfile.ZipFile(archive) as z:
        z.extractall(dossier_piper())
    os.remove(archive)


def preparer_piper(cfg, ouvrir=None):
    """Le moteur (21 Mo) et la voix choisie (20 a 60 Mo), une fois. Hugging
    Face d'abord ; les voix qui existent aussi sur GitHub y sont reprises si
    Hugging Face ne repond pas ; en dernier recours, la voix de secours."""
    nom = voix_choisie(cfg)
    if nom == "windows":
        return False
    with _PIPER_VERROU:
        if piper_pret(cfg) and voix_presente(nom):
            PIPER.update(etat="pret", progres=1.0, message="")
            return True
        ouvrir = ouvrir or (lambda url: urllib.request.urlopen(url, timeout=60, context=_contexte_ssl()))
        PIPER.update(etat="preparation", progres=0.0, message="")
        try:
            import tarfile
            os.makedirs(dossier_piper(), exist_ok=True)
            os.makedirs(os.path.dirname(fichier_voix(nom)), exist_ok=True)
            with _ESPEAK_VERROU:
                _preparer_espeak(ouvrir, (0.0, 0.3))
            for n in (nom, _jv.VOIX_SECOURS):
                if voix_presente(n):
                    break
                entree = _jv.VOIX_PIPER[n]
                dst = fichier_voix(n)
                try:
                    base = _jv.PIPER_VOIX_HF + entree["hf"] + n
                    _telecharger(base + ".onnx.json", dst + ".json", ouvrir)
                    _telecharger(base + ".onnx", dst, ouvrir, (0.3, 1.0))
                    break
                except Exception as e:
                    print("Jarvis : voix %s absente de Hugging Face (%s)" % (n, e))
                if entree.get("github"):
                    try:
                        archive = dst + ".tar.gz"
                        _telecharger(_jv.PIPER_VOIX_GITHUB + entree["github"] + ".tar.gz", archive,
                                     ouvrir, (0.3, 1.0))
                        with tarfile.open(archive) as t:
                            for m in t.getmembers():
                                if m.name.endswith(".onnx") or m.name.endswith(".onnx.json"):
                                    bout = t.extractfile(m).read()
                                    cible = dst + (".json" if m.name.endswith(".json") else "")
                                    with open(cible + ".part", "wb") as f:
                                        f.write(bout)
                                    os.replace(cible + ".part", cible)
                        os.remove(archive)
                        if voix_presente(n):
                            break
                    except Exception as e:
                        print("Jarvis : voix %s absente de GitHub (%s)" % (n, e))
            if not piper_pret(cfg):
                raise RuntimeError("aucune voix n'a pu etre telechargee")
            PIPER.update(etat="pret", progres=1.0,
                         message="" if voix_presente(nom) else
                         "La voix choisie n'a pas pu venir : Jarvis parle avec la voix de secours.")
            return True
        except Exception as e:
            PIPER.update(etat="erreur", message="Voix non telechargee : %s" % str(e)[:120])
            print("Jarvis : voix neuronale indisponible (%s)" % e)
            return False


# ---------- la voix anglaise de Jarvis : Kokoro ----------

KOKORO = {"etat": "absent", "progres": 0.0, "message": "", "calcul": {}}


def texte_calcul_kokoro(cle):
    """Ce qui calcule la voix Kokoro de cette langue, et a quelle vitesse --
    rapporte par le processus de la voix au chargement (l'exe n'a pas de
    console : sans ca, rien ne dirait si la carte graphique travaille)."""
    c = KOKORO.get("calcul", {}).get(cle)
    if not c or not c.get("moteur"):
        return ""
    t = " Calculee par %s" % _jv.nom_moteur_kokoro(c["moteur"])
    if c.get("rtf"):
        t += ", %.2f s par seconde de parole" % c["rtf"]
    t += "."
    if c["moteur"] == "CPUExecutionProvider" and c.get("refus"):
        t += " (Carte graphique refusee : %s)" % c["refus"][0][:300]
    return t
_KOKORO_VERROU = threading.Lock()
_ESPEAK_VERROU = threading.Lock()     # les deux preparations peuvent vouloir l'archive en meme temps


def langue_jarvis(cfg):
    return "fr" if str(cfg.get("jarvis_langue", "en")) == "fr" else "en"


def dossier_kokoro():
    return os.path.join(dossier_jarvis(), "kokoro")


def fichier_kokoro(nom):
    return os.path.join(dossier_kokoro(), nom)


def kokoro_present():
    """Les deux fichiers, a l'octet pres : un telechargement coupe ne passe
    jamais pour complet."""
    return all(os.path.isfile(fichier_kokoro(n)) and os.path.getsize(fichier_kokoro(n)) == taille
               for n, taille in _jv.KOKORO_TAILLES.items())


def voix_kokoro_choisie(cfg):
    v = str(cfg.get("jarvis_voix_kokoro") or _jv.KOKORO_DEFAUT)
    return v if v in _jv.VOIX_KOKORO else _jv.KOKORO_DEFAUT


def fils_kokoro():
    """La moitie des coeurs, entre deux et six : la phrase suivante se calcule
    pendant que la premiere se dit, sans prendre le PC."""
    return max(2, min(6, (os.cpu_count() or 4) // 2))


def voix_fr_choisie(cfg):
    """Sa voix francaise : une voix Kokoro (VOIX_KOKORO_FR), ou « piper » --
    alors c'est `jarvis_voix_modele`, une voix Piper ou celle de Windows."""
    v = str(cfg.get("jarvis_voix_fr") or _jv.KOKORO_FR_DEFAUT)
    return v if v == "piper" or v in _jv.VOIX_KOKORO_FR else _jv.KOKORO_FR_DEFAUT


def kokoro_voulu(cfg):
    """Kokoro sert-il ? Pour parler anglais, ou pour sa voix francaise."""
    return langue_jarvis(cfg) == "en" or voix_fr_choisie(cfg) != "piper"


def kokoro_fr_pret(cfg):
    """De quoi charger sa voix francaise par Kokoro, ou None (pas choisie, ou
    pas encore la : Piper parle en attendant)."""
    v = voix_fr_choisie(cfg)
    if v == "piper" or not kokoro_present() or not os.path.isfile(bibli_espeak()):
        return None
    return {"cle": "fr", "moteur": "kokoro", "langue": "fr", "bibliotheque": bibli_espeak(),
            "donnees": os.path.join(dossier_piper(), "piper"), "espeak": _jv.KOKORO_ESPEAK_FR,
            "modele": fichier_kokoro(_jv.KOKORO_MODELE), "voix_fichier": fichier_kokoro(_jv.KOKORO_VOIX),
            "voix": v, "fils": fils_kokoro()}


def kokoro_pret(cfg):
    """De quoi charger la voix anglaise, ou None."""
    if langue_jarvis(cfg) != "en" or not kokoro_present() or not os.path.isfile(bibli_espeak()):
        return None
    return {"cle": "en", "moteur": "kokoro", "bibliotheque": bibli_espeak(),
            "donnees": os.path.join(dossier_piper(), "piper"), "espeak": _jv.KOKORO_ESPEAK,
            "modele": fichier_kokoro(_jv.KOKORO_MODELE), "voix_fichier": fichier_kokoro(_jv.KOKORO_VOIX),
            "voix": voix_kokoro_choisie(cfg), "fils": fils_kokoro()}


def preparer_kokoro(cfg, ouvrir=None):
    """Le modele (310 Mo) et les voix (27 Mo), une fois, depuis GitHub -- et
    espeak-ng, l'archive de Piper, s'il n'est pas deja la."""
    with _KOKORO_VERROU:
        if kokoro_present() and os.path.isfile(bibli_espeak()):
            KOKORO.update(etat="pret", progres=1.0, message="")
            return True
        ouvrir = ouvrir or (lambda url: urllib.request.urlopen(url, timeout=60, context=_contexte_ssl()))
        KOKORO.update(etat="preparation", progres=0.0, message="")
        try:
            os.makedirs(dossier_kokoro(), exist_ok=True)
            with _ESPEAK_VERROU:
                _preparer_espeak(ouvrir, (0.0, 0.06), KOKORO)
            for nom, part in ((_jv.KOKORO_VOIX, (0.06, 0.14)), (_jv.KOKORO_MODELE, (0.14, 1.0))):
                dst = fichier_kokoro(nom)
                if os.path.isfile(dst) and os.path.getsize(dst) == _jv.KOKORO_TAILLES[nom]:
                    continue
                _telecharger(_jv.KOKORO_SOURCE + nom, dst, ouvrir, part, KOKORO)
                if os.path.getsize(dst) != _jv.KOKORO_TAILLES[nom]:
                    os.remove(dst)
                    raise RuntimeError("%s : pas la taille attendue" % nom)
            KOKORO.update(etat="pret", progres=1.0, message="")
            return True
        except Exception as e:
            KOKORO.update(etat="erreur", message="Voix Kokoro non telechargee : %s" % str(e)[:120])
            print("Jarvis : voix Kokoro indisponible (%s)" % e)
            return False


def charges_voix(cfg):
    """Ce que porte le processus de la voix : l'anglais de Jarvis (Kokoro) et
    son francais -- celui du mode psy aussi -- par Kokoro s'il est choisi et
    la, sinon par Piper. Chacun s'il est la."""
    out = []
    k = kokoro_pret(cfg)
    if k:
        out.append(k)
    f = kokoro_fr_pret(cfg)
    if f:
        out.append(f)
    else:
        p = piper_pret(cfg)
        if p:
            out.append(dict(p, cle="fr", moteur="piper", fils=2))
    return out


def signature_voix(charges):
    return "|".join("%s:%s:%s" % (c["cle"], c["modele"], c.get("voix", c.get("locuteur", "")))
                    for c in charges)


VOIX_ENFANT_ARG = "--voix"
_VOIX_ENFANT = {"proc": None, "sock": None, "pret": False, "pretes": set(), "charge": None,
                "echecs": 0, "prochain": 0.0}
_VOIX_VERROU = threading.Lock()


def _commande_voix(port, secret):
    base = [sys.executable] if FIGE else [sys.executable, os.path.abspath(__file__)]
    return base + [VOIX_ENFANT_ARG, str(port), secret]


def voix_prete(cle=None):
    """Une voix chargee -- celle de cette langue, si on la nomme."""
    p = _VOIX_ENFANT["proc"]
    if not (p is not None and p.poll() is None and _VOIX_ENFANT["sock"] is not None
            and _VOIX_ENFANT["pret"]):
        return False
    return cle is None or cle in _VOIX_ENFANT["pretes"]


def envoyer_voix(objet):
    sock = _VOIX_ENFANT["sock"]
    if sock is None:
        return False
    try:
        _jv.envoyer(sock, objet, _VOIX_VERROU)
        return True
    except Exception:
        return False


def demarrer_voix(cfg):
    """Le processus de la voix, avec ses voix chargees UNE fois : l'anglais
    de Jarvis d'abord (c'est lui qui parle le plus), le francais ensuite."""
    arreter_voix()
    charges = charges_voix(cfg)
    if not charges:
        return False
    proc, sock = _lancer_enfant(lambda port, secret: _commande_voix(port, secret), "de la voix")
    _VOIX_ENFANT.update(proc=proc, sock=sock, pret=False, pretes=set(), charge=signature_voix(charges))
    threading.Thread(target=_lire_voix, args=(sock,), daemon=True).start()
    for c in charges:
        envoyer_voix(dict({"cmd": "charger", "silence": 0.2}, **c))
    return True


def arreter_voix():
    sock, proc = _VOIX_ENFANT["sock"], _VOIX_ENFANT["proc"]
    _VOIX_ENFANT.update(sock=None, proc=None, pret=False, pretes=set(), charge=None)
    _fermer_enfant(sock, proc)
    VOIX.enfant_perdu()


atexit.register(arreter_voix)


# LES SOUS-TITRES DU PANNEAU : ce que dit chaque texte envoye a la voix, et
# ou elle en est (l'evenement « dit » : telle phrase commence, elle dure tant).
SOUS_TITRES = {}


def nom_dans_sa_voix(ident=None, texte=None):
    """Son propre nom est-il dans ce qu'il dit ? Pendant qu'il parle,
    l'oreille cherche « Jarvis » -- sauf si sa propre voix le prononce. Dans
    le doute (texte inconnu), oui : elle ne cherche pas."""
    if texte is None:
        st = SOUS_TITRES.get(ident)
        texte = " ".join(st.get("phrases") or []) if st else ""
    if not texte:
        return True
    try:
        return bool(_jv.contient_nom(texte, noms_appris()))
    except Exception:
        return True


def sous_titre_courant(maintenant=None):
    """Ce que Jarvis a deja prononce, a l'instant."""
    st = JARVIS.get("sous_titre")
    if not st:
        return ""
    t = time.time() if maintenant is None else maintenant
    if st.get("k", -1) < 0:
        if not st.get("estime") or not st.get("t0"):
            return ""
        # la voix de Windows ne dit pas ou elle en est : au debit moyen d'une voix
        tout = " ".join(st["phrases"])
        return _jv.texte_dit([tout], 0, (t - st["t0"]) * _jv.LETTRES_PAR_S / max(1, len(tout)))
    return _jv.texte_dit(st["phrases"], st["k"], (t - st["t0"]) / max(0.1, st.get("duree") or 0.1))


def niveau_de_sa_voix(maintenant=None):
    """Le niveau de SA voix (0 a 1) a l'instant, lu dans l'enveloppe que la
    voix envoie avec chaque phrase (« dit ») : sa boule et son panneau jouent
    avec. 0 tant que le son n'a pas commence ; None quand la voix ne dit rien
    de son son (la voix de Windows) -- on swingue alors sans elle."""
    st = JARVIS.get("sous_titre")
    if not st:
        return 0.0
    if st.get("estime"):
        return None
    env = st.get("enveloppe")                     # (t0, pas, niveaux), d'un seul tenant
    if env is None:
        return 0.0 if st.get("k", -1) < 0 else None
    t = time.time() if maintenant is None else maintenant
    t0, pas, niveaux = env
    return _jv.niveau_enveloppe(niveaux, pas, t - t0 - _jv.VOIX_LATENCE_S)


def _lire_voix(sock):
    while True:
        try:
            ev = _jv.recevoir(sock)
        except Exception:
            ev = None
        if ev is None:
            break
        quoi = ev.get("evt")
        if quoi == "dit":
            st = SOUS_TITRES.get(ev.get("id"))
            if st is not None:
                t0 = time.time()
                maj = {"k": int(ev.get("phrase") or 0), "t0": t0, "duree": float(ev.get("duree") or 0.0)}
                if isinstance(ev.get("env"), list):
                    # son enveloppe, avec son instant : lue d'un bloc par la boule
                    maj["enveloppe"] = (t0, float(ev.get("pas") or _jv.VOIX_ENVELOPPE_PAS), ev["env"])
                st.update(maj)
                JARVIS["sous_titre"] = st
        elif quoi == "debut":
            # IL PARLE : l'oreille guette qu'on lui coupe la parole
            noter_temps("voix")
            envoyer_oreille({"cmd": "parole", "actif": True, "nom": nom_dans_sa_voix(ev.get("id"))})
            if ev.get("id") in SOUS_TITRES:
                JARVIS["sous_titre"] = SOUS_TITRES[ev.get("id")]
        elif quoi == "pret":
            _VOIX_ENFANT["pretes"].add(str(ev.get("cle") or "fr"))
            if ev.get("moteur"):
                KOKORO.setdefault("calcul", {})[str(ev.get("cle") or "fr")] = {
                    "moteur": ev.get("moteur"), "rtf": ev.get("rtf"), "refus": ev.get("refus") or []}
            _VOIX_ENFANT.update(pret=True, echecs=0)
            if ev.get("cle") == "en" or (ev.get("cle") == "fr" and kokoro_fr_pret(CFG)):
                KOKORO.update(etat="pret", message="")
        elif quoi == "fini":
            # la suite de la meme reponse attend deja derriere : l'oreille ne
            # croit pas qu'il s'est tu entre les deux (elle guette toujours
            # qu'on lui coupe la parole)
            if not any(i != ev.get("id") for i in VOIX.attentes):
                envoyer_oreille({"cmd": "parole", "actif": False})
            VOIX.fini(ev.get("id"), bool(ev.get("coupe")), ev.get("reste"), rate=bool(ev.get("rate")))
        elif quoi == "rendu":
            recevoir_porteuse(ev)            # la porteuse de la transcription
        elif quoi == "erreur":
            print("Jarvis : voix : %s" % str(ev.get("message"))[:200])
            # La voix anglaise n'a pas pu se charger : on le DIT, au lieu de
            # laisser Jarvis parler avec la voix de Windows sans explication.
            if ev.get("cle") == "en":
                KOKORO.update(etat="erreur", message="Voix anglaise impossible a charger : %s"
                              % str(ev.get("message"))[:120])
    if _VOIX_ENFANT["sock"] is sock:
        # Tombee sans qu'on l'arrete : la voix de Windows prend le relais, et
        # celle-ci repart plus tard, de plus en plus lentement.
        n = _VOIX_ENFANT["echecs"]
        _VOIX_ENFANT.update(sock=None, pret=False, charge=None, echecs=n + 1,
                            prochain=time.time() + JARVIS_RELANCE_S[min(n, len(JARVIS_RELANCE_S) - 1)])
        VOIX.enfant_perdu(redire=True)


class Voix:
    """Ce que Jarvis dit. La voix neuronale (Piper) vit dans son processus, le
    modele charge une fois : la premiere phrase sonne en quelques dizaines de
    millisecondes, les suivantes se calculent pendant qu'elle se dit, et
    `taire()` coupe au dixieme de seconde -- « Jarvis, stop ».

    Si elle n'est pas la (pas encore telechargee, ou tombee), c'est la voix de
    Windows (SAPI), dans un fil a part : mieux vaut une voix de GPS que pas de
    reponse du tout."""

    def __init__(self):
        self.file = []
        self.signal = threading.Event()
        self.couper = threading.Event()
        self.parle = False
        self.fil = None
        self.sapi = None
        self.disponible = os.name == "nt"      # la voix de Windows
        self.attentes = {}
        self.en_cours = {}          # ident -> (texte, fin, langue) : ce qu'il est en train de dire
        self.reprise = None         # ce qu'on lui a coupe, s'il faut le reprendre
        self.n = 0
        self.verrou = threading.Lock()
        self.enchaine = {}          # ident -> celui dont il est la suite (sa reponse, apres la phrase d'avance)
        self.coupes = set()         # les textes qu'on lui a coupes (voir `rejoindre`)
        self.repris = {}            # ident coupe -> celui qui l'a repris (coupe pour rien)

    def peut_parler(self):
        return voix_prete() or self.disponible

    def dire(self, texte, fin=None, langue="fr", suite_de=None):
        """UNE VOIX PAR LANGUE : l'anglais par Kokoro, le francais par Piper.
        Si celle de la langue n'est pas chargee, la voix de Windows DANS CETTE
        LANGUE -- une voix francaise qui lit de l'anglais est pire qu'un GPS.
        Rend le numero de ce qu'elle dit (voir `rattacher`), ou None."""
        langue = "en" if langue == "en" else "fr"
        texte = _jv.texte_pour_piper(texte, langue)
        if not texte:
            if fin:
                fin()
            return
        cle = langue if voix_prete(langue) else (None if self.disponible else
                                                  ("fr" if voix_prete("fr") else "en" if voix_prete("en") else None))
        if cle:
            self.n += 1
            ident = self.n
            self.attentes[ident] = fin
            self.en_cours[ident] = (texte, fin, langue)
            if suite_de is not None:
                self.enchaine[ident] = suite_de
            for vieux in [i for i in self.enchaine if i < ident - 20]:
                self.enchaine.pop(vieux, None)
            SOUS_TITRES[ident] = {"phrases": _jv.decouper_phrases(texte) or [texte], "k": -1}
            for vieux in sorted(SOUS_TITRES)[:-6]:
                SOUS_TITRES.pop(vieux, None)
            self.parle = True
            if envoyer_voix({"cmd": "dire", "id": ident, "texte": texte, "cle": cle,
                             "lenteur": float(CFG.get("jarvis_lenteur", 0.95))}):
                return ident
            self.attentes.pop(ident, None)
            self.en_cours.pop(ident, None)
        if not self.disponible:
            if fin:
                fin()
            return
        self._par_windows(texte, fin, langue)

    def _par_windows(self, texte, fin, langue):
        JARVIS["sous_titre"] = {"phrases": [texte], "k": -1, "estime": True, "t0": time.time()}
        self.file.append((texte, fin, langue))
        self.signal.set()
        if self.fil is None or not self.fil.is_alive():
            self.fil = threading.Thread(target=self._tourner, daemon=True)
            self.fil.start()

    def rattacher(self, ident, fin):
        """Ce qui doit suivre une phrase DEJA PARTIE (sa premiere phrase, dite
        en avance) : l'ecoute d'apres, la guirlande. Faux si elle est deja
        dite -- a l'appelant de le faire tout de suite."""
        with self.verrou:
            if ident is None or ident not in self.attentes:
                return False
            self.attentes[ident] = fin
            if ident in self.en_cours:
                texte, _, langue = self.en_cours[ident]
                self.en_cours[ident] = (texte, fin, langue)
            return True

    def fini(self, ident, coupe, reste=None, rate=False):
        """`rate` : la voix n'a pas pu le dire (un casque debranche en pleine
        phrase, une synthese en echec). « Silence, puis le carillon d'ecoute
        comme s'il avait repondu » : ce qui n'a pas ete dit passe par la voix
        de Windows, et la suite (l'ecoute d'apres) attend qu'elle l'ait dit ;
        sans elle, une notification le montre et le souci s'affiche."""
        dit = self.en_cours.pop(ident, None)
        if coupe and reste and self.reprise and self.reprise["id"] == ident:
            # a partir de la phrase coupee
            self.reprise["texte"] = (reste + " " + self.reprise.get("apres", "")).strip()
        with self.verrou:
            fin = self.attentes.pop(ident, None)
        if not self.attentes:
            self.parle = False
        if rate and not coupe:
            a_dire = str(reste or (dit[0] if dit else "") or "").strip()
            langue = dit[2] if dit else "fr"
            print("Jarvis : la voix neuronale n'a pas pu parler%s" % (", la voix de Windows reprend"
                                                                      if a_dire and self.disponible else ""))
            if a_dire and self.disponible:
                self._par_windows(a_dire, fin, langue)
                return
            if a_dire:
                n = JARVIS_CROCHETS.get("notifier")
                if n:
                    n("Jarvis", _jv.pour_la_voix(a_dire, 240))
                souci("La voix n'a pas pu parler : sa reponse est dans la notification.")
        if fin and not coupe:
            try:
                fin()
            except Exception:
                pass

    def enfant_perdu(self, redire=False):
        """La voix est tombee en pleine phrase : on ne laisse pas la suite
        (la guirlande, l'ecoute d'apres) attendre une fin qui ne viendra pas.
        `redire` : tombee toute seule (pas arretee expres) -- ce qu'elle avait
        a dire passe par la voix de Windows, et la suite attend qu'il soit dit."""
        attentes, self.attentes = self.attentes, {}
        en_cours = self.en_cours
        self.en_cours, self.reprise = {}, None
        self.parle = False
        # l'oreille ne doit pas croire qu'il parle encore (elle ne cherchait plus son nom)
        envoyer_oreille({"cmd": "parole", "actif": False})
        for ident in sorted(attentes):
            fin = attentes[ident]
            if redire and self.disponible and ident in en_cours:
                texte, _, langue = en_cours[ident]
                self._par_windows(texte, fin, langue)
                continue
            if fin:
                try:
                    fin()
                except Exception:
                    pass

    def rejoindre(self, ident, reste, fin):
        """LA SUITE D'UNE REPONSE dont la premiere phrase est partie en avance
        (`ident`). « Je lui coupe la parole pendant sa premiere phrase, il se
        tait, puis la suite arrive quand meme » : si cette phrase a ete coupee,
        la suite ne se dit pas -- elle rejoint ce qu'il reprendra si personne
        ne parlait (avec la vraie fin : l'ecoute d'apres), et disparait si on
        lui a vraiment parle. Deja reprise (coupe pour rien) : la suite se dit
        derriere la reprise. Rend l'ident derriere lequel dire la suite, ou
        None s'il n'y a rien a dire maintenant."""
        while ident in self.coupes and ident in self.repris:
            ident = self.repris[ident]
        if ident not in self.coupes:
            return ident
        r = self.reprise
        if r and r["id"] == ident:
            r["texte"] = (r["texte"] + " " + reste).strip()
            r["apres"] = (r.get("apres", "") + " " + reste).strip()
            r["fin"] = fin
        return None

    def taire(self, garder=False):
        """Il se tait. `garder` : on vient de lui couper la parole -- on garde
        ce qu'il disait, pour le reprendre si personne ne parlait en fait."""
        self.reprise = None
        if garder and self.en_cours:
            self.coupes.update(self.en_cours)
            for vieux in [i for i in self.coupes if i < self.n - 20]:
                self.coupes.discard(vieux)
                self.repris.pop(vieux, None)
            # la voix dit ses textes dans l'ordre : celui qui sonne est le plus
            # ancien ; ceux qui attendaient, « taire » les jette (sans « fini »)
            # -- sauf la suite de la MEME reponse (sa premiere phrase dite en
            # avance, puis le reste) : elle est reprise derriere, avec ce qui
            # devait suivre la fin.
            ident = min(self.en_cours)
            idents = [ident]
            for i in sorted(self.en_cours):
                if self.enchaine.get(i) == idents[-1]:
                    idents.append(i)
            texte, _, langue = self.en_cours[ident]
            fin = self.en_cours[idents[-1]][1]
            apres = " ".join(self.en_cours[i][0] for i in idents[1:])
            self.reprise = {"id": ident, "texte": (texte + " " + apres).strip(), "apres": apres,
                            "fin": fin, "langue": langue, "t": time.time()}
        self.en_cours.clear()
        self.file.clear()
        self.attentes.clear()
        envoyer_voix({"cmd": "taire"})
        self.couper.set()
        self.parle = False

    def reprendre(self):
        """Reprend ce qu'on lui a coupe (a partir de la phrase coupee), avec la
        meme suite qu'avant -- l'ecoute d'apres, la guirlande."""
        r, self.reprise = self.reprise, None
        if not r or not r.get("texte") or time.time() - r["t"] > 30.0:
            return False
        ident = self.dire(r["texte"], r["fin"], r["langue"])
        if ident is not None:
            self.repris[r["id"]] = ident          # la suite de sa reponse viendra derriere
        return True

    def oublier_reprise(self):
        self.reprise = None

    # Les voix de Windows a essayer, par langue : l'anglais britannique d'abord
    # (809), puis l'americain (409) ; le francais (40C).
    _SAPI_LANGUES = {"fr": ("Language=40C",),
                     "en": ("Language=809;Gender=Male", "Language=409;Gender=Male", "Language=809",
                            "Language=409")}

    def _sapi(self, texte, langue="fr"):
        if self.sapi is None:
            import pythoncom
            import win32com.client
            pythoncom.CoInitialize()
            self.sapi = win32com.client.Dispatch("SAPI.SpVoice")
            self.sapi_voix = {}
            self.sapi_langue = None
        v = self.sapi
        if self.sapi_langue != langue:
            if langue not in self.sapi_voix:
                self.sapi_voix[langue] = None
                for requete in self._SAPI_LANGUES.get(langue, ()):
                    try:
                        trouvees = v.GetVoices(requete)
                        if trouvees.Count:
                            self.sapi_voix[langue] = trouvees.Item(0)
                            break
                    except Exception:
                        pass
            if self.sapi_voix[langue] is not None:
                v.Voice = self.sapi_voix[langue]
            self.sapi_langue = langue
        v.Rate = max(-10, min(10, entier(CFG.get("jarvis_debit", 0), 0)))
        v.Speak(texte, 1)                          # SVSFlagsAsync
        while not v.WaitUntilDone(100):
            if self.couper.is_set():
                v.Speak("", 3)                     # asynchrone + purge
                return False
        return True

    def _tourner(self):
        while True:
            self.signal.wait()
            self.signal.clear()
            while self.file:
                texte, fin, langue = self.file.pop(0)
                self.couper.clear()
                self.parle = True
                dit = True
                noter_temps("voix")
                envoyer_oreille({"cmd": "parole", "actif": True, "nom": nom_dans_sa_voix(texte=texte)})
                try:
                    dit = self._sapi(texte, langue)
                except Exception as e:
                    print("Jarvis : voix de Windows impossible (%s)" % type(e).__name__)
                finally:
                    self.parle = False
                    envoyer_oreille({"cmd": "parole", "actif": False})
                if fin and dit:
                    try:
                        fin()
                    except Exception:
                        pass


VOIX = Voix()


def jouer_son(genre):
    if CFG.get("jarvis_son", True):
        _jv.jouer(genre)


# ---------- le processus de l'oreille ----------

def _commande_oreille(port, secret):
    base = [sys.executable] if FIGE else [sys.executable, os.path.abspath(__file__)]
    return base + [JARVIS_ENFANT_ARG, str(port), secret, dossier_jarvis()]


def config_oreille(cfg):
    auto = bool(cfg.get("jarvis_auto_etalonnage", True))
    manuels = gabarits_jarvis()
    verifier = etat_dictee()["etat"] == "pret"
    _OREILLE["verifier_tout"] = verifier
    return {"cmd": "config", "gabarits": manuels,
            # les facons apprises seul : jamais un reveil direct, toujours verifiees
            "gabarits_auto": gabarits_auto() if auto else [],
            "auto": auto,
            # « SURTOUT QU'IL N'APPARAISSE PAS POUR RIEN » : des que la transcription
            # est prete, un appel qui n'est pas un « Jarvis » tres net est verifie
            # en silence avant qu'il ne se montre
            "verifier_tout": verifier,
            "duree_max": _jv.PHRASE_PSY_MAX_S if JARVIS.get("mode") == "psy" else _jv.PHRASE_MAX_S,
            # CALE SUR TA VOIX : la distance typique entre tes « Jarvis », et leur niveau
            "seuil_perso": _jv.seuil_personnel(manuels),
            "niveau_voix": niveau_voix_appris(),
            "tolerant": bool(cfg.get("jarvis_tolerant", True)),
            "sensibilite": float(cfg.get("jarvis_sensibilite", 0.5)),
            "hey": bool(cfg.get("jarvis_hey", True)),
            "ma_voix": bool(cfg.get("jarvis_ma_voix", True)),
            "son": bool(cfg.get("jarvis_son", True)),
            "couper": bool(cfg.get("jarvis_couper", True)),
            "micro": str(cfg.get("jarvis_micro", "") or ""),
            "micro_nom": str(cfg.get("jarvis_micro_nom", "") or "")}


def retenir_micro(cfg, ident, nom):
    """L'oreille a ouvert le micro choisi : on retient son nom (pour le
    retrouver s'il change d'identifiant), et son nouvel identifiant s'il l'a
    retrouve par son nom -- la page Jarvis le montre alors coche, pas
    « debranche ». Rend True si les reglages ont change."""
    avant = (cfg.get("jarvis_micro"), cfg.get("jarvis_micro_nom"))
    if ident:
        print("Jarvis : le micro choisi a change d'identifiant, retrouve par son nom")
        cfg["jarvis_micro"] = str(ident)
    if nom:
        cfg["jarvis_micro_nom"] = str(nom)[:200]
    if (cfg.get("jarvis_micro"), cfg.get("jarvis_micro_nom")) == avant:
        return False
    sauver_config(cfg)
    return True


def liste_micros():
    """[(identifiant, nom)] des micros branches, sans les boucles des
    haut-parleurs. Vide hors de Windows ou si la liste n'est pas lisible."""
    try:
        import soundcard as sc
        return [(str(m.id), str(m.name)) for m in sc.all_microphones()]
    except Exception:
        return []


def envoyer_oreille(objet):
    sock = _OREILLE["sock"]
    if sock is None:
        return False
    try:
        _jv.envoyer(sock, objet, _OREILLE_VERROU)
        return True
    except Exception:
        return False


def oreille_vivante():
    p = _OREILLE["proc"]
    return p is not None and p.poll() is None and _OREILLE["sock"] is not None


def _lancer_enfant(commande, quoi):
    """Relance cet exe en processus enfant et attend sa poignee de main : un
    secret a usage unique, sur une socket locale. Rend (processus, socket)."""
    srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        srv.bind(("127.0.0.1", 0))
        srv.listen(1)
        srv.settimeout(DICTEE_DEMARRAGE_S)
        secret = secrets.token_hex(16)
        kw = {}
        if os.name == "nt":
            kw["creationflags"] = (getattr(subprocess, "CREATE_NO_WINDOW", 0)
                                   | getattr(subprocess, "BELOW_NORMAL_PRIORITY_CLASS", 0))
        sortie = _JOURNAL if _JOURNAL is not None else None
        proc = subprocess.Popen(commande(srv.getsockname()[1], secret),
                                stdin=subprocess.DEVNULL, stdout=sortie, stderr=sortie, **kw)
        try:
            sock, _ = srv.accept()
        except socket.timeout:
            proc.kill()
            raise RuntimeError("le processus %s n'a pas demarre" % quoi)
        sock.settimeout(30)
        try:
            ok = secrets.compare_digest(_recevoir_trame(sock, 64), secret.encode())
        except Exception:
            ok = False
        if not ok:
            sock.close()
            proc.kill()
            raise RuntimeError("le processus %s n'a pas repondu comme prevu" % quoi)
        sock.settimeout(None)
    finally:
        srv.close()
    return proc, sock


def _fermer_enfant(sock, proc):
    if sock is not None:
        try:
            _envoyer_trame(sock, b"")
        except Exception:
            pass
        try:
            sock.close()
        except Exception:
            pass
    if proc is not None and proc.poll() is None:
        try:
            proc.wait(timeout=3)
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass


OREILLE_MUETTE_S = 25.0      # l'oreille dit son niveau chaque seconde
OREILLE_DEMARRAGE_S = 35.0   # ... sauf le temps de charger ses modeles et d'ouvrir le micro


def oreille_muette(maintenant=None):
    t = time.time() if maintenant is None else maintenant
    return t - float(JARVIS.get("niveau_t") or t) > OREILLE_MUETTE_S


def demarrer_oreille(cfg):
    arreter_oreille()
    JARVIS.update(etat="demarrage", message="Ouverture du micro...")
    JARVIS["niveau_t"] = time.time()
    proc, sock = _lancer_enfant(lambda port, secret: _commande_oreille(port, secret), "du micro")
    # le chien de garde compte a partir d'ICI (l'exe s'est decompresse), et
    # laisse encore aux modeles et au micro le temps de s'ouvrir
    JARVIS["niveau_t"] = time.time() + OREILLE_DEMARRAGE_S
    _OREILLE.update(proc=proc, sock=sock)
    envoyer_oreille(config_oreille(cfg))
    threading.Thread(target=_lire_oreille, args=(sock,), daemon=True).start()


def arreter_oreille():
    sock, proc = _OREILLE["sock"], _OREILLE["proc"]
    _OREILLE.update(sock=None, proc=None)
    _fermer_enfant(sock, proc)


atexit.register(arreter_oreille)


def _lire_oreille(sock):
    while True:
        try:
            ev = _jv.recevoir(sock)
        except Exception:
            ev = None
        if ev is None:
            break
        try:
            traiter_evenement(ev)
        except Exception as e:
            print("Jarvis : evenement non traite (%s: %s)" % (type(e).__name__, str(e)[:120]))
    if _OREILLE["sock"] is sock:
        # Tombe sans qu'on l'ait arrete : on le relance, de plus en plus
        # lentement -- un processus qui meurt au demarrage ne doit pas etre
        # relance chaque seconde (l'exe se decompresse a chaque fois).
        n = _OREILLE["echecs"]
        _OREILLE["echecs"] = n + 1
        _OREILLE["prochain"] = time.time() + JARVIS_RELANCE_S[min(n, len(JARVIS_RELANCE_S) - 1)]
        souci("Le micro s'est arrete ; il repart tout seul.")


# les etats ou il n'est pas en train de te parler : l'oreille qui (re)demarre
# peut y ramener « a l'ecoute »
_ETATS_HORS_CONVERSATION = ("demarrage", "erreur", "eteint", "preparation", "attente", None)


def souci(message):
    """UN SOUCI DE FOND (le micro qui tombe, qui ne repond plus) : dit sur sa
    page et dans le journal -- jamais au panneau. Le panneau rouge « ERROR »
    apparaissait tout seul, et y restait."""
    print("Jarvis : %s" % str(message)[:200])
    JARVIS["souci"] = (str(message or "")[:200], time.time())
    if JARVIS.get("etat") in ("demarrage", "erreur", "preparation"):
        JARVIS.update(etat="attente", message=message_attente())


def traiter_evenement(ev):
    quoi = ev.get("evt")
    if quoi == "pret":
        _OREILLE["echecs"] = 0
        JARVIS["niveau_t"] = time.time()             # le chien de garde repart d'ici
        # (un micro muet le reste quand il se rouvre : seul un vrai son l'efface)
        if not micro_muet_signale():
            JARVIS["souci"] = None
        JARVIS["vad"] = bool(ev.get("vad"))
        # le micro qui se rouvre en pleine conversation ne la coupe pas
        if JARVIS.get("etat") in _ETATS_HORS_CONVERSATION:
            JARVIS.update(etat="attente", message=message_attente())
        if not ev.get("vad") and vad_present():
            envoyer_oreille({"cmd": "vad"})
        # l'oreille demarre : le moteur de transcription se chargera sous peu,
        # avant le premier « Jarvis » (voir entretenir_dictee)
        programmer_prechauffage()
        if "micro" in ev:
            # Le micro qu'il ecoute vraiment -- et s'il n'est pas celui choisi
            # (debranche), on le dit plutot que d'ecouter ailleurs en silence.
            JARVIS["micro"] = str(ev.get("micro") or "")
            JARVIS["micro_absent"] = not ev.get("trouve", True)
            if JARVIS["micro_absent"]:
                print("Jarvis : le micro choisi est introuvable, j'ecoute celui de Windows")
            elif CFG.get("jarvis_micro") and retenir_micro(CFG, ev.get("micro_id"), JARVIS["micro"]) \
                    and ev.get("micro_id"):
                envoyer_oreille(config_oreille(CFG))     # son nouvel identifiant : il le rouvre sous ce nom-la
    elif quoi == "essai" and ev.get("maj"):
        # ce qu'est devenu l'appel pas net en attente de lecture : « lent » (le
        # moteur de transcription demarre), ou tranche au score sans lecture
        for e in reversed(JARVIS.get("essais") or []):
            if e.get("issue") in ("verifier", "lent"):
                e["issue"] = str(ev.get("issue") or "")
                break
        if ev.get("issue") == "lent":
            print("Jarvis : la verification tarde (moteur de transcription froid ?)")
    elif quoi == "essai":
        # L'INDICATEUR DE DETECTION : chaque mot proche de « Jarvis », sa
        # distance, les deux seuils, et ce qui en est sorti
        e = {"d": ev.get("d"), "issue": ev.get("issue"), "direct": ev.get("direct"),
             "verifie": ev.get("verifie"), "t": time.time()}
        JARVIS["essais"] = (list(JARVIS.get("essais") or []) + [e])[-12:]
    elif quoi == "presque":
        # « Jarvis » passe pres du seuil sans le franchir : on le garde pour
        # l'afficher, avec de quoi y remedier.
        JARVIS["presque"] = (float(ev.get("distance") or 0), float(ev.get("seuil") or 0), time.time())
        # quelqu'un vient peut-etre de l'appeler : le moteur se reveille (rien s'il l'est)
        if (CFG.get("jarvis_actif") and dictee_possible() and not moteur_vivant()
                and memoire_pour_garder(charge=False)):
            threading.Thread(target=prechauffer_dictee, daemon=True).start()
    elif quoi == "voix_niveau":
        t = time.time()
        JARVIS["voix_niveau"] = (float(ev.get("v") or 0.0), t)
        # tu parles (une voix, pas un bruit) : il ne compte plus le temps qu'il t'attend
        if JARVIS.get("etat") == "ecoute" and float(ev.get("p") or 0.0) >= _jv.VAD_SEUIL:
            JARVIS["parole_vue"] = t
    elif quoi == "niveau":
        JARVIS["niveau_t"] = time.time()
        JARVIS["db"] = ev.get("db")
        JARVIS["coupure"] = ev.get("coupure")
        suivre_micro_muet(ev.get("db"), JARVIS["niveau_t"])
    elif quoi == "vad":
        JARVIS["vad"] = bool(ev.get("ok"))
    elif quoi == "coupure":
        # ON LUI COUPE LA PAROLE : il se tait net, et l'oreille ecoute deja la
        # suite -- elle fera une phrase comme une autre.
        print("Jarvis : on lui coupe la parole")
        VOIX.taire(garder=True)
        # ce qu'il disait a cet instant : sa voix est au debut de la phrase
        # captee, la transcription l'ecrit (voir `_jv.sans_sa_voix`)
        JARVIS["coupe_contexte"] = contexte_de_coupure()
        poser_led("ecoute")
        JARVIS.update(etat="ecoute", message="Je vous ecoute.", ecoute_fin=0.0, parole_vue=time.time())
        threading.Thread(target=prechauffer_dictee, daemon=True).start()
    elif quoi == "reveil":
        print("Jarvis : eveil (%s%s)" % (ev.get("par"), ", verifie" if ev.get("verifie") else
                                         ", sans lecture : le score a tranche" if ev.get("repli") else ""))
        # UN NOUVEAU TOUR : ce qu'il preparait pour le tour d'avant ne se dira pas
        JARVIS["tour"] = int(JARVIS.get("tour") or 0) + 1
        VOIX.taire()
        if etat_dictee()["etat"] != "pret":
            # RIEN NE POURRA ETRE TRANSCRIT (le modele se telecharge, ou a rate) :
            # il ne t'invite pas a parler dans le vide -- il dit ou il en est
            envoyer_oreille({"cmd": "annuler"})
            return dire_transcription_indisponible(langue_du_mode())
        mode_courant()
        # « Quand Jarvis s'allume, il doit toujours etre en mode Jarvis (meme
        # s'il etait en psychologue avant). » La seance continue tant qu'on se
        # repond sans le rappeler ; l'appeler, c'est revenir au majordome.
        JARVIS["reveil_par"] = ev.get("par")
        JARVIS["reveil_verifie"] = bool(ev.get("verifie"))
        poser_mode("jarvis")
        JARVIS.update(suite_active=False, attente_code=None, entendu="", fait_jusqua=0.0)
        if ev.get("deja_fini"):
            # « Jarvis, allume la lumiere » dit d'une traite pendant qu'il
            # verifiait l'appel : il n'ecoute plus, il lit
            poser_led("comprend")
            JARVIS.update(etat="comprend", message="Je transcris...", ecoute_fin=0.0)
        else:
            attente = max(1.0, float(ev.get("attente") or 5.0))
            poser_led("ecoute")
            JARVIS.update(etat="ecoute", message="Je vous ecoute.", ecoute_fin=time.time() + attente,
                          ecoute_duree=attente, parole_vue=0.0)
        # la lumiere de la routine du reveil -- APRES l'ecoute ouverte : sa
        # replique ne se dit pas par-dessus la demande qui commence
        declencher_routines("evenement", "reveil", CFG)
        # Le moteur de transcription se reveille PENDANT qu'on parle : sa
        # premiere phrase apres un long silence ne paie pas son chargement.
        threading.Thread(target=prechauffer_dictee, daemon=True).start()
    elif quoi == "vide":
        # Personne n'a parle apres la coupure (un clavier, une porte) : il
        # reprend sa phrase -- l'oreille, elle, a deja appris que c'etait de l'echo.
        if ev.get("apres_coupure") and reprendre_apres_coupure():
            return
        if (JARVIS.get("suspens") or {}).get("coupe") and JARVIS["etat"] == "ecoute":
            # « Attends... » dit par-dessus lui, et rien n'a suivi : il reprend
            JARVIS["suspens"] = None
            if reprendre_apres_coupure():
                return
            return fin_de_l_ecoute()
        if JARVIS.get("suspens") and JARVIS["etat"] == "ecoute":
            # sa phrase en suspens, et rien n'a suivi : elle part telle quelle
            JARVIS["ecoute_fin"] = 0.0
            _JARVIS_TRAVAIL.append({"wav": None, "tour": JARVIS.get("tour")})
            _JARVIS_TRAVAIL_SIGNAL.set()
            return
        if JARVIS["etat"] == "ecoute":
            # personne n'a rien ajoute : il se rendort -- et un son le dit
            # (« je n'ecoute plus »), comme un carillon avait dit qu'il ecoutait
            fin_de_l_ecoute()
    elif quoi == "phrase":
        # IL N'ECOUTE PLUS : ca se voit tout de suite (l'oreille a joue son petit son)
        noter_temps("phrase", ev.get("pause"), ev.get("fin_t"))
        # (la fin prevue de la fenetre de suite est gardee : si ce n'etait que
        # la queue de sa voix, il ecoute encore le temps qui restait)
        JARVIS["ecoute_avant"] = (float(JARVIS.get("ecoute_fin") or 0.0)
                                  if JARVIS.get("etat") == "ecoute" and JARVIS.get("suite_active") else 0.0)
        JARVIS["ecoute_fin"] = 0.0
        a = JARVIS.get("avance")
        if (ev.get("apres_coupure") and not ev.get("breve") and a and not a.get("fini")
                and a.get("id") in VOIX.coupes and a.get("tour") == JARVIS.get("tour")):
            # ON LUI A VRAIMENT PARLE par-dessus sa premiere phrase (des mots,
            # pas un bruit bref) : la reponse qu'il attendait encore n'est plus
            # la question -- il n'attend plus BrainDebugger pour t'ecouter
            a["interrompue"] = True
        if JARVIS.get("etat") in ("ecoute", "attente"):
            poser_led("comprend")
            JARVIS.update(etat="comprend", message="Je transcris...")
        _JARVIS_TRAVAIL.append({"wav": ev.get("wav") or "", "apres_coupure": bool(ev.get("apres_coupure")),
                                "deja_dit": bool(ev.get("deja_dit")), "breve": bool(ev.get("breve")),
                                "avec_debut": bool(ev.get("avec_debut")), "tour": JARVIS.get("tour")})
        _JARVIS_TRAVAIL_SIGNAL.set()
    elif quoi == "gabarit":
        _GABARIT_RECU["evt"] = ev
        _GABARIT_RECU["signal"].set()
    elif quoi == "verifier":
        # UN « JARVIS » PAS NET : l'oreille ecoute en silence ; on transcrit ces
        # quelques secondes, et il ne se reveille que si on y lit son nom
        threading.Thread(target=verifier_appel, args=(ev.get("wav") or "", ev.get("n")), daemon=True).start()
    elif quoi == "gabarit_auto":
        # un appel qu'il avait rate de peu, puis une vraie conversation : il le
        # gardera -- SI la transcription de la phrase contient bien son nom
        # (voir traiter_phrase). Sans ce controle, un bruit suivi de n'importe
        # quoi devenait « une facon de l'appeler », et chaque bruit pareil le
        # reveillait ensuite.
        JARVIS.setdefault("auto_en_attente", []).append(ev.get("vecteurs"))
        del JARVIS["auto_en_attente"][:-4]
    elif quoi == "erreur":
        # un souci de l'oreille (le micro) : sur sa page, pas au panneau
        souci(ev.get("message"))


def fin_de_l_ecoute():
    """La fenetre d'ecoute se referme sans que personne n'ait parle."""
    JARVIS.update(suite_active=False, ecoute_fin=0.0, attente_code=None)
    jouer_son("fin")
    poser_led(None)
    if JARVIS.get("mode") == "psy":
        # la seance ne continue pas dans le silence : le prochain appel est
        # pour le majordome (et la page ne dit plus « mode psychologue »)
        poser_mode("jarvis")
        JARVIS.update(psy_echange=[], psy_grave=False)
    JARVIS.update(etat="attente", message=message_attente())


def consigne_ecouter(attente, mode=None, **plus):
    """L'ordre « ecouter » pour l'oreille, selon le mode : le psychologue
    laisse des phrases plus longues ET plus de silence avant de conclure."""
    psy = (mode or JARVIS.get("mode")) == "psy"
    c = {"cmd": "ecouter", "attente": attente, "duree_max": _jv.PHRASE_PSY_MAX_S if psy else _jv.PHRASE_MAX_S}
    if psy:
        c["pause"] = _jv.PHRASE_PSY_PAUSE_S
    c.update(plus)
    return c


REVEIL_CLAVIER_ATTENTE_S = 6.0


def reveil_au_clavier(cfg=None, attendre_oreille_s=10.0, note=False):
    """« Ctrl+J n'allume rien, j'entends juste le bruit de notif » : le
    raccourci basculait la case « Jarvis ecoute ». Il fait maintenant ce que
    fait son nom dit a voix haute : Jarvis se reveille et t'ecoute -- et s'il
    est deja en train d'ecouter, de reflechir ou de parler, il se tait (un
    second appui congedie). Eteint, il s'allume d'abord. Rend ce qu'il a fait.

    `note` (Ctrl+Maj+Espace) : « il faut que control shift espace remplisse un
    systeme de notes, pour inscrire on the fly des infos sur BrainDebugger ».
    Ce qui est dit ensuite part au carnet tel quel, et Jarvis y repond (voir
    `noter_et_repondre`). Il ecoute comme le psychologue : plus long, plus de
    silence avant de conclure."""
    cfg = CFG if cfg is None else cfg
    # en pleine conversation (pas pendant qu'il ouvre le micro : la, on l'attend)
    if JARVIS.get("etat") in ("ecoute", "comprend", "pense", "parle") or JARVIS.get("mode") == "psy":
        print("Jarvis : raccourci clavier -- il se tait")
        terminer_conversation()
        return "congedie"
    if not cfg.get("jarvis_actif"):
        cfg["jarvis_actif"] = True
        sauver_config(cfg)
        REGLAGES_A_RELIRE.add("jarvis_actif")
    # l'oreille demarre avec la veille de Jarvis : on lui laisse un instant
    fin = time.time() + attendre_oreille_s
    while not oreille_vivante() and time.time() < fin:
        time.sleep(0.2)
    if not oreille_vivante():
        print("Jarvis : raccourci clavier -- l'oreille ne repond pas")
        return "sans_oreille"
    if etat_dictee()["etat"] != "pret":
        return dire_transcription_indisponible(langue_du_mode()) or "sans_dictee"
    print("Jarvis : eveil (clavier)")
    JARVIS["tour"] = int(JARVIS.get("tour") or 0) + 1
    VOIX.taire()
    mode_courant()
    poser_mode("jarvis")
    # pas de nom a reconnaitre dans ce qui suit : c'est toi qui l'as appele
    JARVIS.update(reveil_par="clavier", reveil_verifie=True, suite_active=True, attente_code=None,
                  entendu="", fait_jusqua=0.0, note_tour=JARVIS["tour"] if note else None)
    poser_led("ecoute")
    JARVIS.update(etat="ecoute", message="Je note." if note else "Je vous ecoute.",
                  ecoute_fin=time.time() + REVEIL_CLAVIER_ATTENTE_S,
                  ecoute_duree=REVEIL_CLAVIER_ATTENTE_S, parole_vue=0.0)
    jouer_son("eveil")
    envoyer_oreille(consigne_ecouter(REVEIL_CLAVIER_ATTENTE_S, mode="psy" if note else "jarvis"))
    declencher_routines("evenement", "reveil", cfg)
    threading.Thread(target=prechauffer_dictee, daemon=True).start()
    return "reveille"


def reecouter_la_suite():
    """« JE VOUS ECOUTE ENCORE UN INSTANT » -- et il se rendormait 1,5 s plus
    tard : la fin de sa voix (une enceinte en retard, l'echo), pas un mot de
    toi, avait ferme l'ecoute. Tant qu'il reste du temps a la fenetre de
    suite, il ecoute encore ce temps-la, sans carillon."""
    jusqua = float(JARVIS.get("ecoute_avant") or 0.0)
    reste = jusqua - time.time()
    if reste < 1.0 or not oreille_vivante():
        return False
    JARVIS["ecoute_avant"] = 0.0
    print("Jarvis : rien de toi dans ce qu'il a entendu, il ecoute encore %.1f s" % reste)
    poser_led("ecoute")
    JARVIS.update(etat="ecoute", message="Je vous ecoute encore un instant.", suite_active=True,
                  ecoute_fin=jusqua, ecoute_duree=reste, parole_vue=0.0)
    envoyer_oreille(consigne_ecouter(round(reste, 2), ignorer=0.0))
    return True


def contexte_de_coupure():
    """La phrase qu'il disait quand on l'a coupe, et celle d'avant."""
    r = VOIX.reprise
    if not r:
        return ""
    st = SOUS_TITRES.get(r.get("id"))
    if not st:
        return str(r.get("texte") or "")[:400]
    phrases, k = list(st.get("phrases") or []), int(st.get("k", -1))
    return " ".join(phrases[max(0, k - 1):k + 1] if k >= 0 else phrases[:2])


# « IL NE M'ENTEND PLUS » : la confidentialite de Windows qui refuse le micro
# aux applications, une touche « micro coupe » -- le micro ne rend que des
# zeros. La page montrait « -90 dB » sans rien dire. Un indice, pas une erreur :
# certains pilotes antibruit rendent aussi des zeros dans une piece calme.
MICRO_MUET_DB = -90.0
MICRO_MUET_S = 30.0
MICRO_MUET_MESSAGE = ("Le micro ne rend que du silence : coupe, ou acces refuse "
                      "(Parametres > Confidentialite > Microphone).")
# « Jarvis n'est plus detecte, et le micro non plus » : le micro choisi
# introuvable, il ecoutait celui de Windows -- muet. Le dire tel quel.
MICRO_ABSENT_MESSAGE = ("Le micro choisi est introuvable, et celui de Windows ne rend que du silence : "
                        "choisis-le de nouveau dans « le micro », plus bas.")


def micro_muet_signale():
    return (JARVIS.get("souci") or ("",))[0] in (MICRO_MUET_MESSAGE, MICRO_ABSENT_MESSAGE)


def suivre_micro_muet(db, maintenant):
    """Chaque niveau du micro : trente secondes de zeros exacts, on le dit ;
    le premier vrai son l'efface."""
    try:
        db = float(db)
    except (TypeError, ValueError):
        return
    if db <= MICRO_MUET_DB:
        debut = JARVIS.get("muet_depuis") or maintenant
        JARVIS["muet_depuis"] = debut
        if maintenant - debut >= MICRO_MUET_S and not micro_muet_signale():
            souci(MICRO_ABSENT_MESSAGE if JARVIS.get("micro_absent") else MICRO_MUET_MESSAGE)
    else:
        JARVIS["muet_depuis"] = None
        if micro_muet_signale():
            JARVIS["souci"] = None


def verifier_appel(wav64, n=None):
    """Tranche un appel pas net : « Jarvis » (meme ecorche) dans la
    transcription -> il se reveille ; sinon, il se rendort sans un bruit.

    Trois reponses : oui, non, et « illisible » (None : transcription pas
    prete, memoire, moteur qui plante) -- alors l'oreille laisse le score
    trancher. Un « non » sans avoir rien lu rejetait tout appel pas net, sans
    un mot. Rend True seulement si on y a lu son nom."""
    ok, lu = None, None
    try:
        if etat_dictee()["etat"] == "pret":
            texte = transcrire(base64.b64decode(wav64))
            # « J'AI GALERE A CE QU'IL S'ALLUME » : un « Jarvis » dit seul,
            # Parakeet l'ecrit « Javi », « Chavis », « É Javi » -- la forme
            # ecorchee confirme un appel que l'empreinte a deja trouve proche
            lu = _jv.nom_verifie(texte, noms_appris())
            # parler DE lui (« j'ai l'impression que Jarvis ecoute ») n'est pas
            # l'appeler ; le bout de son finit juste apres le nom (« Jarvis il »)
            ok = lu is not None and not _jv.est_une_mention(texte, noms_appris(), tronque=True)
    except Exception as e:
        print("Jarvis : verification impossible (%s)" % type(e).__name__)
    # le mot qui l'a confirme, pour comprendre un reveil intempestif (pas la phrase)
    print("Jarvis : appel pas net %s" % ("illisible : le score tranche" if ok is None else
                                         "confirme (« %s »)" % lu if ok else
                                         "ecarte" + (" (on parlait de lui)" if lu else "")))
    if ok is not None:
        for e in reversed(JARVIS.get("essais") or []):
            if e.get("issue") in ("verifier", "lent"):
                e["issue"] = "confirme" if ok else "ecarte"
                break
    verdict = {"cmd": "verifie", "ok": ok}
    if n is not None:
        verdict["n"] = n
    envoyer_oreille(verdict)
    return bool(ok)


def garder_facons(transcription):
    """Les facons de l'appeler en attente ne sont gardees que si on a
    vraiment dit son nom dans cette phrase."""
    attente, JARVIS["auto_en_attente"] = list(JARVIS.get("auto_en_attente") or []), []
    if not attente or not _jv.contient_nom(transcription, noms_appris()):
        return 0
    n = 0
    for v in attente:
        try:
            n += 1 if ajouter_gabarit_auto(v) else 0
        except Exception as e:
            print("Jarvis : facon non gardee (%s)" % type(e).__name__)
    if n:
        print("Jarvis : %d facon(s) de plus de l'appeler, gardee(s) seul (%d)" % (n, len(gabarits_auto())))
        envoyer_oreille(config_oreille(CFG))
    return n


# les facons apprises seul avant les controles de la v1.58, puis pendant que
# les « noms appris » etaient pollues (v1.59-1.60 : n'importe quel mot d'une
# phrase de calibration confirmait un appel) : effacees une fois
AUTO_PURGE_VERSION = 161


def purger_facons_douteuses(cfg):
    """« Il se declenche tout seul des qu'il y a un bruit. » Les facons
    apprises seul avant la v1.58 ont pu etre des bruits : on les efface, une
    fois ; celles que TU lui as apprises restent."""
    if int(cfg.get("jarvis_auto_purge") or 0) >= AUTO_PURGE_VERSION:
        return False
    n = len(gabarits_auto())
    if n:
        _ecrire_voix(gabarits_jarvis(), [])
        print("Jarvis : %d facon(s) apprise(s) seul effacee(s) (elles ont pu etre du bruit)" % n)
    cfg["jarvis_auto_purge"] = AUTO_PURGE_VERSION
    sauver_config(cfg)
    return True


def reprendre_apres_coupure():
    """On lui avait coupe la parole pour rien : il reprend ou il en etait."""
    if not VOIX.reprise:
        return False
    print("Jarvis : coupe pour rien, il reprend")
    fin, tour = VOIX.reprise.get("fin"), JARVIS.get("tour")

    def puis():
        # un minuteur, une annonce -- ou sa premiere phrase, dite en avance, dont
        # la suite ne viendra plus : rien ne le remettait « a l'ecoute » apres,
        # et il restait « parle » pour toujours
        if fin:
            fin()
        if JARVIS.get("etat") == "parle" and JARVIS.get("tour") == tour:
            poser_led(None)
            JARVIS.update(etat="attente", message=message_attente())
    VOIX.reprise["fin"] = puis
    poser_led("parle")
    JARVIS.update(etat="parle", message="Je reprends.")
    if VOIX.reprendre():
        return True
    poser_led(None)
    JARVIS.update(etat="attente", message=message_attente())
    return False


def message_attente():
    if gabarits_jarvis():
        return "A l'ecoute : dis « Jarvis »."
    if CFG.get("jarvis_hey", True):
        return ("A l'ecoute : dis « Hey Jarvis » (a l'anglaise). Pour « Jarvis » tout "
                "seul, apprends-lui ta voix.")
    return "Apprends-lui ta voix pour qu'il reconnaisse « Jarvis »."


# LE GARDE-FOU DES ETATS. « Il reste bloque sur "il reflechit" jusqu'a ce que
# je redise Jarvis » : un etat ecrit trop tard (la reponse d'un tour d'avant,
# un « fini » que la voix n'enverra jamais) restait affiche pour toujours --
# et bloquait les annonces. Un etat qui n'a plus de raison d'etre depuis
# quelques secondes revient a l'attente.
GARDE_ETATS_S = {"parle": 4.0, "pense": 10.0, "comprend": 10.0}
_GARDE = {"cle": None, "depuis": 0.0, "sans_raison": None}


def raison_d_etre(etat):
    """Quelque chose justifie-t-il encore cet etat ?"""
    if voix_occupee():
        return True                       # il parle, ou il a encore a dire
    if etat == "parle":
        return False
    # pense / comprend : une phrase en file, en travail, ou une requete en cours
    # (une requete abandonnee qui traine encore ne compte pas)
    return bool(_JARVIS_TRAVAIL or _TRAVAIL_COURANT.get("tour") is not None
                or any(not v.get("annule") for v in list(_EN_VOL.values())))


def surveiller_etats(maintenant=None):
    """Appele chaque seconde par la veille. Rend True s'il a remis l'attente."""
    maintenant = time.monotonic() if maintenant is None else maintenant
    etat = JARVIS.get("etat")
    cle = (etat, JARVIS.get("message"), JARVIS.get("tour"))
    if cle != _GARDE["cle"]:
        # un etat qui vient d'etre ecrit a toujours sa chance
        _GARDE.update(cle=cle, depuis=maintenant, sans_raison=None)
        return False
    delai = GARDE_ETATS_S.get(etat)
    if delai is None:
        return False
    if raison_d_etre(etat):
        _GARDE["sans_raison"] = None
        return False
    if _GARDE["sans_raison"] is None:
        _GARDE["sans_raison"] = maintenant
    if maintenant - _GARDE["sans_raison"] < delai:
        return False
    print("Jarvis : garde-fou -- « %s » sans raison depuis %d s, retour a l'attente" % (etat, delai))
    clore_temps("coince")
    poser_led(None)
    JARVIS.update(etat="attente", message=message_attente())
    _GARDE.update(cle=None, sans_raison=None)
    return True


def veiller_sur_jarvis(cfg):
    """Tourne dans son fil : tient l'oreille ouverte quand on l'a demande,
    la ferme sinon, et la relance si elle tombe (de plus en plus lentement)."""
    try:
        purger_facons_douteuses(cfg)
    except Exception as e:
        print("Jarvis : purge impossible (%s)" % e)
    while ETAT["en_marche"]:
        try:
            voulu = bool(cfg.get("jarvis_actif", False))
            vivant = oreille_vivante()
            if voulu and not vivant and time.time() >= _OREILLE["prochain"]:
                if not modeles_jarvis_prets():
                    JARVIS.update(etat="preparation", message="Telechargement du mot d'eveil (3,6 Mo)...")
                    if not preparer_jarvis():
                        _OREILLE["prochain"] = time.time() + 60
                        continue
                if (cfg.get("jarvis_voix", True) and voix_choisie(cfg) != "windows"
                        and PIPER["etat"] in ("absent",) and not piper_pret(cfg)):
                    threading.Thread(target=preparer_piper, args=(cfg,), daemon=True).start()
                if dictee_possible() and etat_dictee()["etat"] == "absent":
                    # La transcription est celle de la dictee : on la prepare
                    # (reprise de Handy, ou telechargement unique de 456 Mo).
                    threading.Thread(target=preparer_dictee, daemon=True).start()
                try:
                    demarrer_oreille(cfg)
                except Exception as e:
                    n = _OREILLE["echecs"]
                    _OREILLE["echecs"] = n + 1
                    _OREILLE["prochain"] = time.time() + JARVIS_RELANCE_S[min(n, len(JARVIS_RELANCE_S) - 1)]
                    souci("Micro indisponible : %s" % str(e)[:120])
            elif not voulu and (vivant or _OREILLE["proc"] is not None):
                arreter_oreille()
                VOIX.taire()
                poser_led(None)
                JARVIS.update(etat="eteint", message="")
            elif voulu and vivant and oreille_muette():
                # « AU BOUT D'UN MOMENT IL NE SE DETECTE PLUS » : l'oreille vit
                # mais ne dit plus rien (un micro bloque dans le pilote) ; elle
                # n'entend plus rien ni ne lit ses commandes. On la relance.
                print("Jarvis : l'oreille ne donne plus signe de vie depuis %d s, je la relance"
                      % (time.time() - float(JARVIS.get("niveau_t") or 0)))
                arreter_oreille()
                n = _OREILLE["echecs"]
                _OREILLE["echecs"] = n + 1
                _OREILLE["prochain"] = time.time() + (2 if not n else
                                                      JARVIS_RELANCE_S[min(n, len(JARVIS_RELANCE_S) - 1)])
                souci("Le micro ne repondait plus ; il repart.")
            elif voulu and not vivant and _OREILLE["proc"] is not None:
                # Tombe en route : on nettoie, la prochaine boucle relance.
                arreter_oreille()
                n = _OREILLE["echecs"]
                _OREILLE["echecs"] = n + 1
                _OREILLE["prochain"] = time.time() + JARVIS_RELANCE_S[min(n, len(JARVIS_RELANCE_S) - 1)]
            elif voulu and vivant:
                # la transcription vient d'etre prete (ou ne l'est plus) : l'oreille
                # verifie les appels douteux en consequence
                if (etat_dictee()["etat"] == "pret") != bool(_OREILLE.get("verifier_tout")):
                    envoyer_oreille(config_oreille(cfg))
                if not vad_present() and time.time() - _VAD["essaye"] > 6 * 3600:
                    _VAD["essaye"] = time.time()
                    threading.Thread(target=preparer_vad, daemon=True).start()
                veiller_sur_la_transcription(cfg)
            if not voulu and JARVIS["etat"] != "eteint" and _OREILLE["proc"] is None:
                JARVIS.update(etat="eteint", message="")
            if voulu:
                surveiller_etats()
            # une tache de fond prete : il l'annonce des qu'il est libre (sans
            # attendre la guirlande, qui peut ne pas etre branchee)
            try:
                veiller_resume_du_jour(cfg)  # le PC vient de demarrer : sa premiere minute d'activite
                dire_les_annonces()
                annoncer_taches(cfg)
            except Exception as e:
                print("Jarvis : annonce impossible (%s)" % e)
            veiller_initiatives(cfg)         # ses petites initiatives (et le « oui ? » qui expire)
            # LA VOIX : un processus a part, ses voix chargees tant qu'il ecoute.
            # Relancee si elle tombe, rechargee si on en change.
            veut_voix = voulu and cfg.get("jarvis_voix", True)
            # La voix anglaise se telecharge des qu'elle manque, pas seulement
            # au demarrage de l'oreille : passer Jarvis en anglais la fait venir.
            if (veut_voix and kokoro_voulu(cfg) and KOKORO["etat"] == "absent"
                    and not kokoro_present()):
                KOKORO["etat"] = "preparation"
                threading.Thread(target=preparer_kokoro, args=(cfg,), daemon=True).start()
            charges = charges_voix(cfg) if veut_voix else []
            if charges and time.time() >= _VOIX_ENFANT["prochain"] and (
                    _VOIX_ENFANT["proc"] is None or _VOIX_ENFANT["proc"].poll() is not None
                    or _VOIX_ENFANT["charge"] != signature_voix(charges)):
                try:
                    demarrer_voix(cfg)
                except Exception as e:
                    n = _VOIX_ENFANT["echecs"]
                    _VOIX_ENFANT.update(echecs=n + 1, prochain=time.time()
                                        + JARVIS_RELANCE_S[min(n, len(JARVIS_RELANCE_S) - 1)])
                    print("Jarvis : voix neuronale impossible (%s)" % e)
            elif not charges and _VOIX_ENFANT["proc"] is not None:
                arreter_voix()
        except Exception as e:
            print("Jarvis : veille (%s)" % e)
        time.sleep(1.0)


def fil_jarvis_travail(cfg):
    """Les phrases, une a la fois, dans l'ordre."""
    while ETAT["en_marche"]:
        _JARVIS_TRAVAIL_SIGNAL.wait(1.0)
        _JARVIS_TRAVAIL_SIGNAL.clear()
        while _JARVIS_TRAVAIL:
            item = _JARVIS_TRAVAIL.pop(0)
            _TRAVAIL_COURANT.update(tour=item.get("tour"), t=time.monotonic())
            if item.get("wav"):
                lancer_onglets(cfg)          # pendant la transcription (voir `onglets_attendus`)
            try:
                traiter_phrase(item["wav"], cfg, item.get("apres_coupure", False), deja_dit=item.get("deja_dit", False),
                               breve=item.get("breve", False), tour=item.get("tour"),
                               avec_debut=item.get("avec_debut", False))
                if not voix_occupee():
                    clore_temps("sans voix")   # un son, une commande muette, une phrase en suspens
            except Annule:
                clore_temps("annule")        # congedie ou rappele pendant qu'il y pensait
            except Exception as e:
                print("Jarvis : phrase non traitee (%s)" % type(e).__name__)
                signaler_erreur(phrase("rate", langue_du_mode(cfg)), detail="phrase non traitee : %s" % type(e).__name__)
            finally:
                _TRAVAIL_COURANT.update(tour=None, t=time.monotonic())


# ce que traite le fil de travail (tour, depuis quand) : le garde-fou des etats
# sait ainsi qu'un « pense » a encore une raison d'etre
_TRAVAIL_COURANT = {"tour": None, "t": 0.0}


def voix_occupee():
    """Dit-il quelque chose, ou a-t-il quelque chose a dire ?"""
    return bool(VOIX.parle or VOIX.attentes or getattr(VOIX, "file", None))


def demarrer_jarvis(cfg):
    threading.Thread(target=veiller_sur_jarvis, args=(cfg,), daemon=True).start()
    threading.Thread(target=fil_jarvis_travail, args=(cfg,), daemon=True).start()


# ---------- ce qu'on fait d'une phrase ----------

def prechauffer_dictee():
    """Charge le moteur de transcription s'il dort, avec une phrase de
    silence (qui ne rend rien). Ne fait rien s'il est deja la."""
    if etat_dictee()["etat"] != "pret":
        return
    with _DICTEE_VERROU:
        if _MOTEUR["proc"] is not None and _MOTEUR["proc"].poll() is None:
            return
        try:
            sock = _moteur_vivant()
            silence = _jv.wav_de(__import__("numpy").zeros(int(_jv.FREQ * 0.4), dtype="int16"))
            sock.settimeout(_delai_reponse(0.4))
            _envoyer_trame(sock, silence)
            _recevoir_trame(sock)
            _MOTEUR["vu"] = time.time()
            _moteur_charge()
        except Exception as e:
            print("Jarvis : prechauffage impossible (%s)" % type(e).__name__)
            _arreter_moteur()
            return
    _programmer_dechargement()


# ---------- la porteuse : la langue des reponses d'un mot ----------
#
# « Non » transcrit « Não », « Ouais » transcrit « Wait » (voir
# jarvis.reconnaitre) : une phrase dite par SA voix francaise, rendue une fois
# en memoire par le processus de la voix, ancre la langue. Jamais sur le disque.

PORTEUSE_TEXTE = {"fr": "Je vous écoute."}
PORTEUSE_REDEMANDE_S = 60
_PORTEUSE = {"fr": None, "demande": 0.0}


def porteuse_pour(langue):
    """Le WAV de la porteuse de cette langue, rendu par la voix chargee en ce
    moment -- ou None (pas de voix neuronale, ou pas encore rendue)."""
    p = _PORTEUSE.get(langue) if langue in PORTEUSE_TEXTE else None
    if p and p.get("sig") and p["sig"] == _VOIX_ENFANT.get("charge"):
        return p["wav"]
    return None


def demander_porteuse(maintenant=None):
    """La voix francaise est chargee et la porteuse manque (ou vient d'une
    voix d'avant) : on la demande -- quand Jarvis ne fait rien, pour ne pas
    retarder une reponse. La voix peut la perdre (« taire » vide sa file) :
    on redemande, au plus une fois par minute."""
    t = time.time() if maintenant is None else maintenant
    if porteuse_pour("fr") is not None or not voix_prete("fr"):
        return False
    if JARVIS.get("etat") != "attente" or t - _PORTEUSE["demande"] < PORTEUSE_REDEMANDE_S:
        return False
    _PORTEUSE["demande"] = t
    return envoyer_voix({"cmd": "rendre", "id": "porteuse", "cle": "fr", "texte": PORTEUSE_TEXTE["fr"]})


def recevoir_porteuse(ev):
    """Le processus de la voix rend la porteuse (evenement « rendu »)."""
    cle = str(ev.get("cle") or "")
    if cle not in PORTEUSE_TEXTE or not ev.get("wav"):
        return False
    try:
        wav = base64.b64decode(ev["wav"])
        if entete_wav(wav)[1] != _jv.FREQ:
            return False
    except Exception:
        return False
    _PORTEUSE[cle] = {"wav": wav, "sig": _VOIX_ENFANT.get("charge")}
    return True


def transcrire_phrase(octets, langue):
    """transcrire, avec la porteuse de la langue quand on l'a."""
    p = porteuse_pour(langue)
    return transcrire(octets, porteuse=p) if p else transcrire(octets)


# ---------- quand la transcription n'est pas la ----------
#
# « Un telechargement rate, et Jarvis est sourd pour de bon. » Le modele de
# la dictee (456 Mo) peut rater sa venue (un reseau qui flanche) : rien ne
# reessayait tant que Machi Tool tournait, et Jarvis ne le disait qu'une
# fois -- ensuite chaque appel sonnait, on parlait dans le vide, et rien.

DICTEE_RELANCES_S = (60, 5 * 60, 30 * 60)
DICTEE_DIRE_S = 120                  # l'etat de la transcription, dit au plus toutes les 2 min
_DICTEE_RELANCE = {"prochain": 0.0, "n": 0}


def relancer_dictee_si_ratee(maintenant=None, lancer=None):
    """La preparation du modele a echoue : on la retente apres 1 min, puis 5,
    puis toutes les 30. Rend True si un essai part."""
    t = time.time() if maintenant is None else maintenant
    if not dictee_possible() or DICTEE.get("etat") != "erreur":
        if DICTEE.get("etat") == "pret":
            _DICTEE_RELANCE.update(prochain=0.0, n=0)
        return False
    if not _DICTEE_RELANCE["prochain"]:
        _DICTEE_RELANCE["prochain"] = t + DICTEE_RELANCES_S[0]
        return False
    if t < _DICTEE_RELANCE["prochain"]:
        return False
    n = _DICTEE_RELANCE["n"] = _DICTEE_RELANCE["n"] + 1
    _DICTEE_RELANCE["prochain"] = t + DICTEE_RELANCES_S[min(n, len(DICTEE_RELANCES_S) - 1)]
    print("Dictee : nouvel essai de preparation (%d)" % n)
    (lancer or (lambda f: threading.Thread(target=f, daemon=True).start()))(preparer_dictee)
    return True


def etat_de_la_transcription(langue):
    """Ce qu'il dit quand on l'appelle et qu'il ne peut pas transcrire."""
    d = etat_dictee()
    if d.get("etat") == "preparation":
        return phrase("transcription_telecharge", langue, int(round(float(d.get("progres") or 0) * 100)))
    if d.get("etat") == "erreur":
        return phrase("transcription_reessaie", langue)
    return phrase("transcription_absente", langue)


def veiller_sur_la_transcription(cfg):
    """A chaque tour de veille, l'oreille ouverte : un modele rate se retente,
    le moteur se precharge ou s'entretient, la porteuse se demande."""
    for f in (relancer_dictee_si_ratee, lambda: entretenir_dictee(cfg), demander_porteuse):
        try:
            f()
        except Exception as e:
            print("Jarvis : transcription, veille (%s)" % type(e).__name__)


def dire_transcription_indisponible(langue, tour=None, maintenant=None):
    """Il ne peut pas transcrire : il le dit (au plus toutes les deux minutes ;
    entre-temps, le son d'erreur et le panneau)."""
    t = time.time() if maintenant is None else maintenant
    texte = etat_de_la_transcription(langue)
    if t - float(JARVIS.get("dictee_dite") or 0.0) >= DICTEE_DIRE_S:
        JARVIS["dictee_dite"] = t
        return signaler_erreur(texte, tour)
    poser_led("erreur", 1.6)
    jouer_son("erreur")
    JARVIS["erreur_jusqua"] = t + ERREUR_MONTREE_S
    JARVIS.update(etat="attente", message=texte)


