def langue_du_mode(cfg=None):
    """Le mode psy parle francais ; le majordome, la langue choisie."""
    return "fr" if JARVIS.get("mode") == "psy" else langue_jarvis(cfg if cfg is not None else CFG)


def phrase(cle, langue, *args):
    fr, en = _PHRASES[cle]
    t = en if langue == "en" and en else fr
    return t % args if args else t


SOUVENIRS_MAX = 40          # gardes sur le PC
SOUVENIRS_ENVOYES = 20      # envoyes avec chaque question
SOUVENIR_SIGNES = 700       # un souvenir garde les details : quelques phrases
# « Fais en sorte que Jarvis se souvienne beaucoup mieux des conversations
# passees » : la conversation en cours part en entier (40 repliques), et
# BrainDebugger y joint le fil des dernieres heures -- eteint, relance ou
# interrompu, il reprend ou vous en etiez.
HISTORIQUE_JARVIS = 40


def _en_fond(f):
    threading.Thread(target=f, daemon=True).start()


def resumer_conversation(historique, cfg):
    """Une phrase sur la conversation qui vient de finir, ecrite par
    BrainDebugger, gardee dans la config. Rien si c'etait une commande, un
    bonjour, ou si quelque chose de grave y est passe (BrainDebugger le voit)."""
    if not _cle_presente(cfg) or not any(h.get("role") == "user" for h in historique):
        return None
    try:
        donnees = _requete_bd("/api/machitool/jarvis", {"transition": "resume", "historique": historique[-HISTORIQUE_JARVIS:],
                                                        "langue": langue_jarvis(cfg)}, cfg, 60)
    except Exception:
        return None
    texte = " ".join(str((donnees or {}).get("texte") or "").split())[:SOUVENIR_SIGNES]
    if not texte:
        return None
    souvenir = {"date": time.strftime("%Y-%m-%d"), "texte": texte}
    cfg["jarvis_souvenirs"] = (list(cfg.get("jarvis_souvenirs") or []) + [souvenir])[-SOUVENIRS_MAX:]
    sauver_config(cfg)
    return souvenir


def verser_au_journal(dit, repondu, cfg):
    """« FAIT EN SORTE QUE LES DISCUSSIONS DE JARVIS AILLENT AUSSI DANS LE
    JOURNAL ! » Chaque echange avec le majordome, une fois dit, part au
    journal de BrainDebugger (les deux bulles marquees « Jarvis »), en
    arriere-plan : il ne retarde rien, et un echec ne dit rien a voix haute.
    Pas ce qui est parti au compagnon (le grave, le mode psychologue) : il est
    deja au journal. Ce qui a ete dit ne va jamais au journal local
    (journal.log), seulement la raison d'un echec. Rend False si rien ne part."""
    dit = str(dit or "").strip()
    if not dit or not cfg.get("jarvis_journal", True) or not _cle_presente(cfg):
        return False
    corps = {"dit": dit[:JOURNAL_TOUR_MAX], "repondu": str(repondu or "").strip()[:JOURNAL_TOUR_MAX]}

    def verser():
        try:
            _requete_bd("/api/machitool/journal", corps, cfg, 30)
        except urllib.error.HTTPError as e:
            # un BrainDebugger d'avant ne connait pas la route : 404, rien de plus
            if e.code != 404:
                print("Jarvis : l'echange n'est pas alle au journal (HTTP %d)" % e.code)
        except Exception as e:
            print("Jarvis : l'echange n'est pas alle au journal (%s)" % type(e).__name__)
    _en_fond(verser)
    return True


JOURNAL_TOUR_MAX = 12000      # un tour de parole, au plus (TOUR_MAX de BrainDebugger)


def clore_historique(cfg=None):
    """La conversation en mode Jarvis se termine : on s'en souvient en une
    phrase (en arriere-plan), et on repart de zero."""
    historique = list(JARVIS.get("historique") or [])
    JARVIS["historique"] = []
    if historique and JARVIS.get("mode", "jarvis") == "jarvis":
        cfg = CFG if cfg is None else cfg
        _en_fond(lambda: resumer_conversation(historique, cfg))


def souvenirs_a_envoyer(cfg):
    return ["%s : %s" % (time.strftime("%d/%m", time.strptime(s_["date"], "%Y-%m-%d")), s_["texte"])
            for s_ in (cfg.get("jarvis_souvenirs") or [])[-SOUVENIRS_ENVOYES:]
            if isinstance(s_, dict) and s_.get("texte") and s_.get("date")]


def poser_mode(mode):
    if mode != JARVIS.get("mode"):
        clore_historique()
        if mode == "psy":
            # ce qui se dit au psychologue, gardé en memoire le temps de la
            # seance -- pour savoir, a l'au revoir, s'il faut se taire
            JARVIS["psy_echange"] = []
            JARVIS["psy_grave"] = False
    JARVIS.update(mode=mode, mode_vu=time.time(), propose_psy=False)


def mode_courant(maintenant=None):
    t = time.time() if maintenant is None else maintenant
    if JARVIS.get("mode") == "psy" and t - JARVIS.get("mode_vu", 0.0) > PSY_DUREE_S:
        poser_mode("jarvis")
    if t - JARVIS.get("vu", 0.0) > CONVERSATION_S and JARVIS.get("historique"):
        clore_historique()
        JARVIS["propose_psy"] = False
    return JARVIS.get("mode", "jarvis")


def nouveau_tour():
    """La conversation change de main : ce qu'il preparait ne se dira pas."""
    JARVIS["tour"] = int(JARVIS.get("tour") or 0) + 1
    return JARVIS["tour"]


CALME_S = 10 * 60             # congedie : pas de replique spontanee pendant dix minutes


def terminer_conversation():
    """« Non rien », « oublie », « degage », un clic sur son panneau : il se
    tait, n'ecoute plus la suite, oublie ce qu'il preparait ; le mode psy se
    referme, la guirlande rend la main."""
    nouveau_tour()
    VOIX.taire()
    envoyer_oreille({"cmd": "annuler"})
    poser_mode("jarvis")
    clore_historique()
    JARVIS.update(attente_code=None, suite_active=False, ecoute_fin=0.0, psy_echange=[], psy_grave=False,
                  calme_jusqua=time.time() + CALME_S)
    poser_led(None)
    JARVIS.update(etat="attente", message=message_attente())
    jouer_son("fin")
    declencher_routines("evenement", "au_revoir", CFG)


_ADIEUX = {
    "bonne nuit": ("Bonne nuit", "Good night"), "good night": ("Bonne nuit", "Good night"),
    "goodnight": ("Bonne nuit", "Good night"), "a demain": ("À demain", "Until tomorrow"),
    "bonne soiree": ("Bonne soirée", "Have a good evening"),
    "bonne journee": ("Bonne journée", "Have a good day"),
}
# « Salut Jarvis ! » en OUVRANT la conversation, c'est bonjour
_ADIEUX_AMBIGUS = {"salut", "ciao", "tchao"}


def dire_adieu(mot, cfg):
    """IL REPOND, PUIS IL S'ETEINT : « À bientôt », « Au revoir », « Bonne nuit »
    -- suivi de la facon dont il vous appelle, si on la lui a donnee (Reglages
    > Jarvis > « Il t'appelle ») : jamais « Monsieur » d'office. Pas de suite :
    l'oreille retourne a la veille, il faudra le rappeler. Le son de fin vient
    APRES son mot (il sonnait par-dessus)."""
    L = langue_jarvis(cfg)
    tour = nouveau_tour()
    envoyer_oreille({"cmd": "annuler"})
    poser_mode("jarvis")
    clore_historique(cfg)
    JARVIS.update(attente_code=None, calme_jusqua=time.time() + CALME_S)
    if mot in _ADIEUX:
        fr, en = _ADIEUX[mot]
    else:
        fr, en = random.choice((("À bientôt", "See you soon"), ("Au revoir", "Goodbye")))
    base = en if L == "en" else fr
    qui = str(cfg.get("jarvis_appellation", "") or "").strip()
    texte = base + (", " + qui if qui else "") + "."
    dire(texte, suite=False, langue=L, apres=lambda: jouer_son("fin"), tour=tour)
    return texte


def quitter_psy(cfg):
    """« AU REVOIR » AU PSYCHOLOGUE : retour au majordome, TOUT DE SUITE -- il
    faisait attendre jusqu'a 30 s, la guirlande en « reflexion ». Le majordome
    a demande en toutes lettres « il peut ne pas parler si la discussion etait
    intense, il peut aussi rebondir sur un sujet de maniere humoristique mais
    pas lourde » : ce mot-la, BrainDebugger l'ecrit en arriere-plan, avec la
    seance sous les yeux (elle est deja dans son journal : rien de neuf ne sort
    d'ici) -- et se tait TOUJOURS si un message grave y est passe. Ici aussi :
    `psy_grave` coupe avant meme de demander. Il ne le dit que si rien d'autre
    ne s'est passe entre-temps."""
    echange = list(JARVIS.get("psy_echange") or [])[-12:]
    grave = bool(JARVIS.get("psy_grave"))
    tour = nouveau_tour()
    VOIX.taire()
    envoyer_oreille({"cmd": "annuler"})
    poser_mode("jarvis")
    # congedie : la conversation se referme, mais elle est resumee (avant, elle
    # etait jetee -- « on parlait de quoi ? » n'avait plus de reponse)
    clore_historique()
    JARVIS.update(psy_echange=[], psy_grave=False, suite_active=False, ecoute_fin=0.0, attente_code=None)
    poser_led(None)
    JARVIS.update(etat="attente", message=message_attente())
    jouer_son("fin")
    if not (echange and not grave and _cle_presente(cfg)):
        return

    def mot_de_la_fin():
        try:
            d = _requete_bd("/api/machitool/jarvis",
                            {"texte": "au revoir", "transition": "fin_psy", "psy": echange,
                             "langue": langue_jarvis(cfg),
                             "appellation": str(cfg.get("jarvis_appellation", "") or "")[:40]}, cfg, 15)
        except Exception:
            return
        retour = str((d or {}).get("texte") or "").strip() if (d or {}).get("mode") == "jarvis" else ""
        if retour and JARVIS.get("etat") == "attente":
            dire(retour, langue=langue_jarvis(cfg), tour=tour)
    _en_fond(mot_de_la_fin)


def revenir_du_psy(cfg):
    """« Jarvis ! », « reviens en mode Jarvis », « je veux plus du psy » : le
    majordome revient, tout de suite, sans rien demander a BrainDebugger."""
    print("Jarvis : retour au majordome")
    tour = nouveau_tour()
    VOIX.taire()
    poser_mode("jarvis")
    JARVIS.update(psy_echange=[], psy_grave=False, historique=[])
    L = langue_jarvis(cfg)
    return dire(phrase("retour", L), suite="toujours", langue=L, tour=tour)


def echanges_en_cours():
    """Combien de fois la personne a parle dans cette conversation."""
    if JARVIS.get("mode") == "psy":
        return sum(1 for h in JARVIS.get("psy_echange") or [] if h.get("role") == "user")
    return sum(1 for h in JARVIS.get("historique") or [] if h.get("role") == "user")


def dire(texte, suite=False, langue=None, apres=None, tour=None, notifier=True, deja=None, spontane=False):
    """Repond : a voix haute si on l'a voulu, sinon en notification. La langue
    est celle du mode, sauf si on la donne.

    `tour` : la reponse d'un tour d'avant (on l'a congedie, rappele entre-
    temps) ne se dit pas. `suite` : ecoute-t-il encore, sans mot d'eveil ?
    « REND-LE PLUS FLUIDE » -- devoir redire « Jarvis » a chaque phrase
    cassait la conversation : il ecoute de nouveau apres CHAQUE reponse. Ce
    qui faisait prendre la tele pour une demande (on ne savait pas qu'il
    ecoutait) est reste regle : le carillon l'annonce, le panneau compte a
    rebours, le son de fin la referme, « ok merci » ou le silence suffisent
    pour partir. `jarvis_suite_questions` : seulement apres une question,
    comme avant. `apres` : ce qui se fait quand il a fini de parler.

    `deja` : sa premiere phrase, deja dite en avance (voir `dire_en_avance`)
    -- on ne dit que la suite, et l'ecoute part apres le tout.

    `spontane` : personne ne lui a parle (une routine, une initiative, une
    tache finie) -- le panneau LED le montre."""
    if tour is not None and JARVIS.get("tour") != tour:
        print("Jarvis : une reponse d'avant, pas dite")
        return
    langue = langue or langue_du_mode()
    texte = str(texte or "")
    if spontane:
        montrer_au_panneau(texte)
    JARVIS["reponse_affichee"] = texte
    mode = JARVIS.get("mode", "jarvis")
    reste, ident_deja = texte, None
    if deja and deja.get("id") is not None and deja.get("tour") == JARVIS.get("tour"):
        deja["fini"] = True
        reste, ident_deja = _jv.reste_a_dire(texte, deja.get("texte")), deja["id"]
    else:
        JARVIS["sous_titre"] = None                # les sous-titres d'avant ne s'affichent plus
    ecouter = bool(suite) and CFG.get("jarvis_suite", True) and (
        suite == "toujours" or mode == "psy" or bool(JARVIS.get("attente_code"))
        or not CFG.get("jarvis_suite_questions", False) or texte.rstrip().endswith("?"))
    t0 = JARVIS.get("tour")

    def fin():
        if JARVIS.get("tour") != t0:
            return                                 # congedie pendant qu'il parlait
        clore_temps("dit", t0)
        # « IL M'ECOUTE ALORS QU'IL PARLE ENCORE » : un minuteur, une annonce
        # attendent derriere sa reponse -- la suite (l'ecoute d'apres) attend
        # qu'ils soient dits, sinon le micro l'enregistre, et il se repond.
        plus_tard = [i for i in list(getattr(VOIX, "attentes", None) or {}) if i is not None]
        if plus_tard:
            dernier = max(plus_tard)
            avant = VOIX.attentes.get(dernier)

            def puis():
                if avant:
                    try:
                        avant()
                    except Exception:
                        pass
                fin()
            if VOIX.rattacher(dernier, puis):
                return
        if ecouter and oreille_vivante():
            jouer_son("eveil")
            attente = _jv.attente_suite(texte, echanges_en_cours(), mode)
            poser_led("ecoute")
            JARVIS.update(etat="ecoute", message="Je vous ecoute encore un instant.", suite_active=True,
                          ecoute_fin=time.time() + attente, ecoute_duree=attente, parole_vue=0.0)
            envoyer_oreille(consigne_ecouter(attente, mode))
        else:
            poser_led(None)
            JARVIS.update(etat="attente", message=message_attente())
        if apres:
            try:
                apres()
            except Exception:
                pass
    if ident_deja is not None:
        # on lui a coupe la parole pendant cette premiere phrase : la suite
        # attend la reprise (ou disparait), et l'etat reste celui de l'ecoute
        ident_deja = VOIX.rejoindre(ident_deja, reste, fin)
        if ident_deja is None:
            print("Jarvis : on lui avait coupe la parole, la suite ne se dit pas maintenant")
            return
        # la premiere phrase sonne (ou a sonne) : la suite derriere elle
        poser_led("parle")
        JARVIS.update(etat="parle", message="Je reponds.")
        if reste:
            VOIX.dire(reste, fin, langue, suite_de=ident_deja)
        elif not VOIX.rattacher(ident_deja, fin):
            fin()
    elif CFG.get("jarvis_voix", True) and VOIX.peut_parler():
        poser_led("parle")
        JARVIS.update(etat="parle", message="Je reponds.")
        VOIX.dire(texte, fin, langue)
    else:
        n = JARVIS_CROCHETS.get("notifier")
        if n and texte and notifier:
            n("Jarvis", _jv.pour_la_voix(texte, 240))
        fin()


def dire_en_avance(texte, langue, tour, avance):
    """« IL MET DU TEMPS A REPONDRE. » Sa premiere phrase, des que
    BrainDebugger l'a : elle sonne pendant que le modele ecrit la suite. Par
    la voix neuronale seulement (celle de Windows ne sait pas enchainer), et
    jamais pour un tour d'avant. `avance` garde ce qui a ete dit, pour que la
    reponse entiere ne le redise pas (voir `dire`, `deja`)."""
    if (avance.get("id") is not None or JARVIS.get("tour") != tour or not CFG.get("jarvis_voix", True)
            or not voix_prete(langue)):
        return
    ident = VOIX.dire(texte, lambda: _avance_dite(avance), langue)
    if ident is None:
        return
    avance.update(id=ident, texte=texte, tour=tour)
    JARVIS["reponse_affichee"] = texte
    poser_led("parle")
    JARVIS.update(etat="parle", message="Je reponds.")


def _avance_dite(avance):
    """La premiere phrase est dite, la suite n'est pas encore la : il reflechit
    encore (la boule, le panneau), il ne parle plus."""
    if not avance.get("fini") and JARVIS.get("tour") == avance.get("tour") and JARVIS.get("etat") == "parle":
        poser_led("pense")
        JARVIS.update(etat="pense", message="Jarvis reflechit...")


def dire_et_attendre(texte, langue=None, delai=30.0):
    """Dit, et rend la main quand c'est dit (ou apres `delai`)."""
    fini = threading.Event()
    langue = langue or langue_du_mode()
    if CFG.get("jarvis_voix", True) and VOIX.peut_parler():
        VOIX.dire(texte, fini.set, langue)
        fini.wait(delai)
    return fini.is_set()


# ---------- le chronometre d'un echange ----------
#
# « IL MET UNE PLOMBE A REPONDRE » -- mais ou ? La pause de fin de phrase, la
# transcription, BrainDebugger (et Claude), la voix ? Chaque echange garde ses
# temps -- des nombres, jamais ce qui a ete dit : une ligne au journal, et la
# page Jarvis montre le dernier, pour qu'on sache enfin ce qui est lent.

CHRONO = {"courant": None}          # l'echange en cours : {"tour", "mur", "pause", "t": {etape: monotonic}}
CHRONOS = deque(maxlen=10)          # les derniers echanges, le plus recent a la fin
_CHRONO_DERNIERES = ("bd_fin",)     # les tours d'outils : la derniere reponse compte


def noter_temps(etape, pause=None, fin_t=None):
    """Un point du chronometre. « phrase » ouvre un echange (l'oreille rend ta
    phrase : `pause`, le silence qu'elle a attendu ; `fin_t`, l'heure ou tu
    t'es tu). Les autres etapes -- transcrit, bd_envoi, bd_debut, bd_fin,
    voix -- ne comptent que pour l'echange en cours, et la premiere fois."""
    try:
        m = time.monotonic()
        if etape == "phrase":
            if CHRONO["courant"] is not None:
                clore_temps("interrompu")
            debut = m
            if fin_t is not None:
                debut = m - max(0.0, min(60.0, time.time() - float(fin_t)))
            elif pause is not None:
                debut = m - max(0.0, float(pause))
            CHRONO["courant"] = {"tour": JARVIS.get("tour"), "mur": time.time(), "pause": pause,
                                 "t": {"fin_parole": debut, "phrase": m}}
            return
        c = CHRONO["courant"]
        if c is None or c["tour"] != JARVIS.get("tour"):
            return
        t = c["t"]
        # « Un instant. » (il patiente) n'est pas le premier son de la reponse
        if etape == "voix" and "bd_envoi" in t and "bd_debut" not in t and "bd_fin" not in t:
            return
        if etape in _CHRONO_DERNIERES or etape not in t:
            t[etape] = m
    except Exception:
        pass


def clore_temps(issue, tour=None):
    """Ferme l'echange en cours (dit, erreur, annule...) : ses temps vont dans
    CHRONOS et au journal, en une ligne."""
    c = CHRONO["courant"]
    if c is None or (tour is not None and c["tour"] != tour):
        return None
    CHRONO["courant"] = None
    try:
        c["t"].setdefault("fin", time.monotonic())
        r = resume_temps(c, issue)
        CHRONOS.append(r)
        print(ligne_temps(r))
        return r
    except Exception as e:
        print("Jarvis : chronometre (%s)" % type(e).__name__)
        return None


def resume_temps(c, issue):
    """Les durees d'un echange, en secondes : chaque segment, puis le premier
    son et la fin comptes depuis le moment ou tu t'es tu."""
    t = c["t"]
    d = lambda a, b: round(max(0.0, t[b] - t[a]), 2) if a in t and b in t else None
    reponse = "bd_debut" if "bd_debut" in t else "bd_fin" if "bd_fin" in t else "transcrit"
    return {"heure": time.strftime("%H:%M:%S", time.localtime(c["mur"])), "issue": issue,
            "chemin": "bd" if "bd_envoi" in t else "ici", "pause": c.get("pause"),
            "fin_de_phrase": d("fin_parole", "phrase"), "transcription": d("phrase", "transcrit"),
            "contexte": d("transcrit", "bd_envoi"), "bd": d("bd_envoi", "bd_debut" if "bd_debut" in t else "bd_fin"),
            "bd_fin": d("bd_envoi", "bd_fin"), "voix": d(reponse, "voix"),
            "premier_son": d("fin_parole", "voix"), "total": d("fin_parole", "fin")}


def ligne_temps(r):
    """La ligne du journal (datee : un journal copie dit enfin ou ca traine)."""
    noms = (("fin_de_phrase", "fin de phrase"), ("transcription", "transcription"), ("contexte", "contexte"),
            ("bd", "BD 1re phrase"), ("bd_fin", "BD fin"), ("voix", "voix"))
    bouts = ["%s %.2f" % (nom, r[k]) for k, nom in noms if r.get(k) is not None]
    fin = [("1er son a %.2f s" % r["premier_son"]) if r.get("premier_son") is not None else "sans voix"]
    if r.get("total") is not None:
        fin.append("fin a %.2f s" % r["total"])
    return "Jarvis : echange de %s (%s, %s) -- %s | %s" % (r["heure"], r["chemin"], r["issue"],
                                                        " | ".join(bouts) or "-", " | ".join(fin))


def _secondes(x):
    return ("%.1f s" % x).replace(".", ",")


def texte_dernier_echange():
    """Pour la page Jarvis : « Dernier echange (14:03) : fin de phrase 0,8 s ·
    transcription 0,4 s · BrainDebugger 1,6 s · voix 0,2 s -- premier son a
    3,0 s. » Et le premier son des echanges d'avant."""
    if not CHRONOS:
        return ""
    r = CHRONOS[-1]
    noms = (("fin_de_phrase", "fin de phrase"), ("transcription", "transcription"),
            ("contexte", "contexte"), ("bd", "BrainDebugger"), ("voix", "voix"))
    bouts = ["%s %s" % (nom, _secondes(r[k])) for k, nom in noms if r.get(k) is not None
             and (k != "contexte" or r[k] >= 0.05)]
    txt = "Dernier echange (%s) : %s" % (r["heure"][:5], " · ".join(bouts) or "-")
    if r.get("premier_son") is not None:
        txt += " -- premier son a %s" % _secondes(r["premier_son"])
    if r.get("issue") not in ("dit",):
        txt += " (%s)" % r["issue"]
    avant = [_secondes(x["premier_son"]) for x in list(CHRONOS)[-6:-1] if x.get("premier_son") is not None]
    if avant:
        txt += ".  Avant : " + " · ".join(reversed(avant))
    return txt + "."


def texte_derniere_erreur(maintenant=None):
    """Le dernier echec, lisible sur la page Jarvis pendant une demi-heure (le
    panneau ne le montre que le temps de le dire)."""
    e = JARVIS.get("derniere_erreur")
    maintenant = time.time() if maintenant is None else maintenant
    if not e or maintenant - e[2] > 1800:
        return ""
    return "Dernier echec (%s) : %s" % (time.strftime("%H:%M", time.localtime(e[2])), (e[1] or e[0])[:240])


ERREUR_MONTREE_S = 2.5


def signaler_erreur(texte, tour=None, detail=None):
    """Ce qui a rate, APRES une demande : il le dit (et le panneau l'ecrit),
    ou le panneau montre ERREUR un instant. Jamais pour un souci de fond (voir
    `souci`), et jamais pour un tour d'avant.

    « JE NE SAIS PAS POURQUOI CA N'A PAS MARCHE » : il dit une phrase courte ;
    le detail technique (`detail`) va au journal et reste sur sa page."""
    # une ligne au journal pour chaque echec (la phrase ou le detail, jamais ce qu'on a dit)
    print("Jarvis : echec -- %s" % str(detail or texte)[:240])
    if tour is not None and JARVIS.get("tour") != tour:
        return
    JARVIS["derniere_erreur"] = (str(texte or ""), str(detail or ""), time.time())
    clore_temps("erreur")
    poser_led("erreur", 1.6)
    jouer_son("erreur")
    JARVIS["erreur_jusqua"] = time.time() + ERREUR_MONTREE_S
    JARVIS["sous_titre"] = None
    if CFG.get("jarvis_voix", True) and VOIX.peut_parler():
        JARVIS.update(etat="parle", message=texte)
        VOIX.dire(texte, lambda: (poser_led(None), JARVIS.update(etat="attente", message=message_attente())),
                  langue_du_mode())
    else:
        JARVIS.update(etat="attente", message=texte)


class Annule(BaseException):
    """La conversation a change pendant qu'il attendait : on laisse tomber.
    (BaseException : les « except Exception » qui disent une erreur ne
    l'attrapent pas -- il n'y a rien a dire.)"""


class Interrompu(Annule):
    """On lui a coupe la parole pendant sa premiere phrase, et c'etaient des
    mots : la suite de cette reponse ne se dira pas."""


class BDMuet(TimeoutError):
    """BrainDebugger n'a rien rendu -- ni premiere phrase, ni reponse -- en
    ATTENTE_BD_MAX_S : « il ne repond pas », pas « injoignable »."""


# « JE LUI PARLE ET PLUS RIEN » : BrainDebugger tarde (Railway qui redemarre,
# Claude surcharge, une recherche sur le web). Sans premiere phrase, un tout
# petit son dit qu'il y pense encore, puis « Un instant. » une fois ; au-dela
# d'ATTENTE_BD_MAX_S, il laisse tomber et le dit.
PATIENCE_S = 4.0
PATIENCE_REDIRE_S = 8.0
PATIENCE_DIRE_S = 12.0
ATTENTE_BD_MAX_S = 90.0             # une recherche sur le web met 20 a 40 s avant sa premiere phrase

# Les requetes a BrainDebugger en cours, par fil : {"r": la reponse ouverte,
# "annule": True}. Une requete abandonnee (congedie, rappele, trop longue) est
# fermee : le fil ne reste pas pendu a une reponse que personne n'entendra.
_EN_VOL = {}


def _fermer_reponse(r):
    """Ferme une reponse ouverte depuis un autre fil. La socket d'abord (la
    lecture en cours se debloque), puis la reponse."""
    try:
        sock = getattr(getattr(getattr(r, "fp", None), "raw", None), "_sock", None)
        if sock is not None:
            sock.shutdown(socket.SHUT_RDWR)
    except Exception:
        pass
    try:
        r.close()
    except Exception:
        pass


def abandonner_requete(ident):
    vol = _EN_VOL.get(ident)
    if vol is None:
        return False
    vol["annule"] = True
    if vol.get("r") is not None:
        # dans son fil : fermer peut attendre que la lecture rende la main
        threading.Thread(target=_fermer_reponse, args=(vol["r"],), daemon=True).start()
    return True


def requete_en_vol(ident=None):
    """La requete de ce fil (ou de `ident`) a-t-elle ete abandonnee ? Rend son
    entree (ou None)."""
    return _EN_VOL.get(threading.get_ident() if ident is None else ident)


def patienter(attente, deja_dit):
    """Un signe pendant qu'il attend BrainDebugger : le petit son, et une fois
    « Un instant. ». Rend True si « Un instant. » est parti."""
    if JARVIS.get("etat") in ("pense", "comprend"):
        JARVIS["message"] = "Jarvis reflechit... (BrainDebugger met du temps : %d s)" % attente
    if VOIX.parle:
        return False
    L = langue_du_mode()
    if (not deja_dit and attente >= PATIENCE_DIRE_S and CFG.get("jarvis_voix", True)
            and VOIX.peut_parler()):
        VOIX.dire(phrase("bd_lent", L), None, L)
        return True
    jouer_son("patience")
    return False


def _requete_bd_annulable(chemin, charge, cfg, delai, tour=None, sur_debut=None, avance=None):
    """_requete_bd, mais on n'attend plus des que la conversation a change (un
    nouveau reveil, « tais-toi », un clic sur le panneau) : Annule, et la
    requete est fermee. Il repondait encore apres qu'on l'avait congedie -- et
    la phrase suivante attendait derriere.

    Tant qu'aucune phrase n'est venue : un signe de loin en loin (voir
    `patienter`), et BDMuet au bout d'ATTENTE_BD_MAX_S. `avance` : sa premiere
    phrase, dite en avance ; interrompue pour de bon (voir traiter_evenement,
    « phrase »), c'est Interrompu."""
    noter_temps("bd_envoi")
    vu = {"debut": None}

    def debut(texte):
        if vu["debut"] is None:
            vu["debut"] = time.monotonic()
            noter_temps("bd_debut")
        sur_debut(texte)
    en_flux = debut if sur_debut is not None else None
    if tour is None:
        r = _requete_bd(chemin, charge, cfg, delai, en_flux)
        noter_temps("bd_fin")
        return r
    boite, fini = {}, threading.Event()

    def faire():
        _EN_VOL[threading.get_ident()] = {"r": None, "annule": False}
        try:
            boite["r"] = _requete_bd(chemin, charge, cfg, delai, en_flux)
        except BaseException as e:
            boite["e"] = e
        finally:
            _EN_VOL.pop(threading.get_ident(), None)
            fini.set()
    fil = threading.Thread(target=faire, daemon=True)
    fil.start()
    t0, signe, dit = time.monotonic(), PATIENCE_S, False
    try:
        while not fini.wait(0.1):
            if JARVIS.get("tour") != tour:
                raise Annule()
            if avance is not None and avance.get("interrompue"):
                raise Interrompu()
            attente = time.monotonic() - t0
            if vu["debut"] is not None:
                continue
            if attente >= ATTENTE_BD_MAX_S:
                raise BDMuet("rien en %d s" % ATTENTE_BD_MAX_S)
            if attente >= signe:
                signe = attente + PATIENCE_REDIRE_S
                dit = patienter(attente, dit) or dit
    except BaseException:
        abandonner_requete(fil.ident)
        raise
    if JARVIS.get("tour") != tour:
        raise Annule()
    if "e" in boite:
        raise boite["e"]
    noter_temps("bd_fin")
    return boite.get("r")


def echec_bd(e, L, tour, pour="jarvis", t0=None):
    """Ce qu'il dit quand BrainDebugger n'a pas repondu : une erreur (voir
    `erreur_bd`), un silence trop long (« ne repond pas ») ou pas de
    connexion (« injoignable »). La cause exacte au journal et sur sa page
    -- « injoignable » pouvait etre un nom introuvable, un pare-feu, une
    reponse coupee, et personne ne savait laquelle."""
    duree = "" if t0 is None else ", apres %.1f s" % (time.monotonic() - t0)
    if isinstance(e, urllib.error.HTTPError):
        corps = _corps_http(e)
        detail = "BrainDebugger %s : %s%s" % (e.code, str(corps.get("error") or corps.get("raison")
                                                           or e.reason or "")[:160], duree)
        return signaler_erreur(erreur_bd(e, L, pour=pour), tour, detail=detail)
    cause = getattr(e, "reason", None) if isinstance(e, urllib.error.URLError) else e
    muet = isinstance(cause, (TimeoutError, socket.timeout))
    cause = cause if isinstance(cause, BaseException) else e
    detail = "BrainDebugger %s -- %s: %s%s" % ("ne repond pas" if muet else "injoignable", type(cause).__name__,
                                               str(cause)[:120], duree)
    return signaler_erreur(phrase("bd_muet" if muet else "bd_injoignable", L), tour, detail=detail)


def veut_partir(texte, brut=""):
    """« Annule », « laisse tomber », « au revoir », « stop », « va dormir » :
    meme a « Code d'acces ? », ce n'est pas un code."""
    return bool(_jv.renvoi(texte) or _jv.renvoi(brut) or _jv.fin_de_conversation(texte) or _jv.adieu(texte)
                or (_jv.comprendre(texte) or {}).get("action") in ("fin", "silence", "dormir"))


def appel_lisible(brut, noms=()):
    """Son nom est-il dans la transcription (meme ecorche : « Javi », « Charvis ») ?"""
    return _jv.nom_verifie(brut, noms) is not None


def retirer_nom_ecorche(texte, noms=()):
    """« Javi, allume la lumiere » juste apres un reveil : le premier mot etait
    son nom, mal lu -- on l'enleve. (Jamais « je vais », « j'arrive ».)"""
    mots = str(texte or "").split()
    i = 0
    while i < len(mots) and _jv.normaliser(mots[i]).replace("'", "").strip(" -,.!?") in _jv._AMORCES_APPEL:
        i += 1
    for k in (1, 2):
        if i + k <= len(mots) and _jv.nom_verifie(" ".join(mots[i:i + k]).replace(" ", ""), noms):
            return re.sub(r"^[\s,.;:!?\u2026-]+", "", " ".join(mots[i + k:])).strip()
    return str(texte or "").strip()


def traiter_phrase(wav64, cfg, apres_coupure=False, deja_dit=False, breve=False, tour=None, avec_debut=False):
    """`avec_debut` : l'oreille a mis la phrase en suspens DEVANT sa suite --
    la transcription lit la phrase entiere, on ne recolle pas deux textes."""
    tour = JARVIS.get("tour") if tour is None else tour
    if JARVIS.get("tour") != tour:
        return                                     # congedie avant qu'on la lise
    poser_led("comprend")
    JARVIS.update(etat="comprend", message="Je transcris...", ecoute_fin=0.0, entendu="")
    L = langue_du_mode(cfg)
    suspens = JARVIS.pop("suspens", None)
    if suspens and suspens.get("tour") != tour:
        suspens = None
    if wav64 is None:
        # la phrase en suspens, et personne n'a rien ajoute : elle part telle quelle
        if not suspens:
            return fin_de_l_ecoute()
        if suspens.get("coupe"):
            # « Attends... » par-dessus lui, et rien apres : il reprend sa phrase
            return reprendre_apres_coupure() or fin_de_l_ecoute()
        return _traiter_texte(suspens["brut"], cfg, tour, suspens, apres_coupure, deja_dit, breve, L,
                              sans_suspens=True)
    try:
        octets = base64.b64decode(wav64)
    except Exception:
        return signaler_erreur(phrase("lecture", L), tour)
    if etat_dictee()["etat"] != "pret":
        # ce qu'il en est (un telechargement a 42 %, un nouvel essai) -- dit au
        # plus toutes les deux minutes, pas une seule fois pour toujours
        return dire_transcription_indisponible(L, tour)
    if dictee_possible() and not moteur_chaud():
        # le moteur se charge (l'exe, puis 1 Go) : l'attente a une raison visible
        JARVIS.update(message="Je prepare la transcription...")
    try:
        texte = transcrire_phrase(octets, L)
        noter_temps("transcrit")
    except DicteeImpossible as e:
        # la raison technique au journal et sur la page ; a voix haute, une phrase courte, dans sa langue
        print("Jarvis : transcription impossible (%s)" % str(e)[:200])
        return signaler_erreur(phrase(getattr(e, "cle", None) or "transcription_moteur", L), tour,
                               detail=str(e)[:240])
    except Exception as e:
        print("Jarvis : transcription impossible (%s)" % type(e).__name__)
        return signaler_erreur(phrase("transcription_ratee", L), tour)
    finally:
        octets = None
    if JARVIS.get("tour") != tour:
        return
    texte = str(texte or "")
    if suspens and suspens.get("coupe"):
        if not texte.strip():
            return reprendre_apres_coupure() or fin_de_l_ecoute()
        VOIX.oublier_reprise()                   # on lui a vraiment parle
    if suspens:
        if avec_debut and texte.strip() and not suspens.get("coupe"):
            print("Jarvis : la phrase en suspens relue en entier, avec sa suite")
        else:
            texte = _jv.joindre_suspens(suspens["brut"], texte)
    return _traiter_texte(texte, cfg, tour, suspens, apres_coupure, deja_dit, breve, L)


NOTES_EN_ATTENTE = []      # notes que BrainDebugger n'a pas prises : en memoire, jamais sur le disque
_NOTES_VERROU = threading.Lock()


def noter_et_repondre(texte, cfg, tour):
    """« Quand je fais Ctrl+Maj+Espace, je veux que Jarvis puisse repondre au
    lieu de dire note, aussi que ca note dans BrainDebugger. » La phrase part
    au carnet telle quelle (en arriere-plan, voir `poser_notes`), puis au
    majordome, qui sait qu'elle y est deja (`notee`) : il y repond. Rien
    n'est interprete en route -- « bon, j'y vais » ne le congedie pas."""
    texte = " ".join(str(texte or "").split())
    if not texte:
        return fin_de_l_ecoute()
    JARVIS["entendu"] = texte
    if _cle_presente(cfg):
        _en_fond(lambda: poser_notes(texte, cfg))
    return parler_a_jarvis(texte, cfg, tour, notee=True)


def poser_notes(texte, cfg):
    """POST /api/machitool/note : celle-ci, et celles d'avant que BrainDebugger
    n'a pas prises -- gardees en memoire, jamais sur le disque. Un echec se dit
    sur sa page, pas a voix haute (il est en train de te repondre). Rend
    le nombre de notes posees."""
    with _NOTES_VERROU:
        a_poser = NOTES_EN_ATTENTE[:] + [texte]
        del NOTES_EN_ATTENTE[:]
        for i, t in enumerate(a_poser):
            try:
                _requete_bd("/api/machitool/note", {"texte": t}, cfg, 20)
            except Exception as e:
                NOTES_EN_ATTENTE.extend(a_poser[i:])
                if isinstance(e, urllib.error.HTTPError) and e.code == 404:
                    souci("BrainDebugger ne connait pas encore les notes : il faut le redeployer "
                          "(%d note(s) gardee(s))" % len(NOTES_EN_ATTENTE))
                else:
                    souci("Note pas posee au carnet (%s) : %d gardee(s), elles partiront avec la prochaine"
                          % (getattr(e, "code", None) or type(e).__name__, len(NOTES_EN_ATTENTE)))
                return i
        print("Jarvis : %d note(s) au carnet" % len(a_poser))
        return len(a_poser)


def _suspendre(brut, cfg, tour, suspens, suite, deja_dit, L, coupe=False):
    """« Mets la musique de... » -- la phrase n'est pas finie : il ne repond
    pas a la moitie, il ecoute la suite (sans carillon : on parlait deja).
    L'oreille reprend depuis la FIN de la phrase (`reprise`) : ce qui a ete dit
    pendant qu'on transcrivait n'est plus perdu. `coupe` : « attends... » dit
    par-dessus lui -- sa reponse est gardee, il la reprend si rien ne suit."""
    n = int((suspens or {}).get("n") or 0)
    if n >= _jv.SUSPENS_MAX or not oreille_vivante():
        return False
    print("Jarvis : phrase en suspens, il attend la suite")
    JARVIS["suspens"] = {"brut": brut, "tour": tour, "n": n + 1, "deja_dit": deja_dit,
                         "suite": True if coupe else (suspens or {}).get("suite", suite), "coupe": bool(coupe)}
    attente = _jv.SUSPENS_ECOUTE_S
    poser_led("ecoute")
    try:
        vu = _jv.retirer_mot_eveil(brut, noms_appris(), garder_avant=True) or brut
    except Exception:
        vu = brut
    JARVIS.update(etat="ecoute", message="Je vous ecoute.", entendu=vu.strip() + "\u2026", suite_active=True,
                  ecoute_fin=time.time() + attente, ecoute_duree=attente, parole_vue=0.0)
    # pas de carillon, donc rien a ignorer ; et apres une coupure, pas la
    # phrase d'avant devant (sa voix y est)
    envoyer_oreille(consigne_ecouter(attente, ignorer=0.0, reprise=True, debut=not coupe))
    return True


def _traiter_texte(texte, cfg, tour, suspens, apres_coupure, deja_dit, breve, L, sans_suspens=False):
    brut = texte = str(texte or "")
    noms = noms_appris()
    if (apres_coupure or breve) and not suspens:
        # LE DEBUT DE LA PHRASE D'APRES UNE COUPURE, C'EST SA VOIX : « operational.
        # Stop. » -> « Stop. » ; « systems are operational » -> rien (une toux)
        net = _jv.sans_sa_voix(brut, JARVIS.get("coupe_contexte") or "")
        if net != brut.strip():
            print("Jarvis : sa propre voix retiree de ce qu'on lui a dit")
        brut = texte = net
    # une reponse, sans le nom (la phrase en suspens garde ce qu'elle etait)
    suite = bool(suspens["suite"]) if suspens else bool(JARVIS.get("suite_active"))
    JARVIS["suite_active"] = False
    deja_dit = bool(deja_dit or (suspens or {}).get("deja_dit"))
    code = JARVIS.get("attente_code") or oui_en_attente()
    if (not code and not apres_coupure and not breve and not sans_suspens and brut.strip()
            and (suspens is None or suspens.get("n", 0) < _jv.SUSPENS_MAX)
            and _jv.phrase_suspendue(brut, L)
            and _suspendre(brut, cfg, tour, suspens, suite, deja_dit, L)):
        return
    if JARVIS.get("note_tour") == tour:
        # Ctrl+Maj+Espace : au carnet telle quelle, puis il y repond
        JARVIS["note_tour"] = None
        return noter_et_repondre(brut, cfg, tour)
    premiere = not suite and not code              # la phrase qui suit un reveil (ou qui le coupe)
    coupe = apres_coupure or breve

    def se_rendormir(pourquoi):
        # pas un appel : il s'efface sans un mot (et sans rien retenir)
        print("Jarvis : %s -- il se rendort" % pourquoi)
        JARVIS["auto_en_attente"] = []
        poser_led(None)
        JARVIS.update(etat="attente", message=message_attente())

    # LA FIN DE SA PROPRE PHRASE, revenue des haut-parleurs dans la fenetre de
    # suite (« sir. ») : ce n'est pas ta reponse -- il ecoute encore
    if (suite and not code and not suspens and not apres_coupure and not breve
            and _jv.queue_de_sa_voix(brut, JARVIS.get("reponse_affichee"))):
        if reecouter_la_suite():
            return
        return se_rendormir("la fin de sa propre voix")

    # « SURTOUT QU'IL N'APPARAISSE PAS POUR RIEN » : juste apres un reveil que
    # personne n'a lu, il faut son nom dans ce qui a ete dit (meme ecorche) ;
    # et parler DE lui (« Jarvis ecoute tout le temps ») n'est pas l'appeler.
    if premiere and not coupe and not JARVIS.get("reveil_verifie") and not appel_lisible(brut, noms):
        return se_rendormir("pas de nom dans ce qu'il a entendu (%d mots)" % len(brut.split()))
    if premiere and not coupe and _jv.est_une_mention(brut, noms):
        return se_rendormir("on parlait de lui")
    garder_facons(brut)
    # au milieu d'une reponse (« j'ai galere a allumer Jarvis ce matin »), son
    # nom n'est pas un appel : on ne coupe pas la phrase
    if premiere or _jv.appel_du_nom(brut, noms):
        texte = _jv.retirer_mot_eveil(brut, noms, garder_avant=deja_dit or not premiere)
    else:
        texte = brut.strip()
    if premiere and not coupe and texte == brut.strip() and not _jv.contient_nom(brut, noms):
        texte = retirer_nom_ecorche(texte, noms)
    JARVIS["entendu"] = texte
    if code and not JARVIS.get("attente_code"):
        return repondre_au_oui(texte, brut, cfg)      # « Je ferme de force Discord ? » -- « oui »
    if code:
        # LA REPONSE A « CODE D'ACCES ? » -- comparee ici, jamais journalisee
        # ni envoyee. « Annule », « degage » : on laisse tomber.
        if time.time() > float(code.get("expire") or 0):
            JARVIS["attente_code"] = None
        elif veut_partir(texte, brut):
            JARVIS["attente_code"] = None
            return terminer_conversation()
        elif not texte:
            JARVIS["entendu"] = ""
            return dire(phrase("code_demande", langue_jarvis(cfg)), suite="toujours", langue=langue_jarvis(cfg),
                        tour=tour)
        else:
            JARVIS["entendu"] = ""                    # un code ne s'affiche pas
            return repondre_au_code(texte, cfg)
    if coupe:
        if not brut.strip():
            # Le micro a entendu quelque chose, mais pas des mots : c'etait
            # pour rien. L'oreille l'apprend, et il reprend sa phrase.
            envoyer_oreille({"cmd": "fausse_coupure"})
            if reprendre_apres_coupure():
                return
            return se_rendormir("coupe pour rien")
        # « MM-HMM », « OUI » par-dessus lui : continue (c'etait bien toi, pas
        # l'echo -- rien a apprendre). « ATTENDS... » : il se tait, et ecoute la
        # suite sans repondre ; si rien ne suit, il reprend.
        nature = _jv.nature_coupure(brut) if VOIX.reprise else None
        if nature == "relance" and reprendre_apres_coupure():
            return
        if nature == "attente" and _suspendre(brut, cfg, tour, suspens, suite, deja_dit, L, coupe=True):
            return
        # on lui a vraiment parle -- son nom compris (« Jarvis ? » pour le couper) :
        # rien de ce qu'il disait ne repart derriere (ni la suite de sa reponse)
        VOIX.taire()
        VOIX.oublier_reprise()
    # CHEZ LE PSYCHOLOGUE, la phrase brute d'abord : son nom, « reviens »,
    # « arrete », « je veux plus du psy » -- avant que le nom soit retire.
    if JARVIS.get("mode") == "psy":
        debut = echanges_en_cours() <= 1 and JARVIS.get("psy_raison") != "demande_locale"
        sortie = _jv.sortie_du_psy(brut, noms, debut_de_seance=debut)
        if sortie == "retour":
            return revenir_du_psy(cfg)
        if sortie == "stop":
            print("Jarvis : fin de la seance")
            return terminer_conversation()
        if sortie == "appel":
            print("Jarvis : appele pendant la seance -- le majordome reprend")
            poser_mode("jarvis")
            JARVIS.update(psy_echange=[], psy_grave=False)
        elif _jv.adieu(texte) or _jv.fin_de_conversation(texte):
            print("Jarvis : fin de la seance")
            return quitter_psy(cfg)
        elif (_jv.comprendre(texte) or {}).get("action") in ("silence", "fin"):
            return terminer_conversation()
    L = langue_du_mode(cfg)
    if not texte and _jv.renvoi(brut):
        # « Degage, Jarvis » : le nom vient APRES, et tout ce qui le precede est
        # coupe -- il ne restait rien, et il repondait « Oui ? ».
        print("Jarvis : renvoye")
        return terminer_conversation()
    mot = _jv.adieu(texte or brut)
    if mot and (mot not in _ADIEUX_AMBIGUS or not premiere):
        # « Salut », « au revoir » : il repond sur le meme ton, puis s'eteint.
        # (« Salut Jarvis ! » pour ouvrir la conversation, c'est bonjour.)
        print("Jarvis : au revoir")
        return dire_adieu(mot, cfg)
    if mot:
        texte = ""
    changement = _jv.changement_de_mode(texte) if texte else None
    if changement and changement[0] == "jarvis":
        # deja chez le majordome : « mode Jarvis » ne change rien ; « pas le
        # psy » en reponse a sa proposition, c'est non
        if JARVIS.get("propose_psy"):
            return terminer_conversation()
        changement, texte = None, ""
    if not texte:
        if not premiere:
            # la suite d'une conversation, mais pas un mot (une toux, un clavier,
            # la fin de sa voix) : il ecoute le temps qui restait, sans insister
            if not apres_coupure and not breve and reecouter_la_suite():
                return
            return se_rendormir("rien de dit")
        # « Jarvis. » tout court : il attend la suite -- et, UNE fois, s'il
        # a ete reveille par « Hey Jarvis » sans connaitre la voix, il dit
        # comment l'appeler par son nom seul.
        if (JARVIS.get("reveil_par") == "hey" and not gabarits_jarvis() and not cfg.get("jarvis_astuce_voix")):
            cfg["jarvis_astuce_voix"] = True
            sauver_config(cfg)
            return dire(phrase("astuce_voix", L), suite="toujours", tour=tour)
        return dire(phrase("oui", L), suite="toujours", tour=tour, notifier=False)
    if _jv.renvoi(texte):
        # « Degage », « pars », « stop » : il part, sans un mot, quel que soit le mode
        print("Jarvis : renvoye")
        return terminer_conversation()
    if (JARVIS.get("mode") != "psy" and _jv.acquittement(texte)
            and not str(JARVIS.get("reponse_affichee") or "").rstrip().endswith("?")):
        # « Ok merci », « parfait » : sa reponse suffisait -- il n'envoie rien
        # a personne et se rendort (s'il venait de poser une question, « ok »
        # est un oui : ca part au modele)
        print("Jarvis : fin de conversation (acquittement)")
        return terminer_conversation()
    if _jv.fin_de_conversation(texte):
        print("Jarvis : fin de conversation")
        if JARVIS.get("mode") == "psy":
            return quitter_psy(cfg)
        return terminer_conversation()
    if changement is None:
        changement = _jv.changement_de_mode(texte)
    if changement and JARVIS.get("mode") != "psy" and cfg.get("jarvis_pc") and _jv.note_a_ecrire(texte):
        changement = None        # « note que... » : Jarvis l'ecrit lui-meme (et la passe au psy)
    oui_au_psy = (changement is None and JARVIS.get("propose_psy")
                  and _jv.normaliser(texte).replace("-", " ").strip(" '") in _OUI)
    propose = JARVIS.get("propose_psy_phrase") or ""
    JARVIS["propose_psy"] = False
    JARVIS["propose_psy_phrase"] = ""
    if oui_au_psy:
        # « Voulez-vous que je passe en mode psychologue ? » -- « oui » : la
        # phrase qui l'avait fait proposer part au psychologue
        print("Jarvis : mode psy (accepte)")
        poser_mode("psy")
        JARVIS["psy_raison"] = "accepte"
        if propose:
            JARVIS["mode_vu"] = time.time()
            return parler_au_compagnon(propose, cfg, tour)
        return dire(phrase("mode_psy", "fr"), suite=True, langue="fr", tour=tour)
    if changement:
        mode, reste = changement
        poser_mode(mode)
        JARVIS["psy_raison"] = "demande_locale"
        print("Jarvis : mode %s" % mode)
        if not reste:
            return dire(phrase("mode_psy", "fr"), suite=True, langue="fr", tour=tour)
        texte = reste
    L = langue_du_mode(cfg)
    JARVIS["vu"] = time.time()
    # SES ROUTINES : « je vais me coucher » -> la lumiere du soir. Avec une
    # replique, c'est tout (un running gag se suffit) -- si la phrase n'est
    # QUE ca : « rappelle-moi dans 10 minutes, je vais me coucher » reste une
    # demande (la lumiere joue quand meme).
    if mode_courant() != "psy":
        r = declencher_routines("phrase", texte, cfg)
        if r and r.get("replique") and _jv.phrase_de_routine(texte, r):
            return dire(r["replique"], suite=False, langue=langue_jarvis(cfg), tour=tour)
    action = _jv.comprendre(texte, cfg.get("jarvis_raccourcis") or [])
    if action:
        print("Jarvis : commande %s" % action["action"])
        if action["action"] in ("fin", "silence"):
            return terminer_conversation()
        if action["action"] == "apprendre":
            threading.Thread(target=apprendre_a_voix_haute, args=(cfg,), daemon=True).start()
            return
        if action["action"] == "dormir" and JARVIS.get("mode") == "psy":
            poser_mode("jarvis")
            JARVIS.update(psy_echange=[], psy_grave=False)
        try:
            reponse = executer_commande(action, cfg)
        except Exception as e:
            print("Jarvis : commande ratee (%s)" % e)
            return signaler_erreur(phrase("commande_ratee", L), tour)
        poser_led("fait", 1.4)
        JARVIS["fait_jusqua"] = time.time() + 1.6
        if reponse:
            dire(reponse, tour=tour)
        else:
            jouer_son("fait")
            JARVIS.update(etat="attente", message=message_attente())
        return
    if mode_courant() == "psy":
        JARVIS["mode_vu"] = time.time()
        return parler_au_compagnon(texte, cfg, tour)
    return parler_a_jarvis(texte, cfg, tour)


def _requete_bd(chemin, charge, cfg, delai, sur_debut=None):
    """POST a BrainDebugger avec la cle de la passerelle (GET si `charge` est
    None). Rend le JSON, leve urllib.error.HTTPError ou une erreur reseau.

    `sur_debut` : la reponse EN FLUX -- BrainDebugger envoie la premiere
    phrase de Jarvis des qu'elle est ecrite (`{"debut": ...}`), puis la
    reponse entiere (`{"fin": ...}`). Un BrainDebugger d'avant repond en JSON
    tout court : ca marche pareil, sans l'avance."""
    if sur_debut is not None and charge is not None:
        charge = dict(charge, flux=True)
    base = str(cfg.get("pont_site", "")).strip().rstrip("/")
    cle = str(cfg.get("pont_cle", "")).strip()
    decalage = -(time.altzone if time.localtime().tm_isdst > 0 else time.timezone) // 3600
    entetes = {"User-Agent": "MachiToolkit/" + VERSION, "Content-Type": "application/json",
               "Authorization": "Bearer " + cle, "X-Machitool-Cle": cle,
               # Sa journee, pas celle du serveur : un fuseau a heure fixe suffit
               # pour dater MAINTENANT.
               "X-Fuseau": "UTC" if not decalage else "Etc/GMT%+d" % -decalage}
    corps = None if charge is None else json.dumps(charge, ensure_ascii=False).encode("utf-8")
    requete = urllib.request.Request(base + chemin, data=corps, headers=entetes)
    vol = requete_en_vol()
    for essai in (1, 2):
        t0 = time.monotonic()
        try:
            with urllib.request.urlopen(requete, timeout=delai, context=_contexte_ssl()) as r:
                if vol is not None:
                    vol["r"] = r                 # abandonnee (voir `abandonner_requete`) : on la ferme
                    if vol.get("annule"):
                        raise Annule()
                if sur_debut is None or "ndjson" not in str(r.headers.get("Content-Type") or ""):
                    return json.loads(r.read().decode("utf-8"))
                return _lire_flux_bd(r, base + chemin, sur_debut)
        except urllib.error.URLError as e:
            if isinstance(getattr(e, "reason", None), _ssl_erreurs()):
                _oublier_contexte_ssl()          # un magasin de certificats perime : relu la prochaine fois
            if essai == 2 or (vol is not None and vol.get("annule")) or not reessai_sur(e, time.monotonic() - t0):
                raise
            print("Jarvis : BrainDebugger -- %s, je reessaie une fois" % _cause_courte(e))
            time.sleep(REESSAI_BD_S)


REESSAI_BD_S = 0.8


def _ssl_erreurs():
    try:
        import ssl
        return (ssl.SSLError, ssl.CertificateError)
    except Exception:
        return ()


def _cause_courte(e):
    c = getattr(e, "reason", None) if isinstance(e, urllib.error.URLError) else None
    c = c if isinstance(c, BaseException) else e
    return "%s: %s" % (type(c).__name__, str(c)[:120])


def reessai_sur(e, duree):
    """Reessayer une requete a BrainDebugger n'est sur que si elle n'a PAS pu
    le mettre au travail : il execute des outils (l'agenda, le carnet) pendant
    la requete, et une seconde fois les poserait deux fois. Donc : le nom
    introuvable, la connexion refusee ou pas etablie, la poignee de main TLS
    (urllib ne les leve en URLError qu'avant la reponse) ; ou une page 502/503/504
    du bord de Railway -- pas du JSON de BrainDebugger -- rendue tout de suite
    (l'appli redemarre). Jamais une connexion coupee apres l'envoi."""
    if isinstance(e, urllib.error.HTTPError):
        return e.code in (502, 503, 504) and duree < 2.0 and not _corps_http(e)
    cause = getattr(e, "reason", None)
    return isinstance(cause, (socket.gaierror, ConnectionRefusedError, socket.timeout, TimeoutError)
                      + _ssl_erreurs())


def _lire_flux_bd(r, url, sur_debut):
    """Les lignes d'une reponse en flux : l'avance, puis la fin (ou l'erreur,
    rendue comme BrainDebugger la rendait avant : une HTTPError)."""
    vol = requete_en_vol()
    for ligne in r:
        if vol is not None and vol.get("annule"):
            raise Annule()                         # plus personne ne l'attend
        ligne = ligne.strip()
        if not ligne:
            continue
        try:
            d = json.loads(ligne.decode("utf-8"))
        except ValueError:
            continue
        if not isinstance(d, dict):
            continue
        if d.get("debut"):
            try:
                sur_debut(str(d["debut"]))
            except Exception:
                pass
        elif "fin" in d:
            return d["fin"]
        elif "erreur" in d:
            corps = json.dumps(d.get("erreur") or {}).encode("utf-8")
            raise urllib.error.HTTPError(url, int(d.get("statut") or 502), "erreur", {}, io.BytesIO(corps))
    raise ConnectionError("reponse coupee avant la fin")


def _cle_presente(cfg):
    return bool(str(cfg.get("pont_site", "")).strip() and str(cfg.get("pont_cle", "")).strip())


def _detail_http(e):
    return str(_corps_http(e).get("error") or "")


def _corps_http(e):
    """Le JSON d'une reponse d'erreur, lu une fois (la lecture vide le flux)."""
    if getattr(e, "_corps_lu", None) is None:
        try:
            e._corps_lu = json.loads(e.read().decode("utf-8")) or {}
        except Exception:
            e._corps_lu = {}
        if not isinstance(e._corps_lu, dict):
            e._corps_lu = {}
    return e._corps_lu


def erreur_bd(e, L, pour="jarvis"):
    """Ce qu'il dit quand BrainDebugger repond une erreur -- la CAUSE, quand on
    la connait (« BrainDebugger a repondu par une erreur 502 » ne disait pas
    quoi faire). Le detail va au journal et sur sa page."""
    corps = _corps_http(e)
    detail, raison = str(corps.get("error") or ""), str(corps.get("raison") or "")
    if detail:
        print("Jarvis : BrainDebugger %d -- %s" % (e.code, detail[:200]))
    if e.code in (401, 403):
        return phrase("cle_refusee", L)
    if e.code == 404:
        return phrase("bd_ancien_psy" if pour == "psy" else "bd_ancien_jarvis", L)
    if raison in ("cle", "credit", "surcharge", "limite"):
        return phrase("api_" + raison, L)
    if "clé API" in detail:
        return phrase("bd_sans_cle", L)
    # le detail (souvent l'anglais du SDK) ne se lit plus a voix haute : il est
    # au journal et sur sa page (voir `echec_bd`)
    return phrase("bd_erreur", L, e.code)


def parler_au_compagnon(texte, cfg, tour=None):
    """Le mode psychologue : le compagnon de BrainDebugger, son fil, son journal."""
    if not _cle_presente(cfg):
        return signaler_erreur(phrase("cle_absente", "fr"), tour)
    poser_led("pense")
    JARVIS.update(etat="pense", message="Le compagnon reflechit...")
    print("Jarvis : message au compagnon (%d signes)" % len(texte))
    t0 = time.monotonic()
    try:
        donnees = _requete_bd_annulable("/api/machitool/parler", {"texte": texte}, cfg, 180, tour)
    except Exception as e:
        return echec_bd(e, "fr", tour, pour="psy", t0=t0)
    reponse = str((donnees or {}).get("texte") or "").strip()
    if not reponse:
        return signaler_erreur(phrase("compagnon_muet", "fr"), tour)
    if JARVIS.get("mode") != "psy":
        return                      # revenu au majordome entre-temps : la seance est close
    JARVIS["mode_vu"] = time.time()
    JARVIS["psy_echange"] = (list(JARVIS.get("psy_echange") or []) + [
        {"role": "user", "texte": texte}, {"role": "assistant", "texte": reponse}])[-HISTORIQUE_JARVIS:]
    dire(reponse, suite=True, langue="fr", tour=tour)


# ---------- ses mains sur le PC ----------
#
# « Donne l'acces total a Jarvis... lorsqu'il doit interagir il demande un
# code d'acces a l'oral avant d'effectuer l'operation. » BrainDebugger dit a
# Jarvis ce qu'il peut faire ; quand il veut un outil, la reponse revient ICI,
# on l'execute sur le poste, et on renvoie le resultat. Avant les dossiers, les
# fichiers et l'ecran, Jarvis demande le code a voix haute : la phrase qui suit
# est comparee a l'empreinte gardee dans la config, sur le poste -- elle n'est
# ni transcrite dans un journal, ni envoyee, ni ecrite nulle part. Juste, les
# mains restent ouvertes dix minutes ; trois faux, elles se ferment cinq.

OUTILS_SANS_CODE = {"musique", "spotify", "rechercher_google", "lien", "retenir", "oublier",
                    "lancer_appli", "fenetre", "son", "pc", "youtube", "onglets", "temperatures",
                    "spotify_jouer", "spotify_en_cours", "spotify_aimer", "montrer_agenda",
                    "lancer_tache", "taches", "noter_projet",
                    # Machi Tool lui-meme est a lui : jamais sous code
                    "lumiere", "routine_lumiere", "reglages_machi", "mise_a_jour",
                    # « verifie bien que Jarvis puisse declencher un minuteur de
                    # lui-meme, pareil pour les alarmes et les chronometres » : il
                    # manquait -- sans ses mains sur le PC, l'outil etait refuse ;
                    # avec, il passait sous code
                    "minuteurs", "resume_du_jour"}
# Ce qu'il retient de toi : toujours permis, meme sans ses mains sur le PC.
OUTILS_MEMOIRE = {"retenir", "oublier"}
ACCES_DUREE_S = 600
VERROU_DUREE_S = 300
OUTILS_TOURS_MAX = 5
OUVRIR_MAX = 10          # « ouvre-les » : dix au plus d'un coup
_TOUCHES_MEDIA = {"lecture_pause": 0xB3, "suivant": 0xB0, "precedent": 0xB1,
                  "volume_plus": 0xAF, "volume_moins": 0xAE, "muet": 0xAD}


def code_regle(cfg):
    return bool(cfg.get("jarvis_code_sel") and cfg.get("jarvis_code_empreinte"))


def poser_code(cfg, code):
    """Le code choisi dans les reglages : on n'en garde que l'empreinte."""
    if not _jv.normaliser_code(code):
        cfg["jarvis_code_sel"] = cfg["jarvis_code_empreinte"] = ""
        return False
    sel = os.urandom(16).hex()
    cfg["jarvis_code_sel"], cfg["jarvis_code_empreinte"] = sel, _jv.empreinte_code(code, sel)
    return True


def acces_ouvert():
    return time.time() < float(JARVIS.get("acces_jusqua") or 0)


def bases_dossiers():
    """Les dossiers qu'on nomme : Documents, Bureau, Telechargements..."""
    home = os.path.expanduser("~")
    bases = {"home": home}
    for cle, nom in (("documents", "Documents"), ("desktop", "Desktop"), ("downloads", "Downloads"),
                     ("pictures", "Pictures"), ("music", "Music"), ("videos", "Videos")):
        bases[cle] = os.path.join(home, nom)
    if os.name == "nt":
        try:
            # les vrais emplacements, meme deplaces (OneDrive, un autre disque)
            import winreg
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion"
                                r"\Explorer\User Shell Folders") as k:
                for cle, val in (("documents", "Personal"), ("desktop", "Desktop"),
                                 ("downloads", "{374DE290-123F-4565-9164-39C4925E467B}"),
                                 ("pictures", "My Pictures"), ("music", "My Music"), ("videos", "My Video")):
                    try:
                        bases[cle] = os.path.expandvars(winreg.QueryValueEx(k, val)[0])
                    except OSError:
                        pass
        except Exception:
            pass
    return bases


def dossiers_proteges():
    env = os.environ
    return [env.get("SystemRoot") or env.get("windir"), env.get("ProgramFiles"),
            env.get("ProgramFiles(x86)"), env.get("ProgramData")]


def touche_media(action):
    """Les touches multimedia du clavier, ENVOYEES (pas ecoutees) : Spotify et
    tout lecteur y repondent. Aucun crochet clavier : on n'ecoute rien."""
    vk = _TOUCHES_MEDIA.get(str(action))
    if vk is None:
        raise ValueError("action inconnue : %s" % action)
    if os.name != "nt":
        raise OSError("les touches multimedia ne se pilotent que sous Windows")
    import ctypes
    user = ctypes.WinDLL("user32")
    user.keybd_event(vk, 0, 0, 0)
    user.keybd_event(vk, 0, 2, 0)          # KEYEVENTF_KEYUP
    return {"lecture_pause": "Lecture ou pause.", "suivant": "Piste suivante.",
            "precedent": "Piste precedente.", "volume_plus": "Volume monte.",
            "volume_moins": "Volume baisse.", "muet": "Son coupe ou remis."}[action]


def ouvrir_spotify(recherche):
    q = str(recherche or "").strip()
    uri = "spotify:search:" + urllib.parse.quote(q) if q else "spotify:"
    try:
        os.startfile(uri)                  # l'application, si elle est installee
        return "Spotify ouvert" + (" sur « %s »." % q if q else ".")
    except Exception:
        import webbrowser
        webbrowser.open("https://open.spotify.com/search/" + urllib.parse.quote(q) if q
                        else "https://open.spotify.com")
        return "Spotify ouvert dans le navigateur" + (" sur « %s »." % q if q else ".")


def creer_fichier(chemin, contenu, protegees=()):
    """Un fichier texte NEUF (jarvis.preparer_fichier dit ou et quoi). Rend
    le chemin reellement ecrit."""
    ch, texte, encodage = _jv.preparer_fichier(chemin, contenu, protegees)
    os.makedirs(os.path.dirname(ch) or ".", exist_ok=True)
    with open(ch, "x", encoding=encodage, newline="") as f:
        f.write(texte)
    return ch


def ecrire_note(dossier, texte, titre="", ajouter_a="", maintenant=None):
    """Une note dans le dossier de Jarvis. Rend (chemin, neuve)."""
    ch, contenu, mode, encodage = _jv.preparer_note(dossier, texte, titre, ajouter_a, maintenant)
    os.makedirs(dossier, exist_ok=True)
    with open(ch, mode, encoding=encodage, newline="") as f:
        f.write(contenu)
    return ch, mode == "x"


def lire_historique_copie(genre, chemin, depuis):
    """Le navigateur tient son historique ouvert : on en lit une copie, dans
    un dossier temporaire efface en sortant."""
    import shutil
    import tempfile
    with tempfile.TemporaryDirectory(prefix="machi-") as d:
        copie = os.path.join(d, "h.sqlite")
        shutil.copyfile(chemin, copie)
        if os.path.isfile(chemin + "-wal"):
            shutil.copyfile(chemin + "-wal", copie + "-wal")
        return _jv.lire_historique(genre, copie, depuis)


def chemin_chrome():
    """chrome.exe, s'il est installe : le registre (App Paths), puis les
    emplacements habituels."""
    if os.name != "nt":
        return None
    try:
        import winreg
        for racine in (winreg.HKEY_CURRENT_USER, winreg.HKEY_LOCAL_MACHINE):
            try:
                with winreg.OpenKey(racine, r"Software\Microsoft\Windows\CurrentVersion\App Paths"
                                    r"\chrome.exe") as k:
                    p = winreg.QueryValueEx(k, "")[0]
                    if p and os.path.isfile(p):
                        return p
            except OSError:
                pass
    except Exception:
        pass
    for base in (os.environ.get("ProgramFiles"), os.environ.get("ProgramFiles(x86)"),
                 os.environ.get("LOCALAPPDATA")):
        p = os.path.join(base or "", "Google", "Chrome", "Application", "chrome.exe")
        if base and os.path.isfile(p):
            return p
    return None


def ouvrir_dans_chrome(url):
    """Une adresse web dans Chrome (ou, sans Chrome, le navigateur par defaut)."""
    chrome = chemin_chrome()
    if chrome:
        subprocess.Popen([chrome, url], creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        return "Chrome"
    import webbrowser
    webbrowser.open(url)
    return "le navigateur"


# --- APPLIS ET JEUX ----------------------------------------------------
# « Lance Discord », « lance Elden Ring » : le menu Demarrer (les raccourcis
# qu'on y voit) et les jeux Steam installes. Relus toutes les cinq minutes.

_APPLIS = {"liste": [], "quand": 0.0}


def racine_steam():
    if os.name == "nt":
        try:
            import winreg
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Valve\Steam") as k:
                p = winreg.QueryValueEx(k, "SteamPath")[0]
                if p and os.path.isdir(p):
                    return os.path.normpath(p)
        except Exception:
            pass
    for base in (os.environ.get("ProgramFiles(x86)"), os.environ.get("ProgramFiles")):
        p = os.path.join(base or "", "Steam")
        if base and os.path.isdir(p):
            return p
    return None


def applis_installees(frais=False):
    if frais or not _APPLIS["liste"] or time.time() - _APPLIS["quand"] > 300:
        menus = [os.path.join(os.environ[v], "Microsoft", "Windows", "Start Menu", "Programs")
                 for v in ("APPDATA", "ProgramData") if os.environ.get(v)]
        _APPLIS["liste"] = _jv.jeux_steam(racine_steam()) + _jv.raccourcis_menu(menus)
        _APPLIS["quand"] = time.time()
    return _APPLIS["liste"]


def lancer_appli(nom):
    trouves = _jv.choisir(nom, applis_installees())
    if not trouves:
        trouves = _jv.choisir(nom, applis_installees(frais=True))
    if not trouves:
        raise LookupError("Aucune appli ni aucun jeu installe ne s'appelle « %s »." % nom)
    if len({c for _, c, _ in trouves}) > 1:
        return "Plusieurs correspondent, lequel ? " + " ; ".join(n for n, _, _ in trouves[:6])
    n, cible, genre = trouves[0]
    startfile_sur(cible)
    return ("Jeu lance par Steam : %s." if genre == "jeu" else "Lance : %s.") % n


# --- FENETRES ----------------------------------------------------------
# Par les fonctions de Windows (ShowWindow, SetForegroundWindow, WM_CLOSE) :
# rien n'est clique ni tape. « Fermer » demande poliment : l'appli peut
# proposer d'enregistrer.

def fenetres_ouvertes():
    """[(hwnd, titre, processus)] des fenetres visibles de la barre des taches."""
    import ctypes
    import win32gui
    import win32process
    import psutil
    dwm = ctypes.WinDLL("dwmapi")
    out = []

    def voir(h, _):
        if not win32gui.IsWindowVisible(h) or win32gui.GetWindow(h, 4):     # GW_OWNER
            return True
        titre = win32gui.GetWindowText(h)
        if not titre or titre in ("Program Manager", "Machi Tool"):
            return True
        cache = ctypes.c_int(0)
        dwm.DwmGetWindowAttribute(h, 14, ctypes.byref(cache), ctypes.sizeof(cache))   # DWMWA_CLOAKED
        if cache.value:
            return True
        try:
            proc = psutil.Process(win32process.GetWindowThreadProcessId(h)[1]).name()
        except Exception:
            proc = ""
        out.append((h, titre, proc))
        return True
    win32gui.EnumWindows(voir, None)
    return out


def agir_fenetre(action, cible="", tout=False):
    import win32gui
    import win32con
    fen = fenetres_ouvertes()
    if action == "lister":
        if not fen:
            return "Aucune fenetre ouverte."
        return "%d fenetres : %s" % (len(fen), " ; ".join("%s (%s)" % (t[:80], p.replace(".exe", ""))
                                                         for _, t, p in fen[:25]))
    if tout and action == "reduire":
        for h, _, _ in fen:
            win32gui.ShowWindow(h, win32con.SW_MINIMIZE)
        return "Toutes les fenetres sont reduites."
    trouves = _jv.choisir(cible, fen, nom=lambda f: f[1] + " " + f[2].replace(".exe", ""), seuil=40)
    if not trouves:
        raise LookupError("Aucune fenetre ouverte ne correspond a « %s »." % cible)
    h, titre, _ = trouves[0]
    if action == "premier_plan":
        if win32gui.IsIconic(h):
            win32gui.ShowWindow(h, win32con.SW_RESTORE)
        try:
            win32gui.SetForegroundWindow(h)
        except Exception:
            # Windows refuse parfois de donner le premier plan a qui ne l'a pas :
            # reduire puis restaurer, c'est l'y mettre sans rien simuler.
            win32gui.ShowWindow(h, win32con.SW_MINIMIZE)
            win32gui.ShowWindow(h, win32con.SW_RESTORE)
        return "Au premier plan : %s." % titre
    geste = {"reduire": win32con.SW_MINIMIZE, "agrandir": win32con.SW_MAXIMIZE,
             "restaurer": win32con.SW_RESTORE}.get(action)
    if geste is not None:
        win32gui.ShowWindow(h, geste)
        return {"reduire": "Reduite", "agrandir": "Agrandie", "restaurer": "Restauree"}[action] + " : %s." % titre
    if action == "fermer":
        win32gui.PostMessage(h, win32con.WM_CLOSE, 0, 0)
        return "Fermeture demandee : %s (elle peut proposer d'enregistrer)." % titre
    raise ValueError("action inconnue : %s" % action)


# --- LE SON ------------------------------------------------------------
# Le volume general, ou celui d'une appli (« baisse Discord ») : le melangeur
# de Windows, par pycaw.

def _volume_general():
    from pycaw.pycaw import AudioUtilities, IAudioEndpointVolume
    haut_parleurs = AudioUtilities.GetSpeakers()
    ev = getattr(haut_parleurs, "EndpointVolume", None)
    if ev is not None:
        return ev
    from comtypes import CLSCTX_ALL
    from ctypes import cast, POINTER
    return cast(haut_parleurs.Activate(IAudioEndpointVolume._iid_, CLSCTX_ALL, None), POINTER(IAudioEndpointVolume))


def sessions_audio():
    """[(session pycaw, nom de l'exe, chemin)] des applis qui ont du son --
    y compris les jeux qu'un anti-triche cache a psutil (la session garde son
    PID : on lit son nom autrement)."""
    from pycaw.pycaw import AudioUtilities
    out = []
    for sess in AudioUtilities.GetAllSessions():
        pid = int(getattr(sess, "ProcessId", 0) or 0)
        if not pid:
            continue                                   # les sons du systeme
        try:
            nom = sess.Process.name() if sess.Process else ""
        except Exception:
            nom = ""
        nom = nom or _nom_du_processus(pid)
        if nom:
            out.append((sess, nom, _chemin_du_processus(pid)))
    return out


def _joli(nom):
    base = os.path.splitext(os.path.basename(nom))[0]
    return {"msedge": "Edge", "chrome": "Chrome", "firefox": "Firefox"}.get(base.lower(),
                                                                          base[:1].upper() + base[1:])


def regler_son(action, appli="", niveau=None):
    """Le volume general (sans appli) ou celui d'applis precises -- « le jeu »,
    « le navigateur », « la musique » compris. Rend une phrase."""
    if os.name != "nt":
        raise OSError("le volume ne se regle que sous Windows")
    if not appli:
        v = _volume_general()
        if action in ("couper", "remettre"):
            v.SetMute(1 if action == "couper" else 0, None)
            return "Son coupé." if action == "couper" else "Son remis."
        n = _jv.nouveau_niveau(v.GetMasterVolumeLevelScalar() * 100, action, niveau)
        v.SetMasterVolumeLevelScalar(n / 100.0, None)
        v.SetMute(0, None)
        return "Volume général à %d %%." % n
    sessions = sessions_audio()
    indices = _jv.cibles_son(appli, [(nom, chemin) for _, nom, chemin in sessions])
    if not indices:
        ouvertes = sorted({_joli(nom) for _, nom, _ in sessions})
        raise LookupError("Rien ne fait du son sous ce nom (%s) ; en ce moment : %s."
                          % (appli, ", ".join(ouvertes) or "aucune appli"))
    noms, faits = [], []
    for i in indices:
        sess, nom, _ = sessions[i]
        vol = sess.SimpleAudioVolume
        if action in ("couper", "remettre"):
            vol.SetMute(1 if action == "couper" else 0, None)
        else:
            n = _jv.nouveau_niveau(vol.GetMasterVolume() * 100, action, niveau)
            vol.SetMasterVolume(n / 100.0, None)
            vol.SetMute(0, None)
            faits.append(n)
        if _joli(nom) not in noms:
            noms.append(_joli(nom))
    qui = " et ".join(noms)
    if action == "couper":
        return "Son de %s coupé." % qui
    if action == "remettre":
        return "Son de %s remis." % qui
    return "Volume de %s à %d %%." % (qui, faits[0])


def lister_sons():
    """« Qu'est-ce qui fait du son ? » : chaque appli et son volume."""
    if os.name != "nt":
        raise OSError("le volume ne se lit que sous Windows")
    vus = {}
    for sess, nom, chemin in sessions_audio():
        vol = sess.SimpleAudioVolume
        cle = _joli(nom) + (" (jeu)" if _jv.est_un_jeu(chemin, nom) else "")
        vus.setdefault(cle, "coupé" if vol.GetMute() else "%d %%" % round(vol.GetMasterVolume() * 100))
    if not vus:
        return "Aucune appli ne fait de son."
    return "En ce moment : " + ", ".join("%s %s" % (k, v) for k, v in vus.items()) + "."


# --- LE PC : VERROUILLER, LUMINOSITE ------------------------------------
# « Qu'il ne puisse pas eteindre, redemarrer ou mettre en veille l'ordinateur,
# ni fermer la session » : il n'y a pas de fonction pour ca, et
# `startfile_sur` refuse ce qui le ferait par la bande (voir
# touche_a_l_alimentation dans jarvis.py). Verrouiller ne ferme rien.

def verrouiller_pc():
    import ctypes
    ctypes.WinDLL("user32").LockWorkStation()
    return "PC verrouille."


def startfile_sur(chemin):
    """os.startfile, sauf ce qui eteindrait, redemarrerait, mettrait en veille
    le PC ou fermerait la session."""
    if _jv.touche_a_l_alimentation(chemin):
        raise PermissionError(_jv.REFUS_ALIMENTATION)
    os.startfile(chemin)


def _dxva2():
    """dxva2, avec ses types : sans eux, ctypes passerait les handles en entier
    32 bits, et un handle 64 bits serait tronque."""
    import ctypes
    from ctypes import wintypes

    class MONITEUR(ctypes.Structure):
        _fields_ = [("h", wintypes.HANDLE), ("nom", wintypes.WCHAR * 128)]
    d = ctypes.WinDLL("dxva2")
    P = ctypes.POINTER
    d.GetNumberOfPhysicalMonitorsFromHMONITOR.argtypes = [wintypes.HMONITOR, P(wintypes.DWORD)]
    d.GetPhysicalMonitorsFromHMONITOR.argtypes = [wintypes.HMONITOR, wintypes.DWORD, P(MONITEUR)]
    d.GetMonitorBrightness.argtypes = [wintypes.HANDLE, P(wintypes.DWORD), P(wintypes.DWORD), P(wintypes.DWORD)]
    d.SetMonitorBrightness.argtypes = [wintypes.HANDLE, wintypes.DWORD]
    d.DestroyPhysicalMonitors.argtypes = [wintypes.DWORD, P(MONITEUR)]
    return d, MONITEUR


def luminosites():
    """Les ecrans qui se reglent par le cable (DDC/CI) : ([(handle physique,
    mini, actuel, maxi)], tableaux a rendre a DestroyPhysicalMonitors)."""
    import ctypes
    from ctypes import wintypes
    user32 = ctypes.WinDLL("user32")
    dxva2, MONITEUR = _dxva2()
    hmons = []
    Rappel = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HMONITOR, wintypes.HDC,
                                ctypes.POINTER(wintypes.RECT), wintypes.LPARAM)
    rappel = Rappel(lambda hm, hdc, r, lp: hmons.append(hm) or True)
    user32.EnumDisplayMonitors(None, None, rappel, 0)
    ecrans, tableaux = [], []
    for hm in hmons:
        n = wintypes.DWORD()
        if not dxva2.GetNumberOfPhysicalMonitorsFromHMONITOR(hm, ctypes.byref(n)) or not n.value:
            continue
        tab = (MONITEUR * n.value)()
        if not dxva2.GetPhysicalMonitorsFromHMONITOR(hm, n.value, tab):
            continue
        tableaux.append((n.value, tab))
        for m in tab:
            mini, cour, maxi = wintypes.DWORD(), wintypes.DWORD(), wintypes.DWORD()
            if dxva2.GetMonitorBrightness(m.h, ctypes.byref(mini), ctypes.byref(cour), ctypes.byref(maxi)):
                ecrans.append((m.h, mini.value, cour.value, maxi.value))
    return ecrans, tableaux


def regler_luminosite(action, niveau=None):
    """Tous les ecrans : par le cable (DDC/CI) pour les ecrans externes, par
    Windows (WMI) pour celui d'un portable."""
    if os.name != "nt":
        raise OSError("la luminosite ne se regle que sous Windows")
    dxva2, _ = _dxva2()
    ecrans, tableaux = luminosites()
    faits = []
    try:
        for h, mini, cour, maxi in ecrans:
            pct = 100.0 * (cour - mini) / max(1, maxi - mini)
            n = _jv.nouveau_niveau(pct, action, niveau)
            if dxva2.SetMonitorBrightness(h, int(round(mini + (maxi - mini) * n / 100.0))):
                faits.append(n)
    finally:
        for n, tab in tableaux:
            dxva2.DestroyPhysicalMonitors(n, tab)
    if faits:
        return "Luminosite a %d %% (%d ecran%s)." % (faits[0], len(faits), "s" if len(faits) > 1 else "")
    if action != "regler":
        raise OSError("Aucun ecran ne dit sa luminosite : donne un niveau precis, par exemple 50 %.")
    r = subprocess.run(["powershell", "-NoProfile", "-Command",
                        "(Get-CimInstance -Namespace root/WMI -ClassName WmiMonitorBrightnessMethods) | "
                        "Invoke-CimMethod -MethodName WmiSetBrightness -Arguments @{Timeout=1;Brightness=%d}"
                        % _jv.nouveau_niveau(0, "regler", niveau)],
                       capture_output=True, timeout=15, creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
    if r.returncode != 0:
        raise OSError("Ces ecrans ne se reglent pas depuis Windows (DDC/CI coupe dans le menu de l'ecran ?).")
    return "Luminosite a %d %%." % _jv.nouveau_niveau(0, "regler", niveau)


# --- LES ONGLETS DE CHROME ---------------------------------------------
# « Il faut qu'il puisse fermer ou ouvrir des onglets. » Par une petite
# extension de Machi Tool, installee dans Chrome (ou Edge, Brave) : elle
# demande a Machi Tool s'il a quelque chose pour elle (127.0.0.1, sa propre
# cle), fait ce qu'on lui dit avec les fonctions d'onglets de Chrome, et
# repond. Rien n'est clique ni tape. Vers Jarvis ne partent que les titres et
# les domaines, jamais les adresses entieres.

ONGLETS = {"file": [], "resultats": {}, "vu": 0.0, "cond": threading.Condition()}
ONGLETS_VIVANTE_S = 45.0
ONGLETS_ATTENTE_S = 20.0


def extension_branchee():
    return time.time() - ONGLETS["vu"] < ONGLETS_VIVANTE_S


def commande_onglets(action, delai=6.0, **args):
    """Une commande a l'extension, et sa reponse (un dict)."""
    if not extension_branchee():
        raise LookupError("L'extension Chrome de Machi Tool n'est pas branchee (Reglages > Jarvis > "
                          "les onglets de Chrome), ou Chrome est ferme.")
    ident = os.urandom(6).hex()
    c = ONGLETS["cond"]
    with c:
        ONGLETS["file"].append(dict(args, id=ident, action=action))
        c.notify_all()
        fin = time.time() + delai
        while ident not in ONGLETS["resultats"] and time.time() < fin:
            c.wait(max(0.05, fin - time.time()))
        r = ONGLETS["resultats"].pop(ident, None)
        ONGLETS["file"] = [x for x in ONGLETS["file"] if x["id"] != ident]
    if r is None:
        raise TimeoutError("Chrome n'a pas repondu.")
    if r.get("erreur"):
        raise OSError("Chrome : %s" % str(r["erreur"])[:200])
    return r


def prochaine_commande_onglets(attente=None):
    """Pour l'extension : la commande suivante, ou None apres `attente`."""
    attente = ONGLETS_ATTENTE_S if attente is None else attente
    c = ONGLETS["cond"]
    with c:
        ONGLETS["vu"] = time.time()
        fin = time.time() + attente
        while not ONGLETS["file"] and time.time() < fin:
            c.wait(max(0.05, fin - time.time()))
        ONGLETS["vu"] = time.time()
        return ONGLETS["file"].pop(0) if ONGLETS["file"] else None


def resultat_onglets(r):
    c = ONGLETS["cond"]
    with c:
        if isinstance(r, dict) and isinstance(r.get("id"), str):
            ONGLETS["resultats"][r["id"]] = r
            c.notify_all()


def _domaine(url):
    try:
        return urllib.parse.urlsplit(url).netloc.lower().removeprefix("www.")
    except ValueError:
        return ""


def nom_onglet(o):
    """Ce a quoi on reconnait un onglet : son titre, son site, sa famille
    (« ferme les Reddit »)."""
    d = _domaine(o.get("url", ""))
    return "%s %s %s" % (o.get("titre") or "", d, _jv.site_de(d))


def agir_onglets(action, cible="", url="", recherche="", tous=False):
    """Ce que Jarvis demande aux onglets. Rend un texte pour lui."""
    if action == "ouvrir":
        adresse = url.strip() if url else (_jv.adresse_google(recherche) if recherche else "")
        if not _jv.lien_permis(adresse):
            raise ValueError("Une adresse web http(s), ou une recherche.")
        commande_onglets("ouvrir", url=adresse)
        return "Nouvel onglet : %s." % (_domaine(adresse) or adresse)
    onglets = commande_onglets("lister").get("onglets") or []
    onglets = [o for o in onglets if isinstance(o, dict) and "id" in o]
    if action == "lister":
        return liste_onglets(onglets) or "Aucun onglet ouvert."
    if action in ("fermer_gauche", "fermer_droite", "garder"):
        gardes = None
        if action == "garder" and cible:
            gardes = _jv.choisir(cible, onglets, nom=nom_onglet, seuil=40, tous=True)
            if not gardes:
                raise LookupError("Aucun onglet ne correspond a « %s » : je n'en ferme aucun." % cible)
        ids = _jv.onglets_a_fermer(onglets, action, gardes)
        if not ids:
            return "Rien a fermer."
        commande_onglets("fermer", ids=ids)
        return "%d onglet%s ferme%s." % (len(ids), "s" if len(ids) > 1 else "", "s" if len(ids) > 1 else "")
    trouves = _jv.choisir(cible, onglets, nom=nom_onglet, seuil=40, tous=tous)
    if not trouves:
        raise LookupError("Aucun onglet ne correspond a « %s »." % cible)
    vises = trouves[:20] if tous else trouves[:1]
    ids = [o["id"] for o in vises]
    noms = " ; ".join((o.get("titre") or _domaine(o.get("url", "")))[:60] for o in vises)
    if action == "fermer":
        commande_onglets("fermer", ids=ids)
        return "Ferme : %s." % noms
    if action == "aller":
        commande_onglets("aller", ids=ids[:1])
        return "Onglet affiche : %s." % noms
    if action in ("couper_son", "remettre_son"):
        commande_onglets("muet", ids=ids, muet=action == "couper_son")
        return ("Son coupe : %s." if action == "couper_son" else "Son remis : %s.") % noms
    raise ValueError("action inconnue : %s" % action)


def liste_onglets(onglets, par_famille=12, titre_max=80):
    """Les onglets rangés par site : « 9 onglets. YouTube (2) : « ... » ; ...
    Reddit (1) : ... » -- titres et domaines, jamais l'adresse entiere."""
    if not onglets:
        return ""
    bouts = []
    for famille, liste in _jv.ranger_onglets(onglets, domaine=lambda o: _domaine(o.get("url", ""))):
        items = ["« %s »%s%s%s" % ((o.get("titre") or "")[:titre_max],
                                   "" if famille not in ("Autres", "Mails") else " (%s)" % _domaine(o.get("url", "")),
                                   " -- affiche" if o.get("actif") else "", " -- joue du son" if o.get("son") else "")
                 for o in liste[:par_famille]]
        reste = len(liste) - par_famille
        bouts.append("%s (%d) : %s%s" % (famille, len(liste), " ; ".join(items),
                                        " ; et %d autres" % reste if reste > 0 else ""))
    return "%d onglets. %s" % (len(onglets), " | ".join(bouts))


def onglets_du_moment():
    """La liste rangée, pour chaque question a Jarvis -- si l'extension est
    branchee et repond vite. Sinon rien : on ne fait pas attendre Jarvis."""
    if not extension_branchee():
        return ""
    try:
        onglets = commande_onglets("lister", delai=1.5).get("onglets") or []
    except Exception:
        return ""
    return liste_onglets([o for o in onglets if isinstance(o, dict)], par_famille=6, titre_max=60)


# « IL MET DU TEMPS A DEMARRER » : la liste des onglets demandait jusqu'a 1,5 s
# a l'extension (morte depuis peu, elle passait encore pour branchee), APRES la
# transcription. Elle part maintenant PENDANT la transcription (voir
# `fil_jarvis_travail`), et la question ne l'attend guere plus.
ONGLETS_BUDGET_S = 0.3
_ONGLETS_AVANCE = {"fil": None, "boite": None, "t": 0.0}


def lancer_onglets(cfg):
    """Demande la liste des onglets en avance, dans son fil."""
    if not cfg.get("jarvis_pc") or not extension_branchee():
        return None
    boite = {}

    def faire():
        try:
            boite["r"] = onglets_du_moment()
        except Exception:
            boite["r"] = ""
    fil = threading.Thread(target=faire, daemon=True)
    _ONGLETS_AVANCE.update(fil=fil, boite=boite, t=time.monotonic())
    fil.start()
    return fil


def onglets_attendus(cfg, budget=None):
    """La liste des onglets pour la question : celle demandee en avance (ou
    demandee maintenant), attendue au plus `budget` secondes -- sinon rien :
    Jarvis n'attend pas l'extension."""
    if not cfg.get("jarvis_pc"):
        return ""
    budget = ONGLETS_BUDGET_S if budget is None else budget
    a = _ONGLETS_AVANCE
    if a["fil"] is None or time.monotonic() - a["t"] > 10.0:
        if lancer_onglets(cfg) is None:
            return ""
    fil, boite = a["fil"], a["boite"]
    a.update(fil=None, boite=None)                 # une liste sert une fois
    fil.join(budget)
    if "r" not in boite:
        print("Jarvis : les onglets tardent, la question part sans eux")
    return boite.get("r") or ""


EXTENSION_MANIFESTE = {
    "manifest_version": 3,
    "name": "Machi Tool - les onglets pour Jarvis",
    "description": "Laisse Jarvis (Machi Tool, sur ce PC) lister, ouvrir, afficher, couper et fermer des onglets.",
    "version": "1.1",
    "permissions": ["tabs", "alarms"],
    "host_permissions": ["http://127.0.0.1/*"],
    "background": {"service_worker": "fond.js"},
}

EXTENSION_FOND = r"""// Machi Tool - les onglets pour Jarvis.
// Demande a Machi Tool (127.0.0.1) s'il a une commande, l'execute avec les
// fonctions d'onglets de Chrome, et repond. Rien d'autre.
importScripts('config.js');
const BASE = 'http://127.0.0.1:' + MACHI.port + '/onglets/';
const ENTETES = { 'X-Onglets-Cle': MACHI.cle };
const pause = ms => new Promise(r => setTimeout(r, ms));
let enCours = false;

async function executer(c) {
  if (c.action === 'lister') {
    const t = await chrome.tabs.query({});
    let courante = null;
    try { courante = (await chrome.windows.getLastFocused()).id; } catch (e) {}
    return { onglets: t.map(o => ({ id: o.id, titre: o.title || '', url: o.url || '', actif: !!o.active,
                                    son: !!o.audible, muet: !!(o.mutedInfo && o.mutedInfo.muted),
                                    position: o.index, epingle: !!o.pinned,
                                    fenetre_courante: o.windowId === courante })) };
  }
  if (c.action === 'ouvrir') {
    if (!/^https?:\/\//.test(String(c.url || ''))) throw new Error('adresse refusee');
    const o = await chrome.tabs.create({ url: c.url, active: true });
    await chrome.windows.update(o.windowId, { focused: true });
    return { texte: 'ouvert' };
  }
  const ids = (c.ids || []).filter(Number.isInteger);
  if (!ids.length) throw new Error('aucun onglet');
  if (c.action === 'fermer') { await chrome.tabs.remove(ids); return { texte: 'ferme' }; }
  if (c.action === 'aller') {
    const o = await chrome.tabs.update(ids[0], { active: true });
    await chrome.windows.update(o.windowId, { focused: true });
    return { texte: 'affiche' };
  }
  if (c.action === 'muet') {
    for (const id of ids) await chrome.tabs.update(id, { muted: !!c.muet });
    return { texte: 'fait' };
  }
  throw new Error('action inconnue');
}

async function boucle() {
  if (enCours) return;
  enCours = true;
  try {
    for (;;) {
      chrome.runtime.getPlatformInfo(() => {});      // garde le service worker eveille
      let r;
      try {
        r = await fetch(BASE + 'attente', { headers: ENTETES, signal: AbortSignal.timeout(25000) });
      } catch (e) { await pause(5000); continue; }
      if (r.status === 204) continue;
      if (r.status !== 200) { await pause(10000); continue; }
      const c = await r.json();
      let rep;
      try { rep = await executer(c); } catch (e) { rep = { erreur: String((e && e.message) || e) }; }
      await fetch(BASE + 'resultat', { method: 'POST', headers: { ...ENTETES, 'Content-Type': 'application/json' },
                                        body: JSON.stringify({ ...rep, id: c.id }) }).catch(() => {});
    }
  } finally { enCours = false; }
}

chrome.runtime.onStartup.addListener(boucle);
chrome.runtime.onInstalled.addListener(boucle);
chrome.alarms.create('machi', { periodInMinutes: 0.5 });
chrome.alarms.onAlarm.addListener(boucle);
boucle();
"""


def preparer_extension(cfg, dossier=None):
    """Ecrit l'extension dans le dossier de Machi Tool (avec le port et sa cle)
    et rend son chemin."""
    if not cfg.get("onglets_cle"):
        cfg["onglets_cle"] = secrets.token_urlsafe(18)
        sauver_config(cfg)
    dossier = dossier or os.path.join(DOSSIER, "extension-chrome")
    os.makedirs(dossier, exist_ok=True)
    port = entier(cfg.get("api_port", 7373), 7373)
    fichiers = {"manifest.json": json.dumps(EXTENSION_MANIFESTE, indent=2, ensure_ascii=False),
                "fond.js": EXTENSION_FOND,
                "config.js": "const MACHI = %s;\n" % json.dumps({"port": port, "cle": cfg["onglets_cle"]})}
    for nom, contenu in fichiers.items():
        with open(os.path.join(dossier, nom), "w", encoding="utf-8") as f:
            f.write(contenu)
    return dossier


# --- LES TEMPERATURES --------------------------------------------------

def memoire_coretemp():
    """Les octets que Core Temp partage (s'il tourne), ou None. Lecture
    seule, en memoire."""
    if os.name != "nt":
        return None
    import ctypes
    from ctypes import wintypes
    k = ctypes.WinDLL("kernel32", use_last_error=True)
    k.OpenFileMappingW.restype = wintypes.HANDLE
    k.OpenFileMappingW.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.LPCWSTR]
    k.MapViewOfFile.restype = ctypes.c_void_p
    k.MapViewOfFile.argtypes = [wintypes.HANDLE, wintypes.DWORD, wintypes.DWORD, wintypes.DWORD, ctypes.c_size_t]
    k.UnmapViewOfFile.argtypes = [ctypes.c_void_p]
    k.CloseHandle.argtypes = [wintypes.HANDLE]
    for nom in ("CoreTempMappingObjectEx", "CoreTempMappingObject"):
        h = k.OpenFileMappingW(0x0004, False, nom)            # FILE_MAP_READ
        if not h:
            continue
        try:
            vue = k.MapViewOfFile(h, 0x0004, 0, 0, _jv.CT_TAILLE)
            if not vue:
                continue
            try:
                return ctypes.string_at(vue, _jv.CT_TAILLE)
            finally:
                k.UnmapViewOfFile(vue)
        finally:
            k.CloseHandle(h)
    return None


def sortie_nvidia_smi():
    """Ce que dit nvidia-smi (installe avec le pilote NVIDIA), ou "". Une
    commande fixe : rien de ce que dit le modele n'y entre."""
    exe = shutil.which("nvidia-smi") or os.path.join(os.environ.get("SystemRoot", r"C:\Windows"), "System32",
                                                     "nvidia-smi.exe")
    if not os.path.isfile(exe) and not shutil.which("nvidia-smi"):
        return ""
    try:
        r = subprocess.run([exe, "--query-gpu=name,temperature.gpu,utilization.gpu,memory.used,memory.total",
                            "--format=csv,noheader,nounits"], capture_output=True, text=True, timeout=6,
                           creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        return r.stdout if r.returncode == 0 else ""
    except Exception:
        return ""


def capteurs_wmi():
    """[(materiel, capteur, °C)] de LibreHardwareMonitor ou OpenHardwareMonitor,
    s'ils tournent."""
    if os.name != "nt":
        return []
    out = []
    try:
        import pythoncom
        import win32com.client
        pythoncom.CoInitialize()
        for espace in ("root\\LibreHardwareMonitor", "root\\OpenHardwareMonitor"):
            try:
                w = win32com.client.GetObject("winmgmts:" + espace)
            except Exception:
                continue
            materiels = {str(m.Identifier): str(m.Name) for m in w.ExecQuery("SELECT Identifier, Name FROM Hardware")}
            for c in w.ExecQuery("SELECT Name, Value, Parent FROM Sensor WHERE SensorType = 'Temperature'"):
                out.append((materiels.get(str(c.Parent), str(c.Parent)), str(c.Name), float(c.Value)))
            if out:
                break
    except Exception:
        pass
    return out


def lire_temperatures():
    return _jv.resume_temperatures(_jv.lire_coretemp(memoire_coretemp()),
                                   _jv.lire_nvidia_smi(sortie_nvidia_smi()), capteurs_wmi())


# --- L'AGENDA -----------------------------------------------------------

AGENDA_JOURS = 14
AGENDA_PASSE = 7        # la frise montre aussi la semaine ecoulee : sommeil, note


def lire_agenda(cfg, jours=AGENDA_JOURS, depuis=None, bilan=False):
    """Les rendez-vous de `depuis` (aujourd'hui) sur `jours`, depuis
    BrainDebugger (les reperes « agenda » ; jamais un « psy ») -- et, avec
    `bilan`, les chiffres des derniers jours : nuits et note de la journee."""
    return _requete_bd("/api/machitool/agenda?depuis=%s&jours=%d%s" % (
        depuis or time.strftime("%Y-%m-%d"), int(jours), "&bilan=1&bilan_jours=%d" % AGENDA_PASSE if bilan else ""),
        None, cfg, 15)


def poser_agenda(cfg, titre, date, fin=None, heure=None):
    """Un rappel dans l'agenda de BrainDebugger : un jour, ou du `date` au `fin`."""
    return _requete_bd("/api/machitool/agenda", {"titre": titre, "date": date, "fin": fin, "heure": heure}, cfg, 15)


# ---------- l'agenda, synchro avec BrainDebugger ----------
# « Fais en sorte que l'agenda soit synchro sur BrainDebugger. » BrainDebugger
# reste la source : la fenetre se relit seule (toutes les minutes, et quand on
# y revient). Ce qu'il a rendu la derniere fois est garde ici (agenda.json) :
# injoignable, la fenetre montre cette copie, et ce qu'on y pose, corrige ou
# retire attend dans une file -- envoye, dans l'ordre, des qu'il repond.

FICHIER_AGENDA = os.path.join(DOSSIER, "agenda.json")
MOIS_AFFICHES = ("Janvier", "Février", "Mars", "Avril", "Mai", "Juin", "Juillet", "Août", "Septembre",
                 "Octobre", "Novembre", "Décembre")
AGENDA_SYNCHRO_S = 60
_AGENDA_VERROU = threading.Lock()


def agenda_local():
    try:
        with open(FICHIER_AGENDA, encoding="utf-8") as f:
            d = json.load(f) or {}
    except Exception:
        d = {}
    d.setdefault("rdv", [])
    d.setdefault("attente", [])
    d.setdefault("quand", 0)
    return d


def _ecrire_agenda_local(d):
    try:
        tmp = FICHIER_AGENDA + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False)
        os.replace(tmp, FICHIER_AGENDA)
    except Exception as e:
        print("Agenda : copie locale impossible (%s)" % type(e).__name__)


def _touche(r, depuis, jusqua):
    return str(r.get("date") or "") <= jusqua and str(r.get("fin") or r.get("date") or "") >= depuis


def memoriser_agenda(rdv, depuis, jusqua):
    """Ce que BrainDebugger vient de rendre pour [depuis, jusqua] remplace la
    copie locale sur cette fenetre de jours ; le reste est garde."""
    with _AGENDA_VERROU:
        d = agenda_local()
        garde = [r for r in d["rdv"] if not _touche(r, depuis, jusqua)]
        d["rdv"] = garde + [dict(r) for r in rdv or []]
        d["quand"] = time.time()
        _ecrire_agenda_local(d)


def _appliquer_attente(rdv, attente):
    """La copie locale, avec ce qui attend d'etre envoye deja applique."""
    rdv = [dict(r) for r in rdv]
    for op in attente:
        if op.get("op") == "poser":
            rdv.append({"id": None, "date": op["date"], "fin": op.get("fin"), "heure": op.get("heure"),
                        "label": op["titre"], "attente": True})
        elif op.get("op") == "supprimer":
            rdv = [r for r in rdv if r.get("id") != op["id"]]
        elif op.get("op") == "modifier":
            for r in rdv:
                if r.get("id") == op["id"]:
                    r.update({k: v for k, v in (("label", op.get("titre")), ("date", op.get("date")),
                                                ("heure", op.get("heure")), ("fin", op.get("fin"))) if v is not None})
                    r["attente"] = True
    return rdv


def envoyer_agenda_en_attente(cfg):
    """Rejoue la file : rend le nombre d'operations parties. Un refus (400) est
    jete -- il ne passera jamais ; une panne arrete la, on reessaiera."""
    with _AGENDA_VERROU:
        d = agenda_local()
        attente = list(d["attente"])
    if not attente or not _cle_presente(cfg):
        return 0
    faites = 0
    for op in attente:
        try:
            if op["op"] == "poser":
                poser_agenda(cfg, op["titre"], op["date"], op.get("fin"), op.get("heure"))
            elif op["op"] == "supprimer":
                retirer_agenda(cfg, op["id"])
            elif op["op"] == "modifier":
                modifier_agenda(cfg, op["id"], **{k: op[k] for k in ("titre", "date", "heure", "fin") if k in op})
        except urllib.error.HTTPError as e:
            if e.code >= 500:
                break
            print("Agenda : operation refusee par BrainDebugger (%d), abandonnee" % e.code)
        except Exception:
            break
        faites += 1
    with _AGENDA_VERROU:
        d = agenda_local()
        d["attente"] = d["attente"][faites:]
        _ecrire_agenda_local(d)
    return faites


def mettre_en_attente(op):
    with _AGENDA_VERROU:
        d = agenda_local()
        d["attente"].append(op)
        _ecrire_agenda_local(d)


def retirer_agenda(cfg, ident):
    return _requete_bd("/api/machitool/agenda", {"supprimer": ident}, cfg, 15)


def modifier_agenda(cfg, ident, **champs):
    return _requete_bd("/api/machitool/agenda", dict(champs, id=ident), cfg, 15)


def lire_agenda_synchro(cfg, depuis, jours, bilan=False):
    """(reponse, None) depuis BrainDebugger -- la file d'attente envoyee d'abord
    --, ou (copie locale, « hors ligne ») s'il ne repond pas. Une erreur de
    BrainDebugger lui-meme (une cle refusee) remonte."""
    try:
        envoyer_agenda_en_attente(cfg)
    except Exception:
        pass
    jusqua = _jv.plus_jours(depuis, int(jours) - 1)
    try:
        r = lire_agenda(cfg, jours, depuis=depuis, bilan=bilan)
        memoriser_agenda(r.get("rendezVous") or [], depuis, jusqua)
        attente = agenda_local()["attente"]
        if attente:
            r["rendezVous"] = _appliquer_attente(r.get("rendezVous") or [], attente)
        return r, None
    except urllib.error.HTTPError as e:
        if e.code < 500:
            raise
        erreur = "BrainDebugger a repondu %d" % e.code
    except Exception:
        erreur = "BrainDebugger injoignable"
    d = agenda_local()
    rdv = [r for r in _appliquer_attente(d["rdv"], d["attente"]) if _touche(r, depuis, jusqua)]
    quand = time.strftime("%d/%m %H:%M", time.localtime(d["quand"])) if d["quand"] else "jamais"
    return {"rendezVous": rdv, "bilan": None}, "%s : copie du %s" % (erreur, quand)


def bilan_local(aujourdhui, jours=AGENDA_PASSE):
    """Le bilan quand BrainDebugger ne le donne pas (plus ancien, injoignable) :
    les nuits que Machi Tool a mesurees lui-meme ; pas de note."""
    out = []
    for k in range(jours - 1, -1, -1):
        d = _jv.plus_jours(aujourdhui, -k)
        try:
            n = sommeil_estime(d) or {}
        except Exception:
            n = {}
        out.append({"date": d, "note": None, "sommeil_h": n.get("sommeil_h"),
                    "coucher": n.get("coucher"), "lever": n.get("reveil")})
    return {"jours": out, "sommeil_mediane": None}


# --- YOUTUBE -----------------------------------------------------------

def ouvrir_youtube(recherche):
    """La premiere video pour cette recherche, ouverte dans Chrome : elle se
    lance toute seule. A defaut, la page des resultats."""
    q = " ".join(str(recherche or "").split())[:200]
    if not q:
        raise ValueError("rien a chercher")
    resultats = "https://www.youtube.com/results?search_query=" + urllib.parse.quote_plus(q)
    video = None
    try:
        req = urllib.request.Request(resultats, headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) "
                          "Chrome/126.0 Safari/537.36",
            "Accept-Language": "fr-FR,fr;q=0.9,en;q=0.8", "Cookie": "SOCS=CAI; CONSENT=YES+"})
        with urllib.request.urlopen(req, timeout=8, context=_contexte_ssl()) as r:
            video = _jv.premiere_video_youtube(r.read(3_000_000).decode("utf-8", "replace"))
    except Exception:
        video = None
    if video:
        ou = ouvrir_dans_chrome("https://www.youtube.com/watch?v=" + video[0])
        return "Video ouverte dans %s : « %s »." % (ou, video[1] or q)
    ou = ouvrir_dans_chrome(resultats)
    return "Resultats YouTube ouverts dans %s (la video n'a pas pu etre choisie seule)." % ou


# --- SPOTIFY -----------------------------------------------------------

_SPOTIFY = {"client": None, "cle": None, "connexion": None}


def spotify_connecte(cfg):
    return bool(str(cfg.get("spotify_client_id") or "").strip() and cfg.get("spotify_refresh"))


def spotify_de(cfg):
    cle = (str(cfg.get("spotify_client_id") or "").strip(), cfg.get("spotify_refresh"))
    if _SPOTIFY["cle"] != cle or _SPOTIFY["client"] is None:
        def sauver(refresh):
            cfg["spotify_refresh"] = refresh
            _SPOTIFY["cle"] = (cle[0], refresh)
            sauver_config(cfg)
        _SPOTIFY["client"], _SPOTIFY["cle"] = _jv.Spotify(cle[0], cle[1], sauver=sauver), cle
    return _SPOTIFY["client"]


def diagnostic_spotify(cfg):
    """« Pourquoi il ne peut pas acceder a l'API Spotify » : pas a pas, en clair."""
    if not str(cfg.get("spotify_client_id") or "").strip():
        return "Pas de Client ID : colle celui de ton app Spotify, puis « Connecter »."
    if not cfg.get("spotify_refresh"):
        return "Pas encore connecte : clique « Connecter » et accepte dans le navigateur."
    try:
        ok, lignes = spotify_de(cfg).diagnostic()
    except Exception as e:
        ok, lignes = False, ["%s : %s" % (type(e).__name__, str(e)[:200])]
    if not cfg.get("jarvis_pc"):
        lignes.append("« Il peut agir sur le PC » est decoche : Jarvis ne peut pas s'en servir.")
        ok = False
    texte = " ".join(lignes)
    print("Spotify : %s" % texte)
    return ("OK. " if ok else "") + texte


def ouvrir_uri_spotify(uri):
    """Le morceau ouvert directement dans l'application (« spotify:track:... »)."""
    if not str(uri or "").startswith("spotify:"):
        raise ValueError("adresse Spotify invalide")
    os.startfile(uri)


def ouvrir_appli_spotify():
    try:
        os.startfile("spotify:")
    except Exception:
        pass


def attendre_retour_oauth(etat, echanger, rappel, delai=180, service="Spotify"):
    """Le retour d'une connexion (Spotify) sur 127.0.0.1:8765/callback,
    une fois : verifie `state`, appelle `echanger(code)` (qui garde le jeton)
    et rend la main. `rappel(message)` dit ou on en est."""
    fini = threading.Event()

    class Retour(http.server.BaseHTTPRequestHandler):
        def log_message(self, *a):
            pass

        def do_GET(self):
            u = urllib.parse.urlsplit(self.path)
            q = dict(urllib.parse.parse_qsl(u.query))
            if u.path != "/callback":
                self.send_response(404)
                self.end_headers()
                return
            ok, message = False, "%s n'a pas ete connecte." % service
            if q.get("state") != etat:
                message = "Reponse inattendue : recommence depuis Machi Tool."
            elif q.get("error"):
                message = "Connexion refusee sur %s (%s)." % (service, q["error"])
            else:
                try:
                    echanger(q.get("code", ""))
                    ok, message = True, "%s est connecte a Machi Tool. Tu peux fermer cet onglet." % service
                except Exception as e:
                    message = str(e)
            corps = ("<!doctype html><meta charset=utf-8><title>Machi Tool</title>"
                     "<body style='font:16px system-ui;padding:40px'>%s</body>" % message).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.end_headers()
            self.wfile.write(corps)
            rappel(message)
            if ok or q.get("error"):
                fini.set()

    serveur = http.server.HTTPServer(("127.0.0.1", _jv.SPOTIFY_PORT), Retour)
    serveur.timeout = 1.0

    def servir():
        limite = time.time() + delai
        try:
            while not fini.is_set() and time.time() < limite:
                serveur.handle_request()
            if not fini.is_set():
                rappel("Pas de retour de %s : recommence." % service)
        finally:
            serveur.server_close()
    t = threading.Thread(target=servir, daemon=True)
    t.start()
    return t


def connecter_spotify(cfg, rappel=None, delai=180):
    """Ouvre la page de connexion de Spotify dans le navigateur et attend son
    retour sur 127.0.0.1:8765, une fois."""
    client_id = str(cfg.get("spotify_client_id") or "").strip()
    if not client_id:
        raise ValueError("Colle d'abord le Client ID de ton app Spotify.")
    verif, defi = _jv.pkce_paire()
    etat = os.urandom(12).hex()
    rappel = rappel or (lambda m: None)

    def echanger(code):
        r = _jv.Spotify.echanger_code(client_id, code, verif)
        cfg["spotify_refresh"] = r["refresh_token"]
        sauver_config(cfg)
        _SPOTIFY["client"] = None
    _SPOTIFY["connexion"] = attendre_retour_oauth(etat, echanger, rappel, delai, "Spotify")
    ouvrir_dans_chrome(_jv.spotify_url_autorisation(client_id, defi, etat))
    rappel("Connecte-toi a Spotify dans le navigateur...")


def capturer_ecran(numero):
    """UNE capture de l'ecran 1 ou 2, en memoire, reduite (1280 px de large au
    plus) et en JPEG : rendue en base64 pour Jarvis, jamais ecrite sur le
    disque. Rien a voir avec la lumiere d'ecran, qui ne garde qu'une couleur."""
    image, n, total = capturer_ecrans([numero])[0]
    return image, n, total


def capturer_ecrans(numeros=None):
    """[(base64, numero, total)] : les ecrans demandes, ou tous (`None`, 0).
    En memoire seulement, comme capturer_ecran. La boule de Jarvis va sur
    chacun le temps de le regarder (JARVIS["regard"])."""
    import mss
    from PIL import Image
    out = []
    with mss.mss() as sct:
        ecrans = sct.monitors[1:]
        if not ecrans:
            raise OSError("aucun ecran")
        voulus = [int(x or 0) for x in (numeros or [0])]
        liste = list(range(1, len(ecrans) + 1)) if 0 in voulus else \
            sorted({max(1, min(len(ecrans), n)) for n in voulus})
        for n in liste:
            JARVIS["regard"] = {"ecran": dict(ecrans[n - 1]), "jusqua": time.time() + 2.5}
            brut = sct.grab(ecrans[n - 1])
            im = Image.frombytes("RGB", brut.size, brut.rgb)
            if im.width > 1280:
                im = im.resize((1280, max(1, im.height * 1280 // im.width)), Image.BILINEAR)
            tampon = io.BytesIO()
            im.save(tampon, "JPEG", quality=70)
            out.append((base64.b64encode(tampon.getvalue()).decode("ascii"), n, len(ecrans)))
    return out


def executer_outil(outil, cfg):
    """Un outil demande par Jarvis, sur le poste. Rend {"id", "texte"} (ou
    "image"), ou {"id", "erreur"} -- jamais d'exception."""
    ident, nom, e = outil.get("id"), outil.get("nom"), outil.get("entree") or {}
    try:
        if nom == "retenir":
            cfg["jarvis_preferences"] = _jv.ajouter_preference(cfg.get("jarvis_preferences"), e.get("preference"))
            sauver_config(cfg)
            return {"id": ident, "texte": "Retenu : %s" % cfg["jarvis_preferences"][-1]}
        if nom == "oublier" and e.get("conversations"):
            n = len(cfg.get("jarvis_souvenirs") or [])
            cfg["jarvis_souvenirs"] = []
            sauver_config(cfg)
            return {"id": ident, "texte": "Oublie : %d souvenir%s de conversations." % (n, "s" if n > 1 else "")}
        if nom == "oublier":
            reste, retirees = _jv.retirer_preference(cfg.get("jarvis_preferences"), e.get("preference", ""),
                                                     tout=bool(e.get("tout")))
            if not retirees:
                return {"id": ident, "texte": "Aucune preference retenue ne correspond."}
            cfg["jarvis_preferences"] = reste
            sauver_config(cfg)
            return {"id": ident, "texte": "Oublie : %s" % " ; ".join(retirees)}
        # MACHI TOOL LUI-MEME : la guirlande, ses routines, les reglages -- a lui,
        # sans les mains sur le PC (« il a tous les droits au niveau de l'application »)
        if nom in ("lumiere", "routine_lumiere", "reglages_machi", "mise_a_jour"):
            return {"id": ident, "texte": outil_application(nom, e, cfg)}
        if nom == "minuteurs":
            return {"id": ident, "texte": outil_minuteurs(e, cfg, langue_jarvis(cfg))}
        if nom == "resume_du_jour":
            return {"id": ident, "texte": outil_resume_du_jour(cfg)}
        # SES TACHES DE FOND ET TES PROJETS : a lui aussi, sans les mains sur le PC
        if nom == "lancer_tache":
            return {"id": ident, "texte": lancer_tache_de_fond(e, cfg)}
        if nom == "taches":
            return {"id": ident, "texte": outil_taches(e, cfg)}
        if nom == "noter_projet":
            cfg["jarvis_projets"] = _jv.ajouter_note_projet(cfg.get("jarvis_projets"), e.get("projet"), e.get("note"))
            sauver_config(cfg)
            return {"id": ident, "texte": "Note dans les projets : %s -- %s" % (e.get("projet"), e.get("note"))}
        if not cfg.get("jarvis_pc"):
            return {"id": ident, "erreur": "Les mains de Jarvis sur le PC sont fermees (Machi Tool > Reglages > Jarvis)."}
        if _jv.groupe_outil(nom):              # ranger les fichiers, reglages de Windows
            return {"id": ident, "texte": outil_pouvoir(nom, e, cfg)}
        if nom == "rechercher_google":
            ou = ouvrir_dans_chrome(_jv.adresse_google(e.get("recherche")))
            return {"id": ident, "texte": "Recherche Google ouverte dans %s." % ou}
        if nom == "lien":
            url = str(e.get("url") or "").strip()
            if not _jv.lien_permis(url):
                return {"id": ident, "erreur": "Adresse refusee : seulement une adresse web http(s)."}
            if e.get("action") == "copier":
                if not copier_presse_papiers(url):
                    return {"id": ident, "erreur": "Le presse-papiers n'a pas pu etre rempli."}
                return {"id": ident, "texte": "Lien copie dans le presse-papiers."}
            return {"id": ident, "texte": "Ouvert dans %s." % ouvrir_dans_chrome(url)}
        if nom == "lancer_appli":
            return {"id": ident, "texte": lancer_appli(e.get("nom"))}
        if nom == "fenetre":
            return {"id": ident, "texte": agir_fenetre(e.get("action") or "lister", e.get("cible") or "",
                                                       bool(e.get("tout")))}
        if nom == "son":
            if e.get("action") == "lister":
                return {"id": ident, "texte": lister_sons()}
            return {"id": ident, "texte": regler_son(e.get("action"), e.get("appli") or "", e.get("niveau"))}
        if nom == "pc":
            a = e.get("action")
            if a == "verrouiller":
                return {"id": ident, "texte": verrouiller_pc()}
            if a in ("veille", "eteindre", "redemarrer", "deconnecter", "fermer_session", "hibernation"):
                return {"id": ident, "erreur": _jv.REFUS_ALIMENTATION}
            if a == "luminosite":
                return {"id": ident, "texte": regler_luminosite(e.get("sens") or "regler", e.get("niveau"))}
            return {"id": ident, "erreur": "action inconnue : %s" % a}
        if nom == "youtube":
            return {"id": ident, "texte": ouvrir_youtube(e.get("recherche"))}
        if nom == "temperatures":
            return {"id": ident, "texte": lire_temperatures()}
        if nom == "onglets":
            return {"id": ident, "texte": agir_onglets(e.get("action") or "lister", e.get("cible") or "",
                                                       e.get("url") or "", e.get("recherche") or "",
                                                       bool(e.get("tous")))}
        if nom == "montrer_agenda":
            # la fenetre s'ouvre dans le fil de l'interface, a son prochain passage
            JARVIS["montrer_agenda"] = time.time()
            return {"id": ident, "texte": "Agenda ouvert a l'ecran."}
        if nom.startswith("spotify_"):
            if not spotify_connecte(cfg):
                return {"id": ident, "erreur": "Spotify n'est pas connecte a Machi Tool (Reglages > Jarvis > Spotify)."}
            sp = spotify_de(cfg)
            if nom == "spotify_jouer":
                return {"id": ident, "texte": sp.jouer(e.get("recherche"), e.get("genre") or "titre",
                                                       bool(e.get("file")), ouvrir_appli_spotify,
                                                       ouvrir_uri=ouvrir_uri_spotify)}
            if nom == "spotify_en_cours":
                c = sp.en_cours()
                return {"id": ident, "texte": ("%s : « %s » de %s." % ("En lecture" if c["lecture"] else "En pause",
                                                                       c["titre"], c["artistes"])) if c
                        else "Rien ne joue sur Spotify."}
            if nom == "spotify_aimer":
                return {"id": ident, "texte": sp.aimer()}
        if nom == "chercher_historique":
            if not cfg.get("jarvis_historique"):
                return {"id": ident, "erreur": "L'historique du navigateur n'est pas permis dans Machi Tool."}
            return {"id": ident, "texte": _jv.chercher_historique(
                e.get("recherche"), _jv.fichiers_historique(), e.get("jours") or 90, lire=lire_historique_copie)}
        if nom == "musique":
            return {"id": ident, "texte": touche_media(e.get("action"))}
        if nom == "spotify":
            return {"id": ident, "texte": ouvrir_spotify(e.get("recherche"))}
        if nom == "regarder_ecran":
            if not cfg.get("jarvis_ecran"):
                return {"id": ident, "erreur": "Regarder l'ecran n'est pas permis dans Machi Tool."}
            vus = capturer_ecrans([e.get("ecran", 0)])
            if len(vus) == 1:
                image, n, total = vus[0]
                return {"id": ident, "image": image, "texte": "Ecran %d sur %d." % (n, total)}
            return {"id": ident, "images": [v[0] for v in vus],
                    "texte": "Les %d ecrans, dans l'ordre : %s." % (len(vus), ", ".join("ecran %d" % v[1] for v in vus))}
        bases = bases_dossiers()
        if nom == "lister_dossier":
            ch = _jv.resoudre_chemin(e.get("chemin"), bases)
            return {"id": ident, "texte": _jv.lister_dossier(ch, max(1, min(2, int(e.get("profondeur") or 1))))}
        if nom == "chercher_fichiers":
            ch = _jv.resoudre_chemin(e.get("dans") or "~", bases)
            crit = _jv.criteres(e.get("mots") or e.get("nom") or "", e.get("type"), e.get("jours"))
            res, coupe = _jv.trouver_fichiers(ch, crit)
            JARVIS["recherche"] = {"racine": ch, "criteres": crit, "resultats": res, "coupe": coupe}
            return {"id": ident, "texte": _jv.resume_recherche(ch, crit, res, coupe)}
        if nom == "affiner_recherche":
            r = JARVIS.get("recherche")
            if not r:
                return {"id": ident, "erreur": "Aucune recherche en cours : commence par chercher_fichiers."}
            racine = _jv.resoudre_chemin(e["dans"], bases) if e.get("dans") else r["racine"]
            crit, garde = _jv.affiner(r, e.get("ajouter") or "", e.get("retirer") or "",
                                      e.get("type"), e.get("jours"))
            coupe = False if garde is not None else r["coupe"]
            if garde is None or racine != r["racine"]:
                garde, coupe = _jv.trouver_fichiers(racine, crit)
            JARVIS["recherche"] = {"racine": racine, "criteres": crit, "resultats": garde, "coupe": coupe}
            return {"id": ident, "texte": _jv.resume_recherche(racine, crit, garde, coupe)}
        if nom == "ouvrir_resultats":
            r = JARVIS.get("recherche")
            if not r or not r["resultats"]:
                return {"id": ident, "erreur": "Aucun resultat de recherche a ouvrir."}
            res = r["resultats"]
            if e.get("numeros"):
                choisis = []
                for n in e["numeros"]:
                    if not (1 <= int(n) <= len(res)):
                        return {"id": ident, "erreur": "Il n'y a pas de numero %s (de 1 a %d)." % (n, len(res))}
                    choisis.append(res[int(n) - 1])
            elif len(res) > OUVRIR_MAX:
                return {"id": ident, "erreur": "Il y en a %d : c'est trop pour tout ouvrir d'un coup (%d au plus). "
                                               "Affine, ou dis lesquels." % (len(res), OUVRIR_MAX)}
            else:
                choisis = res
            for chemin, _, _ in choisis[:OUVRIR_MAX]:
                if _jv.touche_a_l_alimentation(chemin):
                    return {"id": ident, "erreur": _jv.REFUS_ALIMENTATION}
            for chemin, _, _ in choisis[:OUVRIR_MAX]:
                startfile_sur(chemin)
            return {"id": ident, "texte": "Ouverts : %s." % " ; ".join(os.path.basename(c) for c, _, _ in choisis[:OUVRIR_MAX])}
        if nom == "creer_fichier":
            if _jv.touche_a_l_alimentation(e.get("chemin") or "", e.get("contenu") or ""):
                return {"id": ident, "erreur": _jv.REFUS_ALIMENTATION}
            ch = creer_fichier(_jv.resoudre_chemin(e.get("chemin"), bases), e.get("contenu"), dossiers_proteges())
            if e.get("ouvrir"):
                startfile_sur(ch)
            return {"id": ident, "texte": "Cree : %s" % ch}
        if nom == "ecrire_note":
            dossier = os.path.join(bases.get("documents") or os.path.join(bases["home"], "Documents"),
                                   "Notes de Jarvis")
            ch, neuve = ecrire_note(dossier, e.get("texte"), e.get("titre") or "", e.get("ajouter_a") or "")
            if e.get("ouvrir", True):
                startfile_sur(ch)
            return {"id": ident, "texte": ("Note ecrite : %s" if neuve else "Ajoute a la note : %s") % ch}
        if nom == "creer_dossier":
            ch = _jv.resoudre_chemin(e.get("chemin"), bases)
            return {"id": ident, "texte": _jv.creer_dossier(ch, dossiers_proteges())}
        if nom == "ouvrir":
            ch = _jv.resoudre_chemin(e.get("chemin"), bases)
            if not os.path.exists(ch):
                return {"id": ident, "erreur": "Rien a cet endroit : %s" % ch}
            if _jv.touche_a_l_alimentation(ch):
                return {"id": ident, "erreur": _jv.REFUS_ALIMENTATION}
            startfile_sur(ch)
            return {"id": ident, "texte": "Ouvert : %s" % ch}
        return {"id": ident, "erreur": "outil inconnu : %s" % nom}
    except Exception as ex:
        erreur = str(ex)[:300] if isinstance(ex, (_jv.ErreurSpotify, ValueError, LookupError, RuntimeError)) \
            else "%s : %s" % (type(ex).__name__, str(ex)[:300])
        # « Spotify fait de la resistance » ne disait pas POURQUOI : la cause
        # exacte va au journal, et sous « Spotify » dans la page Jarvis
        print("Jarvis : l'outil %s a echoue -- %s" % (nom, erreur))
        if str(nom).startswith("spotify"):
            JARVIS["spotify_message"] = "Derniere erreur (%s) : %s" % (time.strftime("%H:%M"), erreur)
        return {"id": ident, "erreur": erreur}


def outils_de_jarvis(etat, cfg):
    """Les outils d'un tour : ceux qui touchent aux fichiers ou a l'ecran
    attendent le code (ou une session ouverte) ; ceux-la mis a part, on
    execute, on renvoie, et Jarvis continue -- cinq tours au plus.

    « Selon la gravite » (voir _jv.palier_outil) : le code d'abord (s'il en
    faut un), puis le « oui ? » pour ce qui ne s'annule pas (fermer de force,
    installer), puis tout s'execute. `etat["refus"]` : {rang: erreur} deja
    decides (code verrouille, « non » a la question)."""
    L = langue_jarvis(cfg)
    outils = etat["outils"]
    refus = dict(etat.get("refus") or {})
    # mains fermees : ces outils seront refuses, inutile de demander le code
    besoin = [i for i, o in enumerate(outils) if i not in refus and _palier(o, cfg) == _jv.PALIER_CODE]
    if besoin and cfg.get("jarvis_code_actif") and not acces_ouvert():
        if time.time() < float(JARVIS.get("verrou_jusqua") or 0):
            refus.update({i: "Acces verrouille apres trois codes faux : reessayer dans quelques minutes."
                          for i in besoin})
        elif not code_regle(cfg):
            refus.update({i: "Aucun code d'acces n'est regle dans Machi Tool (Reglages > Jarvis) : les dossiers, "
                             "les fichiers et l'ecran restent fermes." for i in besoin})
        else:
            JARVIS["attente_code"] = dict(etat, refus=refus, expire=time.time() + 30, essais=0)
            print("Jarvis : code d'acces demande")
            return dire(phrase("code_demande", L), suite="toujours", langue=L, tour=etat.get("conv"))
    if not etat.get("oui_donne") and demander_oui(etat, refus, cfg):
        return None
    # UN DROIT DONNE DANS CE LOT N'OUVRE PAS LE RESTE DU LOT. Rien n'a encore
    # tourne : `avant` est le palier de chacun tel que la personne l'a vu.
    # Pendant l'execution, un outil ferme au depart (son groupe s'ouvre en
    # route) ou qui demande un « oui » qu'elle n'a pas donne pour lui est
    # refuse -- le tour suivant le reproposera, par son code ou sa question.
    avant = {i: _palier(o, cfg) for i, o in enumerate(outils)}
    confirmes = set(etat.get("oui") or []) if etat.get("oui_donne") else set()
    resultats = []
    for i, o in enumerate(outils):
        if i not in refus:
            maintenant = _palier(o, cfg)
            if avant[i] is None and maintenant is not None:
                refus[i] = REFUS_MEME_LOT
            elif maintenant == _jv.PALIER_OUI and i not in confirmes:
                refus[i] = REFUS_SANS_OUI
        resultats.append({"id": o.get("id"), "erreur": refus[i]} if i in refus else executer_outil(o, cfg))
    return continuer_jarvis(etat, resultats, cfg)


def repondre_au_code(texte, cfg):
    """La phrase qui suit « Code d'acces ? ». Ni journalisee, ni envoyee."""
    att = JARVIS.get("attente_code") or {}
    L = langue_jarvis(cfg)
    if _jv.code_juste(texte, cfg.get("jarvis_code_sel"), cfg.get("jarvis_code_empreinte")):
        JARVIS["attente_code"] = None
        JARVIS["acces_jusqua"] = time.time() + ACCES_DUREE_S
        print("Jarvis : code d'acces juste")
        jouer_son("fait")
        att["conv"] = JARVIS.get("tour")
        return outils_de_jarvis(att, cfg)
    att["essais"] = int(att.get("essais") or 0) + 1
    print("Jarvis : code d'acces faux (%d)" % att["essais"])
    if att["essais"] >= 3:
        JARVIS["attente_code"] = None
        JARVIS["verrou_jusqua"] = time.time() + VERROU_DUREE_S
        poser_led("erreur", 1.2)
        return dire(phrase("code_refuse", L), langue=L, tour=JARVIS.get("tour"))
    att["expire"] = time.time() + 30
    JARVIS["attente_code"] = att
    return dire(phrase("code_faux", L), suite="toujours", langue=L, tour=JARVIS.get("tour"))


def outil_application(nom, e, cfg):
    """La guirlande, les routines de lumiere, les reglages de Machi Tool. Rend
    le texte du resultat ; ValueError/LookupError disent ce qui ne va pas."""
    a = e.get("action")
    if nom == "lumiere":
        if a == "couleur":
            c = _jv.couleur_lue(e.get("couleur"))
            if not c:
                raise ValueError("Couleur illisible : %s" % e.get("couleur"))
            ETAT["forcage"] = {"couleur": hex_vers_rgb(c), "nom": "%s (Jarvis)" % c, "manuel": True, "expire": 0}
            return "Guirlande en %s." % c
        if a == "eteindre":
            ETAT["forcage"] = {"couleur": (0, 0, 0), "nom": "Eteinte (Jarvis)", "manuel": True, "expire": 0}
            return "Guirlande eteinte."
        if a == "normale":
            ANIMATION["etapes"] = []
            f = ETAT.get("forcage")
            if f and f.get("manuel"):
                ETAT["forcage"] = None
            ETAT["pause"] = False
            return "La guirlande reprend son mode (%s)." % cfg.get("mode", "applications")
        if a == "animation":
            d = jouer_animation(e.get("etapes"), e.get("repetitions", 1), "Jarvis", bool(e.get("tenir")))
            return "Animation lancee (%.0f s)." % d
        if a == "mode":
            m = _jv.valeur_reglage("mode", CONFIG_DEFAUT, e.get("mode"))
            executer_commande({"action": "mode", "mode": m}, cfg)
            return "La guirlande suit maintenant : %s." % m
        raise ValueError("action inconnue : %s" % a)
    if nom == "routine_lumiere":
        routines = [r for r in cfg.get("routines_lumiere") or [] if isinstance(r, dict)]
        if a == "lister":
            return _jv.resume_routines(routines) or "Aucune routine pour l'instant."
        if a == "creer":
            r = _jv.routine_propre(e, par_jarvis=True)
            cfg["routines_lumiere"] = _jv.ranger_routine(routines, r)
            sauver_config(cfg)
            return "Routine gardee : " + _jv.decrire_routine(r)
        i = _jv.trouver_routine(routines, e.get("nom") or "")
        if i is None:
            raise LookupError("Aucune routine ne s'appelle « %s »." % (e.get("nom") or ""))
        r = routines[i]
        if a == "supprimer":
            cfg["routines_lumiere"] = routines[:i] + routines[i + 1:]
            sauver_config(cfg)
            return "Routine supprimee : %s." % r["nom"]
        if a in ("activer", "desactiver"):
            r["actif"] = a == "activer"
            cfg["routines_lumiere"] = routines
            sauver_config(cfg)
            return "Routine %s : %s." % ("activee" if r["actif"] else "desactivee", r["nom"])
        if a == "essayer":
            d = jouer_animation(r["etapes"], r.get("repetitions", 1), r["nom"], r.get("tenir"))
            return "Routine jouee (%.0f s) : %s." % (d, r["nom"])
        raise ValueError("action inconnue : %s" % a)
    if nom == "reglages_machi":
        if a == "lire":
            return _jv.lire_reglages(cfg, CONFIG_DEFAUT, e.get("cle") or "")
        if a == "couleur_appli":
            cfg["regles"], texte = _jv.poser_couleur_appli(cfg.get("regles"), e.get("nom"), e.get("couleur"),
                                                           e.get("mots"))
            sauver_config(cfg)
            return texte
        if a == "changer":
            cle = str(e.get("cle") or "").strip()
            if not _jv.reglage_modifiable(cle, CONFIG_DEFAUT):
                raise ValueError("« %s » n'est pas un reglage que je peux changer." % cle)
            v = _jv.valeur_reglage(cle, CONFIG_DEFAUT, e.get("valeur"))
            if cle == "mode":
                executer_commande({"action": "mode", "mode": v}, cfg)
            else:
                if cle in ("collecte_active", "collecte_envoi"):
                    # un seul interrupteur, comme dans la fenetre (et la question le nomme)
                    cle = "collecte_active"
                    cfg["collecte_envoi"] = v
                avant = cfg.get(cle)
                cfg[cle] = v
                sauver_config(cfg)
                appliquer_reglage(cle, avant, v, cfg)
            if cle.startswith("jarvis_"):
                envoyer_oreille(config_oreille(cfg))
            if cle == "jarvis_actif" and not v:
                # il s'eteint : ce qu'il preparait tombe (comme « Jarvis ecoute » decoche)
                _en_fond(terminer_conversation)
            # la fenetre des reglages le montre -- et ne le reecrira pas a l'ancienne valeur
            REGLAGES_A_RELIRE.add(cle)
            if cle == "collecte_active":
                REGLAGES_A_RELIRE.add("collecte_envoi")
            return "%s = %s." % (cle, v)
        raise ValueError("action inconnue : %s" % a)
    if nom == "mise_a_jour":
        return outil_mise_a_jour(a, cfg)
    raise ValueError("outil inconnu : %s" % nom)


# Les reglages changes hors de la fenetre (Jarvis, le menu de l'icone) : la
# boucle de la fenetre les relit (Panneau.relire_reglages), sinon « Enregistrer »
# y reecrirait l'ancienne valeur. Jamais de Tk hors de son fil : un ensemble,
# vide par `surveiller`.
REGLAGES_A_RELIRE = set()


def appliquer_reglage(cle, avant, v, cfg):
    """Ce que la fenetre fait en plus d'ecrire la valeur : sans ca, « coupe le
    journal d'activite » etait note mais le journal continuait."""
    if cle == "collecte_active" and bool(avant) != bool(v):
        demarrer_activite(cfg)                  # arrete ou relance le fil du journal
    elif cle == "api_active" and bool(avant) != bool(v):
        _en_fond(lambda: demarrer_api(cfg))     # arrete ou relance le serveur local
    elif cle == "jarvis_pc" and not v:
        JARVIS["acces_jusqua"] = 0.0            # ses mains fermees : la session aussi


# ---------- ses mises a jour ----------
# « Fait en sorte que Jarvis puisse [...] annoncer une mise a jour (il peut la
# lancer) ». Le meme chemin que le bouton et le menu de l'icone (`travail_maj`,
# pose par main dans DECLENCHER_MAJ) : un seul chemin vers l'installeur.

DECLENCHER_MAJ = [None]
REFUS_MAJ_DECOCHE = ("« Il peut proposer et lancer les mises a jour » est decoche dans ses options : "
                     "je ne lance pas la mise a jour.")
MAJ_ANNONCEES = set()          # (quoi, version) deja dits : une fois chacun
MAJ_POSE_ATTENTE_S = 6.0       # le temps de dire « je reviens » avant de partir


MAJ_JARVIS_LIBRE_S = 60       # au plus, avant de poser malgre tout


def attendre_jarvis_libre(borne=MAJ_JARVIS_LIBRE_S, pas=0.5):
    """Attend (dans le fil des mises a jour) qu'il ne soit plus en train de
    comprendre, reflechir ou parler -- ni d'attendre une reponse, ni en
    seance avec le psychologue -- pour que la pose ne le coupe pas."""
    fin = time.time() + borne
    while time.time() < fin and ETAT.get("en_marche", True) and (
            JARVIS.get("mode") == "psy"                  # une seance : on ne la coupe pas
            or JARVIS.get("etat") in ("comprend", "pense", "parle")
            or (JARVIS.get("etat") == "ecoute" and (JARVIS.get("parole_vue") or JARVIS.get("attente_oui")
                                                   or JARVIS.get("attente_code")))):
        time.sleep(pas)


def etat_maj_en_texte():
    lignes = ["Version installee : %s." % VERSION, "Etat : %s" % MAJ.get("message", "")]
    if MAJ.get("etat") in ("disponible", "prete", "a_poser", "telechargement") and MAJ.get("version"):
        lignes.append("Nouvelle version : %s." % MAJ["version"])
        notes = " ".join(str(MAJ.get("notes") or "").split())
        if notes:
            lignes.append("Ce qu'elle change : %s" % notes[:600])
    return "\n".join(lignes)


def outil_mise_a_jour(action, cfg):
    if action == "etat":
        return etat_maj_en_texte()
    occupe = MAJ.get("etat") in ("verification", "telechargement")
    if action == "verifier":
        # une version deja telechargee ou qui attend d'etre posee ne redevient
        # pas « disponible » (la pose en attente serait perdue)
        if not occupe and MAJ.get("etat") not in ("prete", "a_poser"):
            verifier_maj(cfg)
        return etat_maj_en_texte()
    if action == "installer":
        if not cfg.get("jarvis_annoncer_maj", True):
            raise RuntimeError(REFUS_MAJ_DECOCHE)
        if not FIGE:
            raise RuntimeError("En mode script, la mise a jour se fait par git pull : rien n'a ete touche.")
        if occupe:
            return "Deja en cours : %s" % MAJ.get("message", "")
        if MAJ.get("etat") == "a_poser":
            return ("La version %s attend deja : elle se pose des que la fenetre de Machi Tool est "
                    "refermee, ou apres deux minutes sans clavier ni souris." % MAJ.get("version"))
        declencher = DECLENCHER_MAJ[0]
        if declencher is None:
            raise RuntimeError("Les mises a jour ne sont pas encore pretes (Machi Tool demarre).")
        declencher("installer")
        return ("Mise a jour lancee : Machi Tool verifie, telecharge la nouvelle version s'il y en a une, "
                "puis redemarre un instant (s'il est deja a jour, rien ne change).")
    raise ValueError("action inconnue : %s" % action)


def annoncer_maj(quoi, version, cfg=None):
    """Il dit, une fois par version, qu'une mise a jour attend (« disponible »),
    qu'il part l'installer (« pose ») ou qu'il est revenu (« posee ») -- si
    « a voix haute » est coche ; sinon la mise a jour se pose en silence.
    Rend True s'il le dit tout de suite (sinon c'est en file, ou rien)."""
    cfg = CFG if cfg is None else cfg
    if not version or not cfg.get("jarvis_actif") or not cfg.get("jarvis_annoncer_maj", True) \
            or not cfg.get("jarvis_maj_a_voix_haute", False):
        return False
    if (quoi, version) in MAJ_ANNONCEES:
        return False
    MAJ_ANNONCEES.add((quoi, version))
    L = langue_jarvis(cfg)
    texte = _jv.annonce_maj(quoi, version, L)
    if not texte:
        return False
    if quoi == "disponible" and (JARVIS.get("mode") == "psy" or JARVIS.get("attente_oui")
                                 or JARVIS.get("attente_code")
                                 or time.time() < float(JARVIS.get("calme_jusqua") or 0) - CALME_S + 60):
        # pas chez le psychologue, pas pendant une question, pas juste apres
        # un conge : la notification suffit, la verification suivante
        # redira « disponible ». (La pose, elle, attend qu'il soit libre et
        # la seance finie -- attendre_jarvis_libre -- puis se dit toujours.)
        MAJ_ANNONCEES.discard((quoi, version))
        return False
    if quoi == "posee":
        # au demarrage, sa voix n'est pas encore chargee : en file, dite des qu'elle l'est
        ANNONCES.append((texte, L, time.time()))
        return False
    return annoncer(texte, L)


# ---------- ses nouveaux pouvoirs ----------
# « Ranger les fichiers », « Reglages de Windows », « Prendre des
# initiatives » -- et « selon la gravite » : le code d'acces pour les
# fichiers et Windows, un simple « oui ? » avant ce qui ne s'annule pas
# (fermer de force une appli, installer), le reste directement. Les decisions
# sont dans jarvis.py (palier_outil, refus_chemin, choisir_initiative...) ;
# ici, les gestes, le journal d'annulation et les sauvegardes. Aucune saisie
# clavier simulee, aucun presse-papiers.

OUI_DUREE_S = 20
REFUS_OUI = "Refuse par la personne : rien n'a ete fait."
REFUS_MEME_LOT = ("Pas permis au moment de la demande (le droit vient d'etre donne dans ce meme tour) : "
                  "rien n'a ete fait -- redemande-le maintenant.")
REFUS_SANS_OUI = "Pas fait : ce geste demande un « oui » de la personne, qu'elle n'a pas donne pour lui."
ANNULATIONS = {"liste": None}          # le journal d'annulation (lu du disque une fois)
_WINGET = {"recherches": {}}
WINGET_RECHERCHE_S = 300
INITIATIVES = {"recentes": [], "deja": {}, "actif_depuis": None, "grave_jusqua": 0.0,
               "mesures": {}, "mesure_t": 0.0, "mesure_en_cours": False}
INITIATIVE_MESURE_S = 60               # temperatures et volume, lus hors de la veille


def _texte_erreur(ex):
    if isinstance(ex, (ValueError, LookupError, RuntimeError)):
        return str(ex)[:300]
    return "%s : %s" % (type(ex).__name__, str(ex)[:300])


def _palier(o, cfg):
    """Le palier d'un outil ici, ou None s'il sera refuse de toute facon
    (mains fermees, groupe pas permis) : inutile alors de rien demander."""
    nom = o.get("nom")
    # « n'importe quel setting » : ceux qui lui donnent des droits, et poser
    # une mise a jour (l'application redemarre), la personne les confirme
    p = _jv.palier_application(nom, o.get("entree"))
    if p == _jv.PALIER_POUVOIR:
        # chaque fois un « J'active ... ? » qui NOMME le reglage : une session
        # de code ouverte pour autre chose (dix minutes) ne le couvre jamais --
        # sinon un texte qu'il vient de lire pourrait lui faire couper le code.
        # Avec le code, et pas de session : le code d'abord, puis la question.
        return _jv.PALIER_CODE if cfg.get("jarvis_code_actif") and not acces_ouvert() else _jv.PALIER_OUI
    if p:
        return p
    if nom in OUTILS_SANS_CODE:
        return _jv.PALIER_DIRECT
    if not cfg.get("jarvis_pc"):
        return None
    groupe = _jv.groupe_outil(nom)
    if groupe and not cfg.get("jarvis_" + groupe):
        return None
    return _jv.palier_outil(nom, o.get("entree"), OUTILS_SANS_CODE)


def geste_oui(o, langue="fr"):
    """Ce que dira la question (« Je ferme de force Discord ? ») ; leve si
    l'outil sera refuse de toute facon -- alors on ne demande rien."""
    e = o.get("entree") or {}
    if o.get("nom") == "forcer_fermeture":
        return "forcer", _joli(appli_a_fermer(e.get("cible")))
    if o.get("nom") == "reglages_machi":
        cle = str(e.get("cle") or "").strip()
        if not _jv.reglage_modifiable(cle, CONFIG_DEFAUT):
            raise ValueError("« %s » n'est pas un reglage que je peux changer." % cle)
        return "reglage", _jv.libelle_reglage(cle, _jv.valeur_reglage(cle, CONFIG_DEFAUT, e.get("valeur")), langue)
    if o.get("nom") == "mise_a_jour":
        if not CFG.get("jarvis_annoncer_maj", True):
            raise RuntimeError(REFUS_MAJ_DECOCHE)
        if not FIGE:
            raise RuntimeError("En mode script, la mise a jour se fait par git pull : rien n'a ete touche.")
        v = MAJ.get("version") if MAJ.get("etat") in ("disponible", "prete") else ""
        return "maj_machi", v or ("the latest version" if langue == "en" else "la dernière version")
    action = e.get("action")
    return action, paquet_voulu(e.get("nom"))["nom"]


def demander_oui(etat, refus, cfg):
    """Pose la question « oui ? » si un outil du tour ne s'annule pas. Rend
    True si elle est posee (on attend la reponse)."""
    gestes, indices = [], []
    L = langue_jarvis(cfg)
    for i, o in enumerate(etat["outils"]):
        if i in refus or _palier(o, cfg) != _jv.PALIER_OUI:
            continue
        try:
            gestes.append(geste_oui(o, L))
            indices.append(i)
        except Exception as ex:
            refus[i] = _texte_erreur(ex)
    if not gestes:
        return False
    JARVIS["attente_oui"] = dict(etat, refus=refus, oui=indices, expire=time.time() + OUI_DUREE_S,
                                 tour_oui=JARVIS.get("tour"))
    print("Jarvis : il demande « oui ? » (%s)" % ", ".join(g for g, _ in gestes))
    dire(_jv.question_oui(gestes, L), suite="toujours", langue=L, tour=etat.get("conv"))
    return True


def oui_en_attente():
    """La question « oui ? » attend-elle sa reponse ? Pas apres 20 s, ni
    apres un nouvel appel : le silence, c'est non (rien n'est fait)."""
    att = JARVIS.get("attente_oui")
    if not att:
        return False
    if att.get("tour_oui") != JARVIS.get("tour") or time.time() > float(att.get("expire") or 0):
        JARVIS["attente_oui"] = None
        print("Jarvis : « oui ? » reste sans reponse -- rien n'est fait")
        return False
    return True


def repondre_au_oui(texte, brut, cfg):
    """La phrase qui suit « Je ferme de force Discord ? ». Un oui franc fait ;
    tout le reste annule (« refuse par la personne »), et Jarvis le sait."""
    att = JARVIS.get("attente_oui") or {}
    JARVIS["attente_oui"] = None
    if _jv.renvoi(texte) or _jv.renvoi(brut) or _jv.adieu(texte):
        return terminer_conversation()
    att["conv"] = JARVIS.get("tour")
    if _jv.normaliser(texte).replace("-", " ").strip(" '") in _OUI:
        print("Jarvis : oui")
        return outils_de_jarvis(dict(att, oui_donne=True), cfg)
    print("Jarvis : pas de oui -- rien n'est fait")
    refus = dict(att.get("refus") or {})
    refus.update({i: REFUS_OUI for i in att.get("oui") or []})
    return outils_de_jarvis(dict(att, refus=refus, oui_donne=True), cfg)


def outil_pouvoir(nom, e, cfg):
    """Les outils des groupes « fichiers » et « windows ». Rend le texte du
    resultat ; leve ce qui ne va pas (executer_outil le dit a Jarvis)."""
    groupe = _jv.groupe_outil(nom)
    if groupe == "fichiers" and not cfg.get("jarvis_fichiers"):
        raise RuntimeError("Ranger les fichiers n'est pas permis dans Machi Tool (Reglages > Jarvis).")
    if groupe == "windows" and not cfg.get("jarvis_windows"):
        raise RuntimeError("Les reglages de Windows ne sont pas permis dans Machi Tool (Reglages > Jarvis).")
    if nom == "reglage_windows":
        return reglage_windows(e.get("reglage"), e.get("action") or "lire", e.get("appareil") or "")
    if nom == "forcer_fermeture":
        return forcer_fermeture(e.get("cible"))
    if nom == "installer_appli":
        return installer_appli(e.get("action"), e.get("nom"), cfg)
    if nom == "annuler_fichier":
        return annuler_fichier()
    bases = bases_dossiers()

    def chemin(cle):
        # jamais « rien » compris comme le dossier personnel
        if not str(e.get(cle) or "").strip():
            raise ValueError("%s vide" % cle)
        return _jv.resoudre_chemin(e.get(cle), bases)
    if nom == "lire_fichier":
        return lire_fichier_texte(chemin("chemin"))
    if nom == "deplacer":
        return deplacer_fichier(chemin("source"), chemin("destination"), bases)
    if nom == "renommer":
        return renommer_fichier(chemin("chemin"), e.get("nouveau_nom"), bases)
    if nom == "corbeille":
        return jeter_fichier(chemin("chemin"), bases)
    if nom == "modifier_fichier":
        return modifier_fichier_texte(chemin("chemin"), e.get("remplacements"), e.get("ajouter_a_la_fin") or "")
    raise ValueError("outil inconnu : %s" % nom)


# --- RANGER LES FICHIERS -----------------------------------------------

def dossiers_machi():
    """Le dossier de Machi Tool (sa config, ses cles) et celui de son programme."""
    prog = os.path.dirname(os.path.abspath(sys.executable if getattr(sys, "frozen", False) else __file__))
    return [DOSSIER, prog]


def _gardes(bases=None):
    """(dossiers du systeme, dossiers de base, dossiers de Machi Tool)."""
    return (_jv.dossiers_systeme(os.environ), list((bases or bases_dossiers()).values()), dossiers_machi())


def _fichier_annulations():
    return os.path.join(dossier_jarvis(), "annulations.json")


def dossier_sauvegardes():
    return os.path.join(dossier_jarvis(), "sauvegardes")


def journal_annulations():
    if ANNULATIONS["liste"] is None:
        try:
            with open(_fichier_annulations(), encoding="utf-8") as f:
                ANNULATIONS["liste"] = [o for o in (json.load(f) or []) if isinstance(o, dict)]
        except Exception:
            ANNULATIONS["liste"] = []
    return ANNULATIONS["liste"]


def _ecrire_annulations():
    os.makedirs(dossier_jarvis(), exist_ok=True)
    ch = _fichier_annulations()
    with open(ch + ".part", "w", encoding="utf-8") as f:
        json.dump(ANNULATIONS["liste"] or [], f, ensure_ascii=False)
    os.replace(ch + ".part", ch)


def noter_annulation(operation):
    ANNULATIONS["liste"] = _jv.journal_ajoute(journal_annulations(), dict(operation, t=time.time()))
    _ecrire_annulations()


def purger_sauvegardes(maintenant=None):
    """Les copies d'avant une modification : trente jours, pas plus."""
    d = dossier_sauvegardes()
    try:
        fichiers = [(n, os.path.getmtime(os.path.join(d, n))) for n in os.listdir(d)]
    except OSError:
        return []
    perimees = _jv.sauvegardes_perimees(fichiers, time.time() if maintenant is None else maintenant)
    for n in perimees:
        try:
            os.remove(os.path.join(d, n))
        except OSError:
            pass
    return perimees


def _fichier_texte(ch):
    """Un fichier TEXTE qui existe, hors du systeme et de Machi Tool."""
    systeme, _, machi = _gardes()
    if not os.path.isfile(ch):
        raise FileNotFoundError("pas de fichier ici : %s" % ch)
    r = _jv.refus_chemin(ch, systeme, (), machi)
    if r:
        raise PermissionError(r)
    ext = os.path.splitext(ch)[1].lower()
    if ext not in _jv.EXTENSIONS_TEXTE:
        raise PermissionError("seulement un fichier texte (%s), pas « %s »"
                              % (" ".join(sorted(_jv.EXTENSIONS_TEXTE)), ext or "sans extension"))
    return ch


def lire_fichier_texte(ch):
    ch = _fichier_texte(ch)
    with open(ch, "rb") as f:
        octets = f.read(_jv.FICHIER_MODIFIABLE_MAX)
    texte, _ = _jv.decoder_texte(octets)
    return _jv.texte_lu(ch, texte)


def deplacer_fichier(source, destination, bases=None):
    systeme, b, machi = _gardes(bases)
    src, cible = _jv.preparer_deplacement(source, destination, systeme, b, machi)
    shutil.move(src, cible)
    noter_annulation({"op": "deplacer", "de": src, "vers": cible})
    return "Deplace : %s -> %s (annulable)." % (src, cible)


def renommer_fichier(chemin, nouveau_nom, bases=None):
    systeme, b, machi = _gardes(bases)
    src, cible = _jv.preparer_renommage(chemin, nouveau_nom, systeme, b, machi)
    os.rename(src, cible)
    noter_annulation({"op": "renommer", "de": src, "vers": cible})
    return "Renomme : %s -> %s (annulable)." % (os.path.basename(src), os.path.basename(cible))


def jeter_fichier(chemin, bases=None):
    """A la corbeille de Windows -- jamais une suppression definitive."""
    systeme, b, machi = _gardes(bases)
    src = os.path.normpath(os.path.abspath(chemin))
    if not os.path.exists(src):
        raise FileNotFoundError("rien a cet endroit : %s" % src)
    r = _jv.refus_chemin(src, systeme, b, machi, source=True)
    if r:
        raise PermissionError(r)
    envoyer_a_la_corbeille(src)
    if os.path.exists(src):
        raise RuntimeError("Windows ne l'a pas mis a la corbeille : %s" % src)
    noter_annulation({"op": "corbeille", "chemin": src})
    return "A la corbeille : %s (annulable)." % src


def envoyer_a_la_corbeille(chemin):
    """SHFileOperation avec « annulable » (FOF_ALLOWUNDO) : la Corbeille. Un
    lecteur sans corbeille (cle USB, reseau) est refuse -- Windows y
    supprimerait pour de bon."""
    if os.name != "nt":
        raise OSError("la corbeille ne se pilote que sous Windows")
    import ctypes
    from ctypes import wintypes
    racine = os.path.splitdrive(chemin)[0] + "\\"
    if ctypes.WinDLL("kernel32").GetDriveTypeW(racine) != 3:            # DRIVE_FIXED
        raise PermissionError("pas de corbeille sur ce lecteur (amovible ou reseau) : je ne supprime jamais "
                              "pour de bon")

    class SHFILEOPSTRUCTW(ctypes.Structure):
        _fields_ = [("hwnd", wintypes.HWND), ("wFunc", wintypes.UINT), ("pFrom", wintypes.LPCWSTR),
                    ("pTo", wintypes.LPCWSTR), ("fFlags", ctypes.c_ushort), ("fAnyOperationsAborted", wintypes.BOOL),
                    ("hNameMappings", ctypes.c_void_p), ("lpszProgressTitle", wintypes.LPCWSTR)]
    # FO_DELETE ; FOF_ALLOWUNDO | FOF_NOCONFIRMATION | FOF_SILENT | FOF_WANTNUKEWARNING (Windows
    # previent s'il allait supprimer au lieu de jeter)
    op = SHFILEOPSTRUCTW(None, 3, chemin + "\0", None, 0x40 | 0x10 | 0x4 | 0x4000, False, None, None)
    r = ctypes.WinDLL("shell32").SHFileOperationW(ctypes.byref(op))
    if r or op.fAnyOperationsAborted:
        raise OSError("la corbeille a refuse (code %s)" % r)


def restaurer_de_la_corbeille(chemin):
    """Le remet a sa place depuis la Corbeille (le verbe « undelete » du
    shell). Rend True si c'est fait."""
    if os.name != "nt":
        raise OSError("la corbeille ne se pilote que sous Windows")
    import pythoncom
    import win32com.client
    pythoncom.CoInitialize()
    bac = win32com.client.Dispatch("Shell.Application").NameSpace(10)
    dossier, nom = os.path.split(chemin)
    trouve = None
    for item in bac.Items():
        try:
            origine = str(item.ExtendedProperty("System.Recycle.DeletedFrom") or "")
        except Exception:
            origine = ""
        origine = origine or str(bac.GetDetailsOf(item, 1) or "")
        if os.path.normcase(origine.rstrip("\\")) == os.path.normcase(dossier.rstrip("\\")) and \
                str(item.Name) in (nom, os.path.splitext(nom)[0]):
            trouve = item
    if trouve is None:
        return False
    trouve.InvokeVerb("undelete")
    for _ in range(30):
        if os.path.exists(chemin):
            return True
        time.sleep(0.1)
    return os.path.exists(chemin)


def modifier_fichier_texte(ch, remplacements, ajout=""):
    """Un fichier TEXTE modifie : chaque « avant » doit y etre (sinon rien
    n'est ecrit) ; une copie d'avant est gardee (annulable, trente jours)."""
    ch = _fichier_texte(ch)
    if os.path.getsize(ch) > _jv.FICHIER_MODIFIABLE_MAX:
        raise ValueError("fichier trop gros pour que je le reecrive (%d octets)" % os.path.getsize(ch))
    with open(ch, "rb") as f:
        texte, encodage = _jv.decoder_texte(f.read())
    nouveau, n = _jv.appliquer_modification(texte, remplacements, ajout)
    try:
        octets = nouveau.encode(encodage)
    except UnicodeEncodeError:
        raise ValueError("ces caracteres ne tiennent pas dans l'encodage du fichier (%s)" % encodage)
    purger_sauvegardes()
    os.makedirs(dossier_sauvegardes(), exist_ok=True)
    sauve = _jv.chemin_libre(os.path.join(dossier_sauvegardes(), time.strftime("%Y%m%d-%H%M%S-")
                                          + os.path.basename(ch)))
    shutil.copy2(ch, sauve)
    with open(ch, "wb") as f:
        f.write(octets)
    noter_annulation({"op": "modifier", "chemin": ch, "sauvegarde": sauve})
    return "Modifie : %s (%d remplacement%s%s). La version d'avant est gardee : annulable." % (
        ch, n, "s" if n > 1 else "", ", ajout a la fin" if ajout else "")


def annuler_fichier():
    """« Annule » : defait la derniere operation de fichier de Jarvis."""
    journal = journal_annulations()
    if not journal:
        return "Aucune operation de fichier a annuler."
    op = journal[-1]
    ANNULATIONS["liste"] = journal[:-1]
    _ecrire_annulations()
    systeme, _, machi = _gardes()
    if op.get("op") in ("deplacer", "renommer"):
        de, vers = op.get("de") or "", op.get("vers") or ""
        if not os.path.exists(vers):
            raise LookupError("Introuvable, je ne peux pas le remettre : %s (deplace ou supprime depuis ?)" % vers)
        r = _jv.refus_chemin(de, systeme, (), machi)
        if r:
            raise PermissionError(r)
        retour = de
        if os.path.exists(de) and os.path.normcase(de) != os.path.normcase(vers):
            retour = _jv.chemin_libre(de)
        shutil.move(vers, retour)
        return "Annule : %s est revenu a %s." % (os.path.basename(vers), retour)
    if op.get("op") == "modifier":
        ch, sauve = op.get("chemin") or "", op.get("sauvegarde") or ""
        if not os.path.isfile(sauve):
            raise LookupError("La copie d'avant n'existe plus (plus de %d jours ?) : %s" % (_jv.SAUVEGARDE_JOURS, ch))
        shutil.copyfile(sauve, ch)
        return "Annule : %s a retrouve son contenu d'avant." % ch
    if op.get("op") == "corbeille":
        ch = op.get("chemin") or ""
        if os.path.exists(ch):
            return "Il est deja revenu : %s." % ch
        try:
            ok = restaurer_de_la_corbeille(ch)
        except Exception as ex:
            print("Jarvis : corbeille -- %s" % ex)
            ok = False
        if ok:
            return "Sorti de la corbeille : %s." % ch
        return ("Je n'arrive pas a le sortir de la corbeille moi-meme : « %s » y est (il venait de %s). "
                "Dans la Corbeille : clic droit, Restaurer." % (os.path.basename(ch), os.path.dirname(ch)))
    raise ValueError("operation inconnue dans le journal : %s" % op.get("op"))


# --- QUELQUES REGLAGES DE WINDOWS -----------------------------------------

def _commande(args, delai):
    """Une commande Windows standard, sans fenetre, avec un delai. Rend
    (code, sortie)."""
    if os.name != "nt":
        raise OSError("%s : seulement sous Windows" % os.path.basename(args[0]))
    r = subprocess.run(args, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=delai,
                       creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
    return r.returncode, (r.stdout or "") + (r.stderr or "")


def _powershell(script, delai=25):
    exe = shutil.which("powershell") or os.path.join(os.environ.get("SystemRoot", r"C:\Windows"), "System32",
                                                     "WindowsPowerShell", "v1.0", "powershell.exe")
    return _commande([exe, "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", script], delai)


def ouvrir_parametres(reglage):
    page = _jv.PAGES_PARAMETRES[reglage]
    startfile_sur(page)
    return page


def reglage_windows(reglage, action="lire", appareil=""):
    """Wi-Fi, Bluetooth, mode sombre, sortie audio, ne pas deranger : une
    liste fermee. Ce qui ne se fait pas sans administrateur ou sans API
    publique ouvre la bonne page des Parametres, et le dit."""
    r, a = _jv.reglage_windows_valide(reglage, action)
    if os.name != "nt":
        raise OSError("les reglages de Windows ne se pilotent que sous Windows")
    if r == "ne_pas_deranger":
        page = ouvrir_parametres(r)
        return ("Windows ne laisse pas une appli lire ni changer « Ne pas deranger » : la page des Parametres "
                "est ouverte (%s), c'est un clic." % page)
    try:
        if r in ("wifi", "bluetooth"):
            return _radio(r, a)
        if r == "mode_sombre":
            return _mode_sombre(a)
        return _sortie_audio(a, appareil)
    except (ValueError, LookupError):
        raise
    except Exception as ex:
        print("Jarvis : reglage %s impossible (%s)" % (r, ex))
        page = ouvrir_parametres(r)
        return "Je n'y arrive pas directement (%s) : la page des Parametres est ouverte (%s)." % (
            _texte_erreur(ex)[:120], page)


def _radio(genre, action):
    nom = {"wifi": "Wi-Fi", "bluetooth": "Bluetooth"}[genre]
    code, sortie = _powershell(_jv.script_radio(genre, None if action == "lire" else action == "activer"))
    etat = ([l.strip() for l in sortie.splitlines() if l.strip()] or [""])[-1]
    if etat == "ABSENT":
        return "Pas de %s sur ce PC." % nom
    if etat not in ("On", "Off"):
        raise RuntimeError("l'API Radios ne repond pas (%s)" % " ".join(sortie.split())[-120:])
    if action != "lire" and etat != ("On" if action == "activer" else "Off"):
        raise RuntimeError("Windows a refuse")
    return "%s %s." % (nom, "active" if etat == "On" else "desactive")


def _mode_sombre(action):
    import winreg
    cle = r"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize"
    if action == "lire":
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, cle) as k:
            clair = winreg.QueryValueEx(k, "AppsUseLightTheme")[0]
        return "Mode sombre %s." % ("desactive" if clair else "active")
    clair = 0 if action == "activer" else 1
    with winreg.OpenKey(winreg.HKEY_CURRENT_USER, cle, 0, winreg.KEY_SET_VALUE) as k:
        for n in ("AppsUseLightTheme", "SystemUsesLightTheme"):
            winreg.SetValueEx(k, n, 0, winreg.REG_DWORD, clair)
    import ctypes
    res = ctypes.c_size_t(0)
    # WM_SETTINGCHANGE « ImmersiveColorSet » : les fenetres ouvertes suivent
    ctypes.windll.user32.SendMessageTimeoutW(0xFFFF, 0x1A, 0, "ImmersiveColorSet", 0x2, 3000, ctypes.byref(res))
    return "Mode sombre %s." % ("active" if action == "activer" else "desactive")


def sorties_audio():
    """([(id, nom)], id de celle par defaut) : les sorties audio actives."""
    import comtypes
    from pycaw.pycaw import AudioUtilities, IMMDeviceEnumerator
    try:
        from pycaw.constants import CLSID_MMDeviceEnumerator
    except ImportError:
        from pycaw.pycaw import CLSID_MMDeviceEnumerator
    comtypes.CoInitialize()
    en = comtypes.CoCreateInstance(CLSID_MMDeviceEnumerator, IMMDeviceEnumerator, comtypes.CLSCTX_INPROC_SERVER)
    coll = en.EnumAudioEndpoints(0, 1)                   # eRender, DEVICE_STATE_ACTIVE
    out = []
    for i in range(coll.GetCount()):
        dev = coll.Item(i)
        ident = dev.GetId()
        try:
            nom = AudioUtilities.CreateDevice(dev).FriendlyName or ident
        except Exception:
            nom = ident
        out.append((ident, nom))
    return out, en.GetDefaultAudioEndpoint(0, 1).GetId()


def poser_sortie_audio(ident):
    """La sortie par defaut, pour les trois roles de Windows (IPolicyConfig,
    l'interface du panneau Son ; en echec, la page des Parametres s'ouvre)."""
    import comtypes
    from comtypes import GUID, COMMETHOD, HRESULT, IUnknown
    from ctypes import c_void_p, c_wchar_p, c_int
    vide = lambda n: COMMETHOD([], HRESULT, n, (["in"], c_void_p, "a"))

    class IPolicyConfig(IUnknown):
        _iid_ = GUID("{f8679f50-850a-41cf-9c72-430f290290c8}")
        _methods_ = [vide(n) for n in ("GetMixFormat", "GetDeviceFormat", "ResetDeviceFormat", "SetDeviceFormat",
                                        "GetProcessingPeriod", "SetProcessingPeriod", "GetShareMode", "SetShareMode",
                                        "GetPropertyValue", "SetPropertyValue")] + [
            COMMETHOD([], HRESULT, "SetDefaultEndpoint", (["in"], c_wchar_p, "ident"), (["in"], c_int, "role")),
            vide("SetEndpointVisibility")]
    comtypes.CoInitialize()
    pc = comtypes.CoCreateInstance(GUID("{870af99c-171d-4f9e-af0d-e63df40c2bc9}"), IPolicyConfig,
                                   comtypes.CLSCTX_ALL)
    for role in (0, 1, 2):
        pc.SetDefaultEndpoint(ident, role)


def _sortie_audio(action, appareil):
    sorties, defaut = sorties_audio()
    if action == "lire":
        return "Sortie audio : %s." % next((n for i, n in sorties if i == defaut), "inconnue")
    if action == "lister":
        return "Sorties audio : %s." % " ; ".join(n + (" (celle en service)" if i == defaut else "")
                                                   for i, n in sorties)
    trouves = _jv.choisir(appareil, [(n, i) for i, n in sorties], seuil=40)
    if not trouves:
        raise LookupError("Aucune sortie audio ne s'appelle « %s » (il y a : %s)."
                          % (appareil, ", ".join(n for _, n in sorties) or "aucune"))
    if len(trouves) > 1:
        raise LookupError("Plusieurs sorties correspondent : %s. Laquelle ?" % ", ".join(n for n, _ in trouves))
    nom, ident = trouves[0]
    poser_sortie_audio(ident)
    return "Le son sort maintenant par %s." % nom


# --- FERMER UNE APPLI BLOQUEE -----------------------------------------------

def processus_ouverts():
    """[(pid, nom de l'exe)]."""
    if os.name != "nt":
        raise OSError("fermer une appli de force ne se fait que sous Windows")
    import psutil
    return [(p.info["pid"], p.info["name"] or "") for p in psutil.process_iter(["pid", "name"])]


def terminer_processus(pids):
    if os.name != "nt":
        raise OSError("fermer une appli de force ne se fait que sous Windows")
    import psutil
    tues = []
    for pid in pids:
        try:
            p = psutil.Process(pid)
            p.kill()
            tues.append(p)
        except psutil.NoSuchProcess:
            pass
    psutil.wait_procs(tues, timeout=5)
    return len(tues)


def appli_a_fermer(cible):
    """L'exe designe par le nom d'une fenetre ou d'une appli (jamais un PID)."""
    processus = [n for _, n in processus_ouverts()]          # hors Windows : l'erreur claire, d'abord
    return _jv.appli_a_fermer(cible, [(t, p) for _, t, p in fenetres_ouvertes()], processus)


def forcer_fermeture(cible):
    exe = appli_a_fermer(cible)
    moi = {os.getpid(), os.getppid()}
    pids = [pid for pid, n in processus_ouverts() if n.lower() == exe.lower() and pid not in moi]
    if not pids:
        raise LookupError("« %s » ne tourne plus." % _joli(exe))
    n = terminer_processus(pids)
    return "Ferme de force : %s (%d processus)." % (_joli(exe), n)


# --- INSTALLER UNE APPLI (winget) ---------------------------------------------

def _winget(args, delai):
    exe = shutil.which("winget") if os.name == "nt" else None
    if os.name == "nt" and not exe:
        raise RuntimeError("winget est absent (le « Programme d'installation d'application » du Microsoft Store).")
    return _commande([exe or "winget"] + list(args) + ["--accept-source-agreements", "--disable-interactivity"],
                     delai)


def chercher_paquets(nom):
    n = _jv.nom_de_paquet(nom)
    vu = _WINGET["recherches"].get(n.lower())
    if vu and time.time() - vu[0] < WINGET_RECHERCHE_S:
        return vu[1]
    _, sortie = _winget(["search", n], 60)
    res = _jv.lire_winget(sortie)
    _WINGET["recherches"][n.lower()] = (time.time(), res)
    return res


def paquet_voulu(nom):
    """Le paquet (un seul) ; jamais un paquet qui gere l'alimentation du PC."""
    n = _jv.nom_de_paquet(nom)
    if _jv.paquet_touche_a_l_alimentation(n):
        raise PermissionError(_jv.REFUS_ALIMENTATION)
    p = _jv.choisir_paquet(n, chercher_paquets(n))
    if _jv.paquet_touche_a_l_alimentation(p["nom"], p["id"]):
        raise PermissionError(_jv.REFUS_ALIMENTATION)
    return p


def installer_appli(action, nom, cfg):
    """chercher : ce que winget connait ; installer / mettre_a_jour : UN
    paquet, sans interaction ni redemarrage -- jamais « upgrade --all ».
    L'installation tourne en fond ; il dit quand c'est fini."""
    if action == "chercher":
        n = _jv.nom_de_paquet(nom)
        res = chercher_paquets(n)
        if not res:
            return "winget ne trouve rien pour « %s »." % n
        return "Trouve par winget : %s." % " ; ".join("%s (%s%s)" % (r["nom"], r["id"],
                                                                        ", " + r["version"] if r["version"] else "")
                                                         for r in res[:8])
    if action not in ("installer", "mettre_a_jour"):
        raise ValueError("action : chercher | installer | mettre_a_jour")
    p = paquet_voulu(nom)
    args = ["install" if action == "installer" else "upgrade", "--id", p["id"], "--exact", "--silent",
            "--accept-package-agreements"]
    _en_fond(lambda: finir_installation(action, p, args, cfg))
    return "%s de %s (%s) lancee par winget, en fond : Machi Tool dira quand c'est fini." % (
        "Installation" if action == "installer" else "Mise a jour", p["nom"], p["id"])


def finir_installation(action, p, args, cfg):
    try:
        code, sortie = _winget(args, 1800)
    except Exception as ex:
        code, sortie = -1, str(ex)
    L = langue_jarvis(cfg)
    ok = code == 0
    print("Jarvis : winget %s %s -> %s%s" % (args[0], p["id"], code,
                                             "" if ok else " (%s)" % " ".join(str(sortie).split())[-200:]))
    if L == "en":
        texte = ("%s is %s." % (p["nom"], "installed" if action == "installer" else "up to date") if ok
                 else "The %s of %s failed." % ("installation" if action == "installer" else "update", p["nom"]))
    else:
        texte = ("C'est fait : %s est %s." % (p["nom"], "installé" if action == "installer" else "à jour") if ok
                 else "L'%s de %s a échoué." % ("installation" if action == "installer" else "mise à jour", p["nom"]))
    annoncer_resultat(texte, cfg)
    return texte


def annoncer_resultat(texte, cfg):
    """Un resultat qui arrive plus tard : dit s'il est libre, sinon en notification."""
    if (JARVIS.get("etat") in ("attente", None) and JARVIS.get("mode") != "psy"
            and not (JARVIS.get("attente_code") or JARVIS.get("attente_oui"))):
        return dire(texte, suite=False, langue=langue_jarvis(cfg), tour=JARVIS.get("tour"), spontane=True)
    n = JARVIS_CROCHETS.get("notifier")
    if n:
        n("Jarvis", texte)


# --- SES PETITES INITIATIVES, toujours annoncees -----------------------------

def _mesurer_pour_initiatives():
    """Temperatures et volume, dans un fil a part : nvidia-smi peut prendre six
    secondes, et la veille ne doit jamais attendre."""
    m = {"t": time.time()}
    try:
        cpu = _jv.lire_coretemp(memoire_coretemp())
        if cpu:
            m.update(cpu=max(cpu["temperatures"]), tjmax=cpu.get("tjmax"))
    except Exception:
        pass
    try:
        temps = [g["temperature"] for g in _jv.lire_nvidia_smi(sortie_nvidia_smi()) if g.get("temperature") is not None]
        if temps:
            m["gpu"] = max(temps)
    except Exception:
        pass
    try:
        import comtypes
        comtypes.CoInitialize()
        v = _volume_general()
        if not v.GetMute():
            m["volume"] = round(v.GetMasterVolumeLevelScalar() * 100)
    except Exception:
        pass
    INITIATIVES.update(mesures=m, mesure_en_cours=False)


def _lancer_mesures(t):
    if os.name == "nt" and not INITIATIVES["mesure_en_cours"] and t - INITIATIVES["mesure_t"] >= INITIATIVE_MESURE_S:
        INITIATIVES.update(mesure_t=t, mesure_en_cours=True)
        _en_fond(_mesurer_pour_initiatives)


def signaux_initiatives(cfg, t):
    m = INITIATIVES["mesures"] if t - float(INITIATIVES["mesures"].get("t") or 0) < 5 * 60 else {}
    return {"actif": bool(cfg.get("jarvis_actif")), "etat": JARVIS.get("etat"), "mode": JARVIS.get("mode"),
            "en_attente": bool(JARVIS.get("attente_code") or JARVIS.get("attente_oui") or JARVIS.get("suite_active")),
            "voix_occupee": bool(getattr(VOIX, "parle", False) or getattr(VOIX, "file", None)
                                 or getattr(VOIX, "attentes", None)),
            "plein_ecran": plein_ecran_occupe(t), "calme_jusqua": JARVIS.get("calme_jusqua"),
            "heure": time.localtime(t).tm_hour, "inactivite_s": secondes_inactivite(),
            "temp_cpu": m.get("cpu"), "tjmax": m.get("tjmax"), "temp_gpu": m.get("gpu"), "volume": m.get("volume")}


def suivre_activite(inactivite_s, t):
    """Depuis quand tu es sur le PC sans pause (cinq minutes loin = une pause).
    Apres une pause, la proposition d'en faire une peut revenir."""
    if inactivite_s >= _jv.INITIATIVE_PRESENCE_S:
        INITIATIVES["actif_depuis"] = None
        INITIATIVES["deja"].pop("pause", None)
        return 0.0
    if INITIATIVES["actif_depuis"] is None:
        INITIATIVES["actif_depuis"] = t
    return t - INITIATIVES["actif_depuis"]


def veiller_initiatives(cfg, maintenant=None, signaux=None):
    """Depuis sa veille (chaque seconde) : une petite initiative, TOUJOURS
    annoncee (a voix haute, ou en notification si la voix est coupee) -- si
    on les a permises, et si la porte commune le laisse parler. Rend ce
    qu'il a dit, ou None. `signaux` : pour les tests, ce que le PC dirait."""
    try:
        t = time.time() if maintenant is None else maintenant
        oui_en_attente()                          # un « oui ? » reste sans reponse : il expire
        if not cfg.get("jarvis_initiatives"):
            return None
        if JARVIS.get("psy_grave"):
            INITIATIVES["grave_jusqua"] = t + _jv.INITIATIVE_APRES_GRAVE_S
        if signaux is None:
            _lancer_mesures(t)
            signaux = signaux_initiatives(cfg, t)
        s = dict(signaux, maintenant=t, langue=langue_jarvis(cfg), recentes=INITIATIVES["recentes"],
                 grave_jusqua=max(float(signaux.get("grave_jusqua") or 0), INITIATIVES["grave_jusqua"]))
        s["activite_continue_s"] = suivre_activite(float(s.get("inactivite_s") or 0), t)
        choix = _jv.choisir_initiative(s, INITIATIVES["deja"])
        if not choix or _jv.parole_spontanee_refusee(s, choix["nuit_permise"]):
            return None
        if choix.get("volume") is not None:
            regler_son("regler", "", choix["volume"])
        INITIATIVES["recentes"] = [x for x in INITIATIVES["recentes"] if t - x < 3600] + [t]
        INITIATIVES["deja"][choix["cle"]] = t
        print("Jarvis : initiative (%s)" % choix["cle"])
        dire(choix["texte"], suite=False, langue=langue_jarvis(cfg), tour=JARVIS.get("tour"), spontane=True)
        return choix["texte"]
    except Exception as e:
        print("Jarvis : initiative impossible (%s)" % e)
        return None


# ---------- ses taches de fond ----------
# « Que Jarvis puisse accomplir des taches (rechercher des choses sur le
# cote ?). » Jarvis (l'outil `lancer_tache`) demande ; on la lance chez
# BrainDebugger, qui la fait tourner sans nous (Claude, le web, la reflexion).
# Un fil vient voir ou elle en est ; finie, le texte complet est range dans
# jarvis/taches/ (un .md qu'on ouvre d'un clic), et Jarvis l'annonce a voix
# haute des qu'il n'est pas occupe. Rien de tout cela n'entre dans le journal.

TACHE_SONDE_S = 6
TACHE_ANNONCE_S = 15 * 60      # au-dela, une tache prete n'est plus annoncee a voix haute
TACHE_ABANDON_S = 20 * 60
TACHES_VERROU = threading.Lock()
TACHES_PRETES = []            # les taches finies pas encore annoncees


def _fichier_taches():
    return os.path.join(dossier_jarvis(), "taches.json")


def lire_taches():
    try:
        with open(_fichier_taches(), encoding="utf-8") as f:
            return [t for t in (json.load(f) or []) if isinstance(t, dict)]
    except Exception:
        return []


def _ecrire_taches(taches):
    os.makedirs(dossier_jarvis(), exist_ok=True)
    chemin = _fichier_taches()
    with open(chemin + ".part", "w", encoding="utf-8") as f:
        json.dump(_jv.taches_recentes(taches)[:_jv.TACHES_GARDEES], f, ensure_ascii=False)
    os.replace(chemin + ".part", chemin)


def maj_tache(ident, **champs):
    """Met a jour une tache (ou l'ajoute) ; rend la tache a jour."""
    with TACHES_VERROU:
        taches = lire_taches()
        for t in taches:
            if t.get("id") == ident:
                t.update(champs)
                break
        else:
            t = dict(champs, id=ident)
            taches.append(t)
        _ecrire_taches(taches)
        return dict(t)


def lancer_tache_de_fond(e, cfg, suivre=True):
    """La tache part chez BrainDebugger ; un fil la suit. Rend ce que Jarvis
    doit savoir (il le dit en une phrase)."""
    demande = str(e.get("demande") or "").strip()
    if not demande:
        raise ValueError("demande vide")
    genre = e.get("genre") if e.get("genre") in ("recherche", "reflexion") else "recherche"
    titre = _jv.titre_tache(e.get("titre"), demande)
    try:
        r = _requete_bd("/api/machitool/tache",
                        {"demande": demande[:8000], "genre": genre, "titre": titre, "langue": langue_jarvis(cfg),
                         "projets": str(cfg.get("jarvis_projets") or "")[:_jv.PROJETS_MAX]}, cfg, 30)
    except urllib.error.HTTPError as ex:
        if ex.code == 404:
            raise RuntimeError("BrainDebugger ne connait pas encore les taches de fond : il faut le redeployer.")
        raise RuntimeError(_detail_http(ex) or "BrainDebugger a refuse la tache (%d)." % ex.code)
    t = maj_tache(r["id"], titre=titre, genre=genre, demande=demande[:2000], etat="en_cours", debut=time.time())
    print("Jarvis : tache de fond lancee (%s)" % genre)
    if suivre:
        threading.Thread(target=suivre_tache, args=(t["id"], cfg), daemon=True).start()
    return "Tache lancee : « %s ». Machi Tool previendra quand elle sera prete (quelques minutes)." % titre


def suivre_tache(ident, cfg, dormir=time.sleep, horloge=time.time):
    """Vient voir ou en est la tache, jusqu'a ce qu'elle finisse. Un reseau
    qui tousse ne l'arrete pas ; un serveur qui l'a oubliee (redemarre), si."""
    debut = horloge()
    while True:
        dormir(TACHE_SONDE_S)
        try:
            r = _requete_bd("/api/machitool/tache?id=" + urllib.parse.quote(ident), None, cfg, 30)
        except urllib.error.HTTPError as ex:
            if ex.code in (404, 401):
                return terminer_tache(ident, {"etat": "erreur", "erreur": _detail_http(ex) or "tache perdue"})
            r = {}
        except Exception:
            r = {}
        if r.get("etat") in ("fini", "erreur"):
            try:
                return terminer_tache(ident, r)
            except Exception as ex:             # un disque plein : dit, pas « en cours » pour toujours
                print("Jarvis : tache de fond impossible a ranger (%s)" % ex)
                return terminer_tache(ident, {"etat": "erreur", "erreur": "rangement impossible : %s" % ex})
        if horloge() - debut > TACHE_ABANDON_S:
            return terminer_tache(ident, {"etat": "erreur", "erreur": "trop longue : abandonnee"})


def terminer_tache(ident, r):
    """Range le resultat, et le met dans la file des annonces."""
    champs = {"etat": r.get("etat"), "fin": time.time()}
    if r.get("etat") == "fini":
        avant = next((t for t in lire_taches() if t.get("id") == ident), {})
        dossier = os.path.join(dossier_jarvis(), "taches")
        os.makedirs(dossier, exist_ok=True)
        chemin = os.path.join(dossier, _jv.nom_fichier_tache(avant.get("titre"), avant.get("debut") or time.time()))
        with open(chemin, "w", encoding="utf-8") as f:
            f.write("# %s\n\n> %s\n\n%s\n" % (avant.get("titre") or "Tache", " ".join(str(avant.get("demande") or "")
                                                                                     .split())[:600],
                                             str(r.get("texte") or "")))
        champs.update(resume=str(r.get("resume") or "")[:600], fichier=chemin)
    else:
        champs["erreur"] = str(r.get("erreur") or "")[:300]
    t = maj_tache(ident, **champs)
    print("Jarvis : tache de fond %s" % t.get("etat"))
    TACHES_PRETES.append(t)
    poser_led("fait" if t.get("etat") == "fini" else "erreur", 1.2)
    notifier = JARVIS_CROCHETS.get("notifier")
    if notifier:
        notifier("Jarvis", _jv.pour_la_voix(_jv.annonce_tache(t, langue_jarvis(CFG)), 240))
    return t


def annoncer_taches(cfg):
    """Depuis sa veille (chaque seconde) : une tache prete, et Jarvis libre (pas
    en train d'ecouter, de reflechir ou de parler, pas chez le psychologue) ->
    il l'annonce, sans ecouter apres (« lis-la moi » : on l'appelle)."""
    if not TACHES_PRETES:
        return None
    if not (cfg.get("jarvis_actif") and cfg.get("jarvis_annoncer_taches", True)):
        TACHES_PRETES.clear()               # la notification a suffi
        return None
    if JARVIS.get("etat") not in ("attente", None) or JARVIS.get("mode") == "psy":
        return None
    if time.time() < float(JARVIS.get("calme_jusqua") or 0) - CALME_S + 60:
        return None                        # on vient de le congedier : une minute de calme
    t = TACHES_PRETES.pop(0)
    # ratee, ou prete depuis longtemps (tu etais absent) : la notification suffit
    if t.get("etat") != "fini" or time.time() - float(t.get("fin") or time.time()) > TACHE_ANNONCE_S:
        return None
    texte = _jv.annonce_tache(t, langue_jarvis(cfg))
    # une annonce, pas une conversation : il n'ecoute pas apres
    dire(texte, suite=False, langue=langue_jarvis(cfg), tour=JARVIS.get("tour"), spontane=True)
    return texte


def reprendre_taches(cfg):
    """Au demarrage : les taches encore en cours sont suivies de nouveau
    (BrainDebugger les garde quelques heures)."""
    for t in lire_taches():
        if t.get("etat") == "en_cours" and t.get("id"):
            if time.time() - float(t.get("debut") or 0) > TACHE_ABANDON_S:
                maj_tache(t["id"], etat="erreur", erreur="interrompue")
            else:
                threading.Thread(target=suivre_tache, args=(t["id"], cfg), daemon=True).start()


def outil_taches(e, cfg):
    taches = _jv.taches_recentes(lire_taches())
    L = langue_jarvis(cfg)
    if e.get("action") != "lire":
        return _jv.lister_taches(taches, langue=L)
    n = int(e.get("numero") or 1)
    if not 1 <= n <= len(taches):
        raise LookupError("Il n'y a pas de tache numero %d (%d en tout)." % (n, len(taches)))
    t = taches[n - 1]
    if t.get("etat") != "fini":
        return _jv.lister_taches([t], langue=L)
    try:
        with open(t["fichier"], encoding="utf-8") as f:
            texte = f.read()
    except Exception:
        texte = t.get("resume") or ""
    return "%s\n\n%s" % (t.get("titre") or "", texte[:6000])


def capacites_jarvis(cfg):
    """Ce que Jarvis peut faire ici, dit a BrainDebugger a chaque question :
    ses mains, ses yeux, l'historique -- et ce qu'il retient de toi."""
    pc = bool(cfg.get("jarvis_pc"))
    return {"outils": pc, "ecran": pc and bool(cfg.get("jarvis_ecran")),
            "navigation": pc and bool(cfg.get("jarvis_historique")),
            "spotify": pc and spotify_connecte(cfg),
            "onglets": pc and extension_branchee(),
            "fenetre_agenda": pc,
            # ses nouveaux pouvoirs : ranger les fichiers, reglages de Windows, initiatives
            "fichiers": pc and bool(cfg.get("jarvis_fichiers")), "windows": pc and bool(cfg.get("jarvis_windows")),
            "initiatives": bool(cfg.get("jarvis_initiatives")),
            # Machi Tool lui-meme : la guirlande, ses routines, les reglages
            "application": True, "routines": _jv.resume_routines(cfg.get("routines_lumiere") or []),
            # ses mises a jour : les annoncer, les lancer (« oui ? » avant) -- si c'est coche
            "mise_a_jour": bool(cfg.get("jarvis_annoncer_maj", True)),
            "souvenirs": souvenirs_a_envoyer(cfg),
            # ses taches de fond, et le contexte de tes projets
            "taches": True, "projets": str(cfg.get("jarvis_projets") or "")[:_jv.PROJETS_MAX],
            "memoire": True, "preferences": [str(p)[:_jv.PREFERENCE_LONGUEUR]
                                             for p in (cfg.get("jarvis_preferences") or [])][-_jv.PREFERENCES_MAX:]}


def continuer_jarvis(etat, resultats, cfg):
    """Renvoie a BrainDebugger ce que les outils ont fait ; Jarvis continue."""
    L = langue_jarvis(cfg)
    conv = etat.get("conv")
    if conv is not None and JARVIS.get("tour") != conv:
        # congedie ou rappele pendant les outils : il ne repasse pas a « pense »
        # par-dessus la nouvelle ecoute (la boule y restait coincee)
        raise Annule()
    poser_led("pense")
    JARVIS.update(etat="pense", message="Jarvis agit...")
    avance = JARVIS["avance"] = {}
    t0 = time.monotonic()
    try:
        donnees = _requete_bd_annulable("/api/machitool/jarvis",
                                        dict({"suite": etat["suite"], "resultats": resultats, "langue": L,
                                              "appellation": str(cfg.get("jarvis_appellation", "") or "")[:40]},
                                             **capacites_jarvis(cfg)), cfg, 180, conv,
                                        sur_debut=lambda t: dire_en_avance(t, L, conv, avance), avance=avance)
    except Interrompu:
        return reponse_interrompue(etat["texte"], avance)
    except Exception as e:
        return echec_bd(e, L, conv, t0=t0)
    return recevoir_jarvis(etat["texte"], donnees, cfg, int(etat.get("tour") or 1) + 1, conv, avance)


def copier_presse_papiers(texte):
    """Le texte dans le presse-papiers de Windows. Rend False hors de Windows
    ou en echec. Par l'API du presse-papiers (CF_UNICODETEXT) : clip.exe,
    lui, gardait la marque d'encodage (\ufeff) en tete du texte -- collee
    devant « MACHITOOL_BULLE_CLE », elle en changeait le nom. clip.exe (en
    UTF-16 avec sa marque, pour les accents) ne sert plus qu'a defaut."""
    if os.name != "nt" or not texte:
        return False
    try:
        import win32clipboard
        win32clipboard.OpenClipboard()
        try:
            win32clipboard.EmptyClipboard()
            win32clipboard.SetClipboardText(texte, win32clipboard.CF_UNICODETEXT)
        finally:
            win32clipboard.CloseClipboard()
        return True
    except Exception:
        pass
    try:
        subprocess.run(["clip"], input=texte.encode("utf-16"), check=True, timeout=5,
                       creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        return True
    except Exception:
        return False


def recevoir_jarvis(texte, donnees, cfg, tour=1, conv=None, avance=None):
    """Ce que BrainDebugger renvoie : une reponse a dire, le compagnon (grave),
    une proposition de passer au psychologue, ou des outils a executer ici.
    `tour` : le tour d'outils ; `conv` : le tour de la conversation (une
    reponse d'un tour d'avant ne se dit pas)."""
    L = langue_jarvis(cfg)
    donnees = donnees or {}
    if conv is not None and JARVIS.get("tour") != conv:
        raise Annule()
    if avance is not None:
        avance["fini"] = True                  # la reponse est la : la premiere phrase n'attend plus
    if donnees.get("agenda_modifie"):
        JARVIS["agenda_change"] = time.time()  # la fenetre Agenda, si elle est ouverte, se relit
        relire_agenda_au_fond(cfg)             # et le panneau, son prochain rendez-vous
    if donnees.get("detail"):
        # CE QUE CLAUDE A REPONDU EN ENTIER, quand Jarvis l'a consulte : il en
        # dit l'essentiel, le texte complet va dans le presse-papiers.
        JARVIS["derniere_reponse_complete"] = str(donnees["detail"])
        if copier_presse_papiers(str(donnees["detail"])):
            notifier = JARVIS_CROCHETS.get("notifier")
            if notifier:
                notifier("Jarvis", "La réponse complète de Claude est dans le presse-papiers.")
    if donnees.get("outils"):
        # executer_outil refuse lui-meme ce que les reglages ne permettent pas
        if tour > OUTILS_TOURS_MAX:
            return signaler_erreur(phrase("sans_reponse", L), conv)
        return outils_de_jarvis({"texte": texte, "suite": donnees.get("suite") or [],
                                 "outils": list(donnees["outils"]), "tour": tour, "conv": conv}, cfg)
    reponse = str(donnees.get("texte") or "").strip()
    if not reponse:
        return signaler_erreur(phrase("sans_reponse", L), conv)
    if donnees.get("fin"):
        # CONGEDIE, POUR DE BON : il dit sa formule, puis n'ecoute plus -- il
        # disait « je m'efface » et restait a l'ecoute.
        print("Jarvis : congedie")
        JARVIS["historique"] = (JARVIS["historique"] + [
            {"role": "user", "texte": texte}, {"role": "assistant", "texte": reponse}])[-HISTORIQUE_JARVIS:]
        verser_au_journal(texte, reponse, cfg)
        clore_historique(cfg)
        JARVIS["attente_code"] = None
        envoyer_oreille({"cmd": "annuler"})
        return dire(reponse, suite=False, langue=L, tour=conv, deja=avance)
    if donnees.get("mode") == "psy":
        # Le compagnon a repondu, et on reste avec lui : un message GRAVE (a
        # l'au revoir, Jarvis se taira : `psy_grave`) -- ou, avec un vieux
        # BrainDebugger, parce que Jarvis a compris qu'on voulait le psychologue.
        grave = donnees.get("raison") != "demande"
        print("Jarvis : bascule en mode psychologue (%s)" % ("grave" if grave else "demande"))
        if grave:
            JARVIS["historique"] = []      # grave : cette conversation-la, on ne la resume pas
        else:
            clore_historique(cfg)
        poser_mode("psy")
        JARVIS.update(psy_grave=grave, psy_raison=donnees.get("raison") or "grave",
                      psy_echange=[{"role": "user", "texte": texte}, {"role": "assistant", "texte": reponse}])
        JARVIS["vu"] = time.time()
        return dire(reponse, suite=True, langue="fr", tour=conv)
    JARVIS["historique"] = (JARVIS["historique"] + [
        {"role": "user", "texte": texte}, {"role": "assistant", "texte": reponse}])[-HISTORIQUE_JARVIS:]
    verser_au_journal(texte, reponse, cfg)
    # « IL EST RENTRE EN MODE PSYCHOLOGUE » : il ne le propose plus en passant.
    # Seule une VRAIE proposition (BrainDebugger la signale ; sinon la question
    # finale) rend un « oui » decisif -- pas « Vous n'etes plus en mode
    # psychologue. Autre chose ? ».
    propose = bool(donnees.get("propose_psy")) if "propose_psy" in donnees else \
        bool(_OFFRE_PSY.search(_jv.sans_accents(reponse).lower().replace("-", " ").replace("’", "'")))
    JARVIS["propose_psy"] = propose
    JARVIS["propose_psy_phrase"] = texte if propose else ""
    JARVIS["vu"] = time.time()
    dire(reponse, suite=True, langue=L, tour=conv, deja=avance)


def parler_a_jarvis(texte, cfg, conv=None, notee=False):
    """Le mode Jarvis : le majordome du PC, par BrainDebugger (qui tient la cle
    Claude) -- Sonnet, effort bas. Chaque echange va au journal une fois dit
    (verser_au_journal, si « jarvis_journal ») ; un message grave, lui, part
    au compagnon (qui le range), et on passe en mode psychologue."""
    L = langue_jarvis(cfg)
    if not _cle_presente(cfg):
        return signaler_erreur(phrase("cle_absente", L), conv)
    poser_led("pense")
    JARVIS.update(etat="pense", message="Jarvis reflechit...")
    print("Jarvis : question au majordome (%d signes)" % len(texte))
    avance = JARVIS["avance"] = {}
    t0 = time.monotonic()
    try:
        donnees = _requete_bd_annulable("/api/machitool/jarvis",
                                        dict({"texte": texte, "historique": JARVIS["historique"][-HISTORIQUE_JARVIS:], "langue": L,
                                              "appellation": str(cfg.get("jarvis_appellation", "") or "")[:40],
                                              "onglets_ouverts": onglets_attendus(cfg),
                                              # Ctrl+Maj+Espace : deja au carnet, il y repond
                                              **({"notee": True} if notee else {})},
                                             **capacites_jarvis(cfg)), cfg, 180, conv,
                                        sur_debut=lambda t: dire_en_avance(t, L, conv, avance), avance=avance)
    except Interrompu:
        return reponse_interrompue(texte, avance)
    except Exception as e:
        return echec_bd(e, L, conv, t0=t0)
    return recevoir_jarvis(texte, donnees, cfg, 1, conv, avance)


def reponse_interrompue(texte, avance):
    """On lui a coupe la parole pendant sa premiere phrase : il n'attend plus
    la suite pour t'ecouter. L'historique garde ce que tu avais demande et ce
    qu'il a eu le temps de dire -- BrainDebugger sait ou vous en etiez."""
    avance["fini"] = True
    print("Jarvis : interrompu pendant sa premiere phrase, il t'ecoute")
    JARVIS["historique"] = (JARVIS["historique"] + [
        {"role": "user", "texte": texte},
        {"role": "assistant", "texte": (str(avance.get("texte") or "") + " [interrompu]").strip()}])[-HISTORIQUE_JARVIS:]
    # au journal aussi : ta question, et ce qu'il a eu le temps de dire
    verser_au_journal(texte, avance.get("texte"), CFG)


_JOURS = ("lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche")
_MOIS = ("janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août",
         "septembre", "octobre", "novembre", "décembre")


_JOURS_EN = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")
_MOIS_EN = ("January", "February", "March", "April", "May", "June", "July", "August", "September",
            "October", "November", "December")


def heure_en(t):
    """« It's 6:30 in the evening. » -- espeak lit « 6:30 » comme on le dit."""
    h, m = t.tm_hour, t.tm_min
    moment = ("in the morning" if 5 <= h < 12 else "in the afternoon" if 12 <= h < 18
              else "in the evening" if 18 <= h < 22 else "at night")
    h12 = h % 12 or 12
    return ("It's %d o'clock %s." % (h12, moment)) if not m else ("It's %d:%02d %s." % (h12, m, moment))


def date_en(t):
    d = t.tm_mday
    suffixe = "th" if 11 <= d % 100 <= 13 else {1: "st", 2: "nd", 3: "rd"}.get(d % 10, "th")
    return "It's %s, the %d%s of %s." % (_JOURS_EN[t.tm_wday], d, suffixe, _MOIS_EN[t.tm_mon - 1])


def executer_commande(a, cfg, maintenant=None):
    """Fait la commande. Rend la phrase a dire, ou None (un son suffit)."""
    quoi = a["action"]
    t = time.localtime(maintenant) if maintenant is not None else time.localtime()
    L = langue_du_mode(cfg)
    if quoi == "verrouiller":
        JARVIS["acces_jusqua"] = 0.0
        JARVIS["attente_code"] = None
        return phrase("verrouille", langue_jarvis(cfg))
    if quoi == "silence":
        VOIX.taire()
        return None
    if quoi in ("volume", "sons"):
        if not cfg.get("jarvis_pc"):
            return phrase("mains_fermees", langue_jarvis(cfg))
        try:
            if quoi == "sons":
                return lister_sons()
            return regler_son(a.get("sens"), a.get("cible") or "", a.get("niveau"))
        except Exception as e:
            return str(e) if isinstance(e, LookupError) else phrase("son_rate", langue_jarvis(cfg))
    if quoi == "youtube":
        if not cfg.get("jarvis_pc"):
            return phrase("mains_fermees", langue_jarvis(cfg))
        try:
            fait = ouvrir_youtube(a.get("recherche"))
        except Exception as e:
            print("Jarvis : YouTube impossible (%s)" % type(e).__name__)
            return phrase("youtube_rate", langue_jarvis(cfg))
        return phrase("youtube_video" if fait.startswith("Video") else "youtube_resultats", langue_jarvis(cfg))
    if quoi in ("annuler", "fin"):
        return None
    if quoi == "dormir":
        cfg["jarvis_actif"] = False
        sauver_config(cfg)
        return phrase("dormir", L)
    if quoi == "heure":
        if L == "en":
            return heure_en(t)
        return "Il est %d heure%s %02d." % (t.tm_hour, "s" if t.tm_hour > 1 else "", t.tm_min) \
            if t.tm_min else "Il est %d heure%s pile." % (t.tm_hour, "s" if t.tm_hour > 1 else "")
    if quoi == "date":
        if L == "en":
            return date_en(t)
        return "Nous sommes le %s %d %s." % (_JOURS[t.tm_wday], t.tm_mday, _MOIS[t.tm_mon - 1])
    if quoi == "mode":
        cfg["mode"] = a["mode"]
        sauver_config(cfg)
        if a["mode"] == "son":
            demarrer_audio(cfg)
        else:
            arreter_audio()
        return None
    if quoi == "lumiere_off":
        ETAT["forcage"] = {"couleur": (0, 0, 0), "nom": "Eteinte (Jarvis)", "manuel": True, "expire": 0}
        return None
    if quoi == "lumiere_couleur":
        ETAT["forcage"] = {"couleur": hex_vers_rgb(a["couleur"]), "nom": "%s (Jarvis)" % a["nom"],
                           "manuel": True, "expire": 0}
        return None
    if quoi in ("lumiere_on", "lumiere_normale"):
        f = ETAT.get("forcage")
        if f and f.get("manuel"):
            ETAT["forcage"] = None
        ETAT["pause"] = False
        return None
    if quoi == "minuteur":
        return poser_minuteur(a["secondes"], a.get("quoi") or "", L)
    if quoi == "minuteurs_annuler":
        # « annule les minuteurs » : les minuteurs -- pas l'alarme de demain matin
        n = annuler_chronos(genre="minuteur")
        return phrase("annule" if n else "aucun_minuteur", L)
    if quoi == "ouvrir_site":
        import webbrowser
        adresse = str(cfg.get("pont_site", "")).strip()
        if adresse:
            webbrowser.open(adresse)
        return None
    if quoi == "ouvrir_panneau":
        f = JARVIS_CROCHETS.get("ouvrir_panneau")
        if f:
            f()
        return None
    if quoi == "synchro":
        if not (ACTIVITE["active"] and cfg.get("collecte_envoi", False)):
            return phrase("synchro_coupee", L)
        threading.Thread(target=lambda: envoyer_activite_au_site(cfg), daemon=True).start()
        return phrase("synchro", L)
    if quoi == "ouvrir":
        cible = a["cible"]
        if os.name == "nt":
            startfile_sur(cible)
        else:
            import webbrowser
            webbrowser.open(cible)
        return None
    return None


# CE QU'IL DIT SANS QU'ON LUI AIT PARLE (un minuteur, un rappel) : jamais par-
# dessus une conversation. Le son et la notification tout de suite ; la
# phrase, des qu'il est libre (voir `dire_les_annonces`, depuis sa veille).
ANNONCES = []
ANNONCE_GARDEE_S = 600
ANNONCE_VOIX_ATTENTE_S = 90   # sa voix pas encore chargee : on l'attend, puis celle de Windows


def annoncer(texte, langue="fr"):
    """« Le minuteur sonne pendant qu'il m'ecoute : il l'enregistre et se
    repond. » Libre, il le dit ; une fenetre d'ecoute d'apres ou personne n'a
    encore parle, il la referme et le dit ; en pleine conversation (il
    t'ecoute, transcrit, reflechit, parle), ca attend qu'il ait fini.
    Rend True s'il le dit maintenant."""
    if not (CFG.get("jarvis_voix", True) and VOIX.peut_parler()):
        return False
    etat = JARVIS.get("etat")
    if (etat == "ecoute" and JARVIS.get("suite_active") and not JARVIS.get("parole_vue")
            and not JARVIS.get("suspens") and not JARVIS.get("attente_code")
            and not JARVIS.get("attente_oui")):
        envoyer_oreille({"cmd": "annuler"})
        poser_led(None)
        JARVIS.update(etat="attente", suite_active=False, ecoute_fin=0.0, message=message_attente())
        etat = "attente"
    if etat in ("attente", "eteint", None):
        montrer_au_panneau(texte)
        VOIX.dire(texte, None, langue)
        return True
    ANNONCES.append((texte, langue, time.time()))
    return False


def dire_les_annonces():
    """Depuis sa veille : ce qui attendait qu'il soit libre."""
    while ANNONCES and JARVIS.get("etat") in ("attente", "eteint", None):
        texte, langue, t = ANNONCES[0][:3]
        avec = ANNONCES[0][3] if len(ANNONCES[0]) > 3 else {}
        if time.time() - t > ANNONCE_GARDEE_S:
            ANNONCES.pop(0)
            continue                          # trop vieux : la notification a suffi
        if CFG.get("jarvis_voix", True):
            if not VOIX.peut_parler():
                return                        # aucune voix encore : ca attend
            cle = "en" if langue == "en" else "fr"
            attendue = any(c.get("cle") == cle for c in charges_voix(CFG))
            if attendue and not voix_prete(cle) and time.time() - t < ANNONCE_VOIX_ATTENTE_S:
                return                        # SA voix se charge encore : ca attend (puis Windows)
        ANNONCES.pop(0)
        if avec.get("programme") is not None:
            # le resume du jour : le panneau montre le programme, pas son visage
            PANNEAU["programme"] = {"debut": time.time(), "rdv": avec["programme"],
                                    "journee": avec.get("journee")}
        if CFG.get("jarvis_voix", True):
            if avec.get("programme") is None:
                montrer_au_panneau(texte)
            VOIX.dire(texte, None, langue)


# LE RESUME DU JOUR. « Lorsque l'ordinateur est demarre et que Machi Tool
# s'ouvre, Jarvis resume la journee si des choses sont prevues » -- « il doit
# detecter un debut d'activite sur le PC (au moins une minute) ». Au lancement,
# le PC vient-il de demarrer (moins de 15 min) ? Alors la premiere minute
# d'activite sans pause declenche le resume : ce qui reste de la journee, dit
# a voix haute, et le programme sur le panneau. Une relance de Machi Tool
# (une mise a jour) ne le refait pas ; deux demarrages rapproches non plus.

RESUME = {"attendu": False, "actif_depuis": None, "lance": False}
RESUME_DEMARRAGE_S = 15 * 60           # Machi Tool lance moins de 15 min apres le PC : un demarrage
RESUME_ACTIVITE_S = 60                 # « au moins une minute d'activite »
RESUME_PAUSE_S = 30                    # sans clavier ni souris depuis 30 s : l'activite repart de zero
RESUME_ECART_S = 3 * 3600              # pas deux resumes en trois heures


def preparer_resume_du_jour(cfg, maintenant=None, demarrage_pc=None):
    """Au lancement de Machi Tool. Rend True si le resume attend ta premiere
    minute d'activite."""
    t = time.time() if maintenant is None else maintenant
    if demarrage_pc is None:
        try:
            import psutil
            demarrage_pc = psutil.boot_time()
        except Exception:
            demarrage_pc = None
    vient_de_demarrer = demarrage_pc is not None and 0 <= t - demarrage_pc < RESUME_DEMARRAGE_S
    RESUME.update(attendu=bool(cfg.get("jarvis_resume_du_jour", True) and vient_de_demarrer
                               and t - float(cfg.get("jarvis_resume_dernier") or 0) > RESUME_ECART_S),
                  actif_depuis=None, lance=False)
    return RESUME["attendu"]


def veiller_resume_du_jour(cfg, maintenant=None, inactivite=None, lancer=None):
    """Depuis sa veille (chaque seconde) : une minute d'activite sans pause
    depuis le demarrage, et le resume part (dans un fil : l'agenda vient de
    BrainDebugger). Rend True quand il part."""
    if not RESUME["attendu"] or RESUME["lance"] or not cfg.get("jarvis_actif"):
        return False
    t = time.time() if maintenant is None else maintenant
    i = secondes_inactivite() if inactivite is None else inactivite
    if i >= RESUME_PAUSE_S:
        RESUME["actif_depuis"] = None
        return False
    if RESUME["actif_depuis"] is None:
        RESUME["actif_depuis"] = t
    if t - RESUME["actif_depuis"] < RESUME_ACTIVITE_S:
        return False
    RESUME["lance"] = True
    cfg["jarvis_resume_dernier"] = t
    try:
        sauver_config(cfg)
    except Exception:
        pass
    if lancer is None:
        threading.Thread(target=sans_faute, args=("Resume du jour", faire_resume_du_jour, cfg),
                         daemon=True).start()
    else:
        lancer(cfg)
    return True


def programme_du_jour(cfg, maintenant=None):
    """Ce qui reste aujourd'hui, depuis BrainDebugger (sa copie locale s'il ne
    repond pas) : (texte du resume ou None, ce qui reste, toute la journee)."""
    t = time.time() if maintenant is None else maintenant
    jour = time.strftime("%Y-%m-%d", time.localtime(t))
    try:
        r, _ = lire_agenda_synchro(cfg, jour, 1)
        journee = _jv.rdv_du_jour(r.get("rendezVous") or [], jour)
        PANNEAU["agenda"] = None
    except Exception:
        d = agenda_local()
        journee = _jv.rdv_du_jour(_appliquer_attente(d["rdv"], d["attente"]), jour)
    lt = time.localtime(t)
    restants = _jv.restants_du_jour(journee, lt.tm_hour * 60 + lt.tm_min)
    texte = _jv.resume_journee(restants, lt.tm_hour * 60 + lt.tm_min, langue_jarvis(cfg),
                               str(cfg.get("jarvis_appellation", "") or "").strip())
    return texte, restants, journee


def faire_resume_du_jour(cfg, maintenant=None):
    """Le resume du demarrage : rien de prevu, il se tait ; sinon il rejoint
    ses annonces -- dit des qu'il est libre et que sa voix est prete --, avec
    le programme pour le panneau. Rend le texte, ou None."""
    texte, restants, journee = programme_du_jour(cfg, maintenant)
    L = langue_jarvis(cfg)
    if not texte:
        print("Jarvis : rien de prevu aujourd'hui, pas de resume")
        return None
    print("Jarvis : resume du jour (%d chose%s)" % (len(restants), "s" if len(restants) > 1 else ""))
    ANNONCES.append((texte, L, time.time(), {"programme": restants, "journee": journee}))
    if not cfg.get("jarvis_voix", True):
        n = JARVIS_CROCHETS.get("notifier")
        if n:
            n("Jarvis", texte)
    return texte


def outil_resume_du_jour(cfg):
    """« Fais en sorte de pouvoir rejouer le resume sur demande. » L'outil de
    Jarvis : le meme resume (il le dit dans sa reponse), et le programme sur le
    panneau pendant qu'il parle."""
    texte, restants, journee = programme_du_jour(cfg)
    if not texte:
        return ("Nothing else planned today." if langue_jarvis(cfg) == "en"
                else "Rien d'autre de prévu aujourd'hui.")
    PANNEAU["programme"] = {"debut": time.time(), "rdv": restants, "journee": journee}
    return texte


def rappel_dans_l_agenda(quoi, fin, cfg):
    """Le rappel « rappelle-moi dans 2 h d'appeler maman », pose aussi dans
    l'agenda : son jour et son heure. Rend True s'il y est."""
    t = time.localtime(fin)
    titre = str(quoi or "").strip()
    titre = titre[:1].upper() + titre[1:]
    try:
        poser_agenda(cfg, titre[:120], time.strftime("%Y-%m-%d", t), heure=time.strftime("%H:%M", t))
    except Exception as e:
        print("Jarvis : rappel pas pose dans l'agenda (%s)" % type(e).__name__)
        return False
    JARVIS["agenda_change"] = time.time()
    return True


# ---------- minuteurs, alarmes, chronometres ----------
# « Fais en sorte que je puisse demander a Jarvis de mettre un minuteur, un
# chronometre ou une alarme qui tourne en fond. » Tous dans JARVIS["minuteurs"]
# (genre : minuteur, alarme, chrono), gardes dans la config : un redemarrage de
# Machi Tool ne les perd plus. Ils se voient dans la fenetre Agenda (« En cours »).

CHRONOS_MAX = 20


class _SansSonnerie:
    """Un chronometre ne sonne pas : rien a annuler."""

    def cancel(self):
        pass


def _nouvel_id():
    pris = {m.get("id") for m in JARVIS["minuteurs"]}
    n = 1
    while n in pris:
        n += 1
    return n


def sauver_chronos(cfg=None):
    cfg = CFG if cfg is None else cfg
    cfg["jarvis_chronos"] = [{k: m[k] for k in ("id", "genre", "fin", "debut", "duree", "quoi") if k in m}
                             for m in JARVIS["minuteurs"]]
    sauver_config(cfg)


def _heure_dite(t, langue="fr"):
    lt = time.localtime(t)
    if langue == "en":
        return time.strftime("%H:%M", lt)
    return "%d h %02d" % (lt.tm_hour, lt.tm_min) if lt.tm_min else "%d h" % lt.tm_hour


def _armer(entree, langue="fr"):
    """La sonnerie d'un minuteur ou d'une alarme, a sa fin."""
    if entree.get("genre") == "chrono":
        entree["minuteur"] = _SansSonnerie()
        return

    def sonner():
        if entree not in JARVIS["minuteurs"]:
            return
        JARVIS["minuteurs"].remove(entree)
        try:
            sauver_chronos()
        except Exception:
            pass
        quoi = entree.get("quoi") or ""
        jouer_son("minuteur")
        poser_led("minuteur", 8 if entree.get("genre") == "alarme" else 5)
        if entree.get("genre") == "alarme":
            heure = _heure_dite(entree["fin"], langue)
            texte = (phrase("alarme_nommee_sonne", langue, heure, quoi) if quoi
                     else phrase("alarme_sonne", langue, heure))
        elif entree.get("rappel"):
            texte = phrase("rappel", langue, quoi)
        elif quoi:
            texte = phrase("minuteur_nomme_fini", langue, quoi)
        else:
            texte = phrase("minuteur_fini", langue, _jv.dire_duree(entree["duree"], langue))
        notifier = JARVIS_CROCHETS.get("notifier")
        if notifier:
            notifier("Jarvis", texte)
        annoncer(texte, langue)

    entree["minuteur"] = threading.Timer(max(0.0, entree["fin"] - time.time()), sonner)
    entree["minuteur"].daemon = True
    entree["minuteur"].start()


def _ajouter(entree, langue="fr"):
    if len(JARVIS["minuteurs"]) >= CHRONOS_MAX:
        raise ValueError("Deja %d minuteurs, alarmes et chronometres en cours : annules-en un d'abord."
                         % CHRONOS_MAX)
    entree.setdefault("id", _nouvel_id())
    _armer(entree, langue)
    JARVIS["minuteurs"].append(entree)
    sauver_chronos()
    return entree


def poser_minuteur(secondes, quoi="", langue="fr", rappel=None):
    """Un minuteur de `secondes`. Une phrase de rappel (« rappelle-moi dans 2 h
    d'appeler maman ») va aussi dans l'agenda ; `rappel=False` : un minuteur
    nomme (« les pates »), qui n'encombre pas l'agenda."""
    secondes = max(1.0, min(24 * 3600.0, float(secondes)))
    rappel = bool(quoi) if rappel is None else bool(rappel and quoi)
    entree = _ajouter({"genre": "minuteur", "fin": time.time() + secondes, "quoi": quoi, "duree": secondes,
                       "rappel": rappel}, langue)
    if rappel and _cle_presente(CFG):
        # « Assure-toi que rajouter un rappel rajoute un element a l'agenda
        # aussi » : il sonne ici, ET il est dans l'agenda de BrainDebugger
        # (la fenetre Agenda, la frise) -- meme apres un redemarrage.
        _en_fond(lambda: rappel_dans_l_agenda(quoi, entree["fin"], CFG))
    if rappel:
        return phrase("rappel_pose", langue, _jv.dire_duree(secondes, langue))
    return phrase("minuteur", langue, _jv.dire_duree(secondes, langue))


def fin_d_alarme(heure, jour=None, maintenant=None):
    """L'instant d'une alarme a HH:MM : aujourd'hui si c'est encore a venir,
    sinon demain -- ou le `jour` donne (AAAA-MM-JJ)."""
    m = re.match(r"^\s*(\d{1,2})\s*(?:[:hH]\s*(\d{2})?)?\s*$", str(heure or ""))
    if not m or int(m.group(1)) > 23 or int(m.group(2) or 0) > 59:
        raise ValueError("Heure illisible : %s (HH:MM)" % heure)
    h, mn = int(m.group(1)), int(m.group(2) or 0)
    t = time.time() if maintenant is None else maintenant
    base = time.localtime(t)
    if jour:
        try:
            a, mo, j = (int(x) for x in str(jour).split("-"))
        except Exception:
            raise ValueError("Jour illisible : %s (AAAA-MM-JJ)" % jour)
        fin = time.mktime((a, mo, j, h, mn, 0, 0, 0, -1))
        if fin <= t:
            raise ValueError("Cette heure-la est deja passee.")
        return fin
    fin = time.mktime((base.tm_year, base.tm_mon, base.tm_mday, h, mn, 0, 0, 0, -1))
    if fin <= t:
        fin = time.mktime((base.tm_year, base.tm_mon, base.tm_mday + 1, h, mn, 0, 0, 0, -1))
    return fin


def poser_alarme(heure, jour=None, quoi="", langue="fr"):
    fin = fin_d_alarme(heure, jour)
    _ajouter({"genre": "alarme", "fin": fin, "quoi": quoi, "duree": fin - time.time()}, langue)
    quand = _heure_dite(fin, langue)
    if time.strftime("%Y-%m-%d", time.localtime(fin)) != time.strftime("%Y-%m-%d"):
        demain = time.strftime("%Y-%m-%d", time.localtime(time.time() + 86400))
        jour_fin = time.strftime("%Y-%m-%d", time.localtime(fin))
        quand = ("demain " if langue != "en" else "tomorrow ") + quand if jour_fin == demain else \
            "%s %s" % (_jv.jour_court(jour_fin), quand)
    return phrase("alarme", langue, quand)


def lancer_chrono(quoi="", langue="fr"):
    _ajouter({"genre": "chrono", "debut": time.time(), "quoi": quoi}, langue)
    return phrase("chrono", langue)


def temps_ecoule(secondes):
    """« 1:02:05 », « 12:30 » : pour l'ecran."""
    s = int(max(0, secondes))
    h, reste = divmod(s, 3600)
    return "%d:%02d:%02d" % (h, reste // 60, reste % 60) if h else "%02d:%02d" % (reste // 60, reste % 60)


def _choisir(designation=None, genre=None):
    """Ceux que designe un numero, un nom (« les pates »), ou un genre."""
    tous = [m for m in JARVIS["minuteurs"] if genre is None or m.get("genre") == genre]
    d = str(designation if designation is not None else "").strip().lower()
    if not d:
        return tous
    if d.isdigit():
        return [m for m in tous if m.get("id") == int(d)]
    return [m for m in tous if d in str(m.get("quoi") or "").lower()]


def arreter_chrono(designation=None, langue="fr"):
    chronos = _choisir(designation, "chrono")
    if not chronos:
        raise LookupError("Aucun chronometre en cours%s." % (" pour « %s »" % designation if designation else ""))
    c = chronos[-1]
    JARVIS["minuteurs"].remove(c)
    sauver_chronos()
    return phrase("chrono_arrete", langue, _jv.dire_duree(time.time() - c["debut"], langue))


def annuler_chronos(designation=None, genre=None, langue="fr"):
    choisis = _choisir(designation, genre)
    for m in choisis:
        m["minuteur"].cancel()
        JARVIS["minuteurs"].remove(m)
    if choisis:
        sauver_chronos()
    return len(choisis)


def decrire_chronos(maintenant=None, langue="fr"):
    """Ce qui tourne, une ligne chacun : pour Jarvis, et pour l'ecran."""
    t = time.time() if maintenant is None else maintenant
    lignes = []
    for m in sorted(JARVIS["minuteurs"], key=lambda m: m.get("fin") or 9e12):
        nom = (" « %s »" % m["quoi"]) if m.get("quoi") else ""
        if m.get("genre") == "chrono":
            lignes.append("#%d chronometre%s : %s ecoulees" % (m["id"], nom, temps_ecoule(t - m["debut"])))
        elif m.get("genre") == "alarme":
            lignes.append("#%d alarme%s : %s (dans %s)" % (m["id"], nom, time.strftime("%d/%m %H:%M",
                          time.localtime(m["fin"])), _jv.dire_duree(m["fin"] - t, langue)))
        else:
            lignes.append("#%d minuteur%s : reste %s" % (m["id"], nom, temps_ecoule(m["fin"] - t)))
    return lignes


def outil_minuteurs(e, cfg, langue="fr"):
    """L'outil « minuteurs » de Jarvis. Rend le texte du resultat."""
    a = e.get("action")
    quoi = str(e.get("nom") or "").strip()[:80]
    if a == "minuteur":
        secondes = e.get("secondes")
        if not isinstance(secondes, (int, float)) or secondes <= 0:
            raise ValueError("Il faut une duree en secondes.")
        poser_minuteur(secondes, quoi, langue, rappel=False)
        return "Minuteur%s lance : %s." % (" « %s »" % quoi if quoi else "", _jv.dire_duree(secondes, langue))
    if a == "alarme":
        return poser_alarme(e.get("heure"), e.get("jour") or None, quoi, langue)
    if a == "chrono_lancer":
        return lancer_chrono(quoi, langue)
    if a == "chrono_arreter":
        return arreter_chrono(e.get("id") or quoi or None, langue)
    if a == "annuler":
        n = annuler_chronos(None if e.get("tout") else (e.get("id") or quoi or None),
                            e.get("genre") if e.get("genre") in ("minuteur", "alarme", "chrono") else None, langue)
        if not n:
            raise LookupError("Rien de tel en cours.")
        return "Annule : %d." % n
    if a == "lister":
        return "\n".join(decrire_chronos(langue=langue)) or "Rien en cours."
    raise ValueError("Action inconnue : %s" % a)


def restaurer_chronos(cfg=None):
    """Au demarrage : ce qui tournait avant reprend ; ce qui a sonne pendant que
    Machi Tool etait ferme se dit en notification (sans voix : c'est passe)."""
    cfg = CFG if cfg is None else cfg
    t = time.time()
    rates = []
    for m in cfg.get("jarvis_chronos") or []:
        if not isinstance(m, dict) or m.get("genre") not in ("minuteur", "alarme", "chrono"):
            continue
        if any(x.get("id") == m.get("id") for x in JARVIS["minuteurs"]):
            continue
        if m["genre"] != "chrono" and float(m.get("fin") or 0) <= t:
            rates.append(m)
            continue
        entree = dict(m)
        _armer(entree)
        JARVIS["minuteurs"].append(entree)
    sauver_chronos(cfg)
    notifier = JARVIS_CROCHETS.get("notifier")
    for m in rates:
        texte = "Pendant que Machi Tool etait ferme : %s %s a sonne a %s." % (
            "l'alarme" if m["genre"] == "alarme" else "le minuteur",
            ("« %s »" % m["quoi"]) if m.get("quoi") else "", time.strftime("%H:%M", time.localtime(m["fin"])))
        print("Jarvis : " + texte)
        if notifier:
            notifier("Jarvis", texte)
    return len(rates)


# ---------- le panneau LED (Machi LED Wall) ----------
# « Tu peux faire passer ca dans Machi Tool automatiquement ? » Un panneau
# 64 x 64 sur une MatrixPortal S3 branchee en USB, avec le croquis du guide
# (machi_panneau.ino) : "MF" + 8 192 octets (RGB565, poids fort d'abord) est
# une image, "MB" + 1 octet la luminosite. Machi Tool trouve la carte seul et
# lui envoie 30 images par seconde (« possible que machitool envoie du 30
# fps ? ») -- 8 Ko a 30 i/s, 250 Ko/s : l'USB de l'ESP32-S3 suit sans peine.
# Rien de personnel n'y passe : l'heure, la date, la couleur de la guirlande,
# un minuteur -- sans son nom. Seule exception, qu'on peut decocher : le
# panneau de Jarvis, et ce qu'il dit.

