def _ecran_selon(reglages):
    return lambda e, t, ecoule, dt: _ecran_boreal(reglages, e, t, ecoule, dt)


def _scene_selon(moteur, humeur):
    p = {"humeur": humeur}
    return lambda e, t, ecoule, dt: moteur(p, e, t, ecoule, dt)


# Sur la page, par familles : une case par decor serait illisible.
FAMILLES_ECRANS = []
for _famille, _texte, _scenes in DECORS:
    _noms = []
    for _scene, _moteur, _humeurs in _scenes:
        for _humeur, _titre in _humeurs:
            _cle = _scene if _humeur is None else _scene + "_" + _humeur       # une seule ambiance : le nom de la scene
            ECRANS[_cle] = (_titre, _scene_selon(_moteur, _humeur))
            _noms.append(_cle)
    FAMILLES_ECRANS.append((_famille, "%s (%d)" % (_texte, len(_noms)), tuple(_noms)))
for _cle, _titre, _reglages in _presets_boreaux():
    ECRANS[_cle] = (_titre, _ecran_selon(_reglages))
ECRANS_AURORES = tuple(cle for cle, _, _ in _presets_boreaux())
FAMILLES_ECRANS.append(("boreales", "Les aurores boreales : montagnes, lac, fjord, mer, banquise, foret, cabane, phare, "
                                    "village, igloo, volcan, sommet, ciel (16)",
                        tuple(c for c in ECRANS_AURORES if c.startswith("boreale_"))))
ECRANS["vortex"] = ("Vortex de lumiere", _scene_selon(_scene_vortex, None))
FAMILLES_ECRANS.append(("tunnels", "Les tunnels de lumiere : rond, carre, en spirale, d'anneaux, vermoulu, vortex (6)",
                        tuple(c for c in ECRANS_AURORES if c.startswith("tunnel_")) + ("vortex",)))
FAMILLES_ECRANS = tuple(FAMILLES_ECRANS)
ECRANS_DECORS = tuple(n for _, _, noms in FAMILLES_ECRANS for n in noms)


def reglages_ecrans(cfg):
    """(secondes entre deux ecrans, duree d'un ecran), lues dans la config et bornees."""
    def lire(cle, defaut, bornes):
        try:
            v = float(cfg.get(cle, defaut))
        except (TypeError, ValueError):
            v = defaut
        return max(bornes[0], min(bornes[1], v))
    return (lire("panneau_ecrans_intervalle", 5, ECRAN_INTERVALLE_BORNES) * 60,
            lire("panneau_ecrans_duree", 15, ECRAN_DUREE_BORNES))


def ecrans_permis(cfg):
    """Les ecrans coches sur la page (panneau_ecrans_sans : ceux qu'on a decoches)."""
    sans = set(cfg.get("panneau_ecrans_sans") or [])
    return [n for n in ECRANS if n not in sans]


def prochain_ecran(rng=None, permis=None):
    """Le suivant dans le sac : chacun son tour, dans un ordre melange, parmi
    `permis` (tous par defaut) ; None si aucun n'est permis."""
    import random
    permis = list(ECRANS) if permis is None else [n for n in permis if n in ECRANS]
    if not permis:
        return None
    sac = [n for n in PANNEAU.get("ecrans_sac") or [] if n in permis]
    if not sac:
        sac = list(permis)
        (rng or random).shuffle(sac)
        if len(sac) > 1 and sac[0] == PANNEAU.get("ecran_dernier"):
            sac.append(sac.pop(0))                     # jamais deux fois le meme de suite
    PANNEAU["ecrans_sac"] = sac[1:]
    PANNEAU["ecran_dernier"] = sac[0]
    return sac[0]


def demander_ecran(nom=None):
    """« Montrer un ecran » (la page Panneau LED) : le suivant, ou celui-la, tout de suite."""
    PANNEAU["ecran_demande"] = nom if nom in ECRANS else True


def ecran_du_moment(cfg, t, urgent=None):
    """L'ecran qui prend le panneau a l'instant t ({nom, debut, etat}), ou None.
    Il commence quand l'intervalle est passe et que le cycle change de vue
    (ou quand on le demande) ; `urgent` (un minuteur, un rendez-vous) le retient."""
    import numpy as np
    intervalle, duree = reglages_ecrans(cfg)
    e = PANNEAU.get("ecran")
    if e is not None:
        if 0 <= t - e["debut"] < duree:
            return e
        PANNEAU["ecran"] = None
        PANNEAU["ecran_fin"] = t
    fin = PANNEAU.setdefault("ecran_fin", t)
    if not 0 <= t - fin <= intervalle + 3600:          # l'horloge a recule, ou bondi (une veille) : on repart d'ici
        fin = PANNEAU["ecran_fin"] = t
    demande = PANNEAU.pop("ecran_demande", None)
    if not demande:
        if not cfg.get("panneau_ecrans", True) or t - fin < intervalle:
            return None
        cycle = PANNEAU.get("cycle") if cfg.get("panneau_cycle", True) else None
        if cycle and not 0 <= t - float(cycle.get("depuis") or 0) < 1.0 and t - fin - intervalle < 35:
            return None                                 # on attend que le cycle change de vue (35 s au plus)
        if (urgent() if callable(urgent) else urgent):
            return None
    nom = demande if demande in ECRANS else prochain_ecran(permis=ecrans_permis(cfg))
    if nom is None:
        return None                                     # tous decoches
    e = PANNEAU["ecran"] = {"nom": nom, "debut": t, "t": t,
                            "etat": {"rng": np.random.default_rng(int(t * 1000) % (2 ** 32))}}
    return e


def image_de_l_ecran(e, t, duree, dessous=None):
    """L'image de l'ecran `e` a l'instant t ; en fondu sur `dessous` (une
    fonction qui rend l'image d'en dessous) a l'entree et a la sortie."""
    import numpy as np
    ecoule = t - e["debut"]
    dt = min(0.2, max(0.0, t - e["t"]))
    e["t"] = t
    img = ECRANS[e["nom"]][1](e["etat"], t, ecoule, dt)
    k = min(1.0, ecoule / ECRAN_FONDU_S, (duree - ecoule) / ECRAN_FONDU_S)
    if k < 1.0 and dessous is not None:
        k = max(0.0, k)
        img = np.clip(np.round(img * k + dessous() * (1 - k)), 0, 255).astype(np.uint8)
    return img


# LE MIROIR DE L'ECRAN. « Add a screen replication mode, especially when
# playing : the board can replicate the colors of the game. » Pendant un jeu
# (ou toujours, ou aussi pour une video en plein ecran : panneau_miroir), le
# panneau recopie l'ecran ou il se joue, etire sur tout le panneau (« stretch
# l'ecran sur tout le panneau plutot que de le fit ») -- ou tout en couleurs
# floues (panneau_miroir_style). Un fil a lui capture, GDI reduisant l'image
# lui-meme : le fil du panneau ne fait que la poser.
# Un jeu : son .exe dans un dossier de jeux (Steam, Epic, Riot, GOG...), ou
# une appli en plein ecran qui n'est ni un navigateur ni un lecteur video.
# Trois secondes ailleurs (un Alt+Tab) ne l'arretent pas. Un jeu en plein
# ecran EXCLUSIF peut se derober a la capture : le mode fenetre sans bordure
# (le reglage par defaut de la plupart des jeux) se recopie.
#
# LE JEU D'ABORD. « Make sure my game is not stuttering, you don't have to
# replicate every frame every time, it can be a blend of colors. » Lire
# l'ecran fait attendre le compositeur de Windows le temps de la copie : 30
# captures par seconde, c'etait 30 occasions par seconde de retarder une
# image du jeu. Le miroir capture donc peu -- 8 fois par seconde au plus,
# et jamais plus de 3 % du temps (une capture qui coute 20 ms : une toutes
# les 0,67 s) --, depuis un fil de basse priorite, et le panneau FOND d'une
# capture a l'autre a sa cadence : les couleurs glissent au lieu de sauter.
MIROIR_MODES = ("jeux", "plein_ecran", "toujours", "jamais")
MIROIR_CAPTURES_S = 8                   # au plus 8 captures par seconde...
MIROIR_PART = 0.03                      # ...et jamais plus de 3 % du temps a capturer
MIROIR_PAUSE_MAX_S = 1.0                # une capture par seconde au moins, quoi qu'elle coute
MIROIR_GRACE_S = 3.0
MIROIR_FRAIS_S = 2.5                    # une capture plus vieille : le miroir s'efface
MIROIR_FONDU_S = {"couleurs": 0.45, "image": 0.15}   # le temps que le panneau met a rejoindre une capture
JEUX_DOSSIERS = ("\\steamapps\\common\\", "\\epic games\\", "\\riot games\\", "\\gog galaxy\\games\\",
                 "\\gog games\\", "\\ubisoft game launcher\\games\\", "\\ea games\\", "\\origin games\\",
                 "\\xboxgames\\", "\\itch\\apps\\", "\\games\\", "\\jeux\\")
# Des noms d'exe entiers (sans .exe ni chiffres de fin : obs64 est obs) --
# pas des morceaux : « edge » ne doit pas ecarter Mirror's Edge.
PAS_DES_JEUX = NAVIGATEURS + (
    # les lecteurs (le mode plein_ecran les recopie, le mode jeux non)
    "vlc", "mpc-hc", "mpc-be", "potplayer", "potplayermini", "wmplayer", "mpv", "kmplayer", "smplayer", "plex",
    "video.ui", "microsoft.media.player", "photos", "microsoft.photos",
    # les lanceurs : dans les dossiers de jeux, mais pas des jeux
    "steam", "steamwebhelper", "epicgameslauncher", "riotclientux", "riotclientservices", "galaxyclient", "upc",
    "ubisoftconnect", "eadesktop", "origin", "battle.net",
    # Windows, Machi Tool, et ce qu'on met en plein ecran sans jouer
    "explorer", "applicationframehost", "lockapp", "logonui", "searchhost", "searchapp", "startmenuexperiencehost",
    "shellexperiencehost", "machitool", "obs", "discord", "spotify", "code", "powerpnt", "zoom", "teams", "ms-teams",
    "slack")


def chemin_du_processus(pid):
    """Le chemin complet de l'exe d'un PID, ou "" -- par psutil, sinon par
    QueryFullProcessImageName (un jeu protege refuse souvent le premier)."""
    try:
        import psutil
        return psutil.Process(pid).exe() or ""
    except Exception:
        pass
    try:
        import ctypes
        from ctypes import wintypes
        k = ctypes.WinDLL("kernel32", use_last_error=True)
        k.OpenProcess.restype = wintypes.HANDLE
        k.OpenProcess.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]
        h = k.OpenProcess(0x1000, False, int(pid))      # PROCESS_QUERY_LIMITED_INFORMATION
        if not h:
            return ""
        try:
            buf = ctypes.create_unicode_buffer(32768)
            n = wintypes.DWORD(len(buf))
            k.QueryFullProcessImageNameW.argtypes = [wintypes.HANDLE, wintypes.DWORD, wintypes.LPWSTR,
                                                     ctypes.POINTER(wintypes.DWORD)]
            return buf.value if k.QueryFullProcessImageNameW(h, 0, buf, ctypes.byref(n)) else ""
        finally:
            k.CloseHandle(h)
    except Exception:
        return ""


def premier_plan():
    """(processus, chemin de son exe, plein ecran ?) de la fenetre au premier
    plan, en minuscules ; None hors de Windows ou sans fenetre."""
    if os.name != "nt":
        return None
    try:
        import ctypes
        import win32api
        import win32gui
        import win32process
        h = win32gui.GetForegroundWindow()
        if not h or win32gui.GetClassName(h) in ("Progman", "WorkerW", "Shell_TrayWnd"):
            return None
        _, pid = win32process.GetWindowThreadProcessId(h)
        chemin = chemin_du_processus(pid).lower()
        nom = os.path.basename(chemin) or str(_nom_du_processus(pid) or "").lower()
        g, ht, d, b = win32gui.GetWindowRect(h)
        m = win32api.GetMonitorInfo(win32api.MonitorFromWindow(h, 2))["Monitor"]     # le plus proche
        # agrandie, une fenetre deborde de l'ecran de ses bordures : pas du plein ecran
        plein = g <= m[0] and ht <= m[1] and d >= m[2] and b >= m[3] and not ctypes.windll.user32.IsZoomed(h)
        return nom, chemin, bool(plein)
    except Exception:
        return None


def est_un_jeu(processus, chemin, plein_ecran):
    """Un jeu : son exe dans un dossier de jeux, ou une appli en plein ecran
    qui n'est ni un navigateur, ni un lecteur video, ni Machi Tool. Un
    processus qui ne se laisse pas lire (un anti-triche) : en plein ecran, un jeu."""
    nom = str(processus or "").strip().lower()
    nom = nom[:-4] if nom.endswith(".exe") else nom
    if nom in PAS_DES_JEUX or nom.rstrip("0123456789") in PAS_DES_JEUX:
        return False
    if not nom:
        return bool(plein_ecran)
    chemin = str(chemin or "").lower().replace("/", "\\")
    return any(d in chemin for d in JEUX_DOSSIERS) or bool(plein_ecran)


def suivre_jeu(t, info=None):
    """Depuis le fil des sources : un jeu au premier plan ? une fenetre en
    plein ecran ? (PANNEAU["jeu_vu"], ["plein_ecran_vu"]). `info` : pour les tests."""
    info = premier_plan() if info is None else info
    if not info:
        return False
    processus, chemin, plein = info
    if plein:
        PANNEAU["plein_ecran_vu"] = t
    if est_un_jeu(processus, chemin, plein):
        PANNEAU.update(jeu_vu=t, jeu=processus)
        return True
    return False


def miroir_voulu(cfg, t):
    """Le panneau doit-il recopier l'ecran a l'instant t ? (panneau_miroir)"""
    mode = cfg.get("panneau_miroir", "jeux")
    if mode == "toujours":
        return True
    recent = lambda cle: 0 <= t - float(PANNEAU.get(cle) or 0) <= MIROIR_GRACE_S
    if mode == "jeux":
        return recent("jeu_vu")
    if mode == "plein_ecran":
        return recent("jeu_vu") or recent("plein_ecran_vu")
    return False


def capturer_miroir():
    """L'ecran de la fenetre au premier plan, reduit a 64 x 64 -- etire, quelle
    que soit sa proportion : chaque pixel du panneau, la moyenne de sa part
    d'ecran (un 16/9 : 60 x 34 pixels de 4K chacun) --, en RGB ; GDI le reduit
    lui-meme, sinon mss et une moyenne par blocs. None si rien ne se capture."""
    import numpy as np
    sct = _capteur()
    zone = zone_reelle()                                # l'ecran du jeu, dans sa definition du moment
    if zone is None:
        zone = sct.monitors[max(1, min(_ecran_actif(sct), len(sct.monitors) - 1))]
    lignes = 64
    octets = _vignette_gdi(zone, 64, lignes, brut=True)
    if octets and len(octets) >= 64 * lignes * 4:
        return np.frombuffer(octets, np.uint8)[:64 * lignes * 4].reshape(lignes, 64, 4)[..., 2::-1].copy()
    from PIL import Image
    brut = sct.grab(zone)
    return np.asarray(Image.frombytes("RGB", brut.size, brut.rgb).resize((64, lignes), Image.BOX))


def pause_miroir(cout):
    """Le temps entre deux captures, d'apres ce qu'une capture coute (en s) :
    1/8 s au mieux, et assez pour que capturer ne prenne jamais plus de 3 %
    du temps -- mais une par seconde au moins."""
    return max(1.0 / MIROIR_CAPTURES_S, min(MIROIR_PAUSE_MAX_S, float(cout) / MIROIR_PART))


def fil_miroir(cfg=None, tours=None):
    """Le fil du miroir : tant que le panneau recopie l'ecran (branche, et
    miroir_voulu), une capture dans PANNEAU["miroir"] -- a la cadence que son
    cout permet (pause_miroir), le cout lisse sur les dernieres : une capture
    qui traine (le jeu charge le PC) espace les suivantes."""
    cfg = CFG if cfg is None else cfg
    priorite_du_fil(-2)                                 # THREAD_PRIORITY_LOWEST : le jeu passe devant
    n, cout = 0, None
    while ETAT["en_marche"] and (tours is None or n < tours):
        n += 1
        t = time.time()
        if not (cfg.get("panneau_actif", True) and PANNEAU.get("etat") == "connecte" and miroir_voulu(cfg, t)
                and cfg.get("panneau_contenu", "horloge") != "eteint"):
            if tours is None:
                time.sleep(0.25)
            continue
        debut = time.monotonic()
        try:
            petite = capturer_miroir()
        except Exception as e:
            signaler_capture("Miroir du panneau", e)
            petite = None
        duree = time.monotonic() - debut
        cout = duree if cout is None else 0.7 * cout + 0.3 * duree
        pause = pause_miroir(cout)
        PANNEAU.update(miroir_cout_ms=cout * 1000.0, miroir_pause_s=pause)
        if petite is not None:
            try:
                petite = corriger_miroir(petite, cfg)   # f.lux, et la balance du miroir
            except Exception as e:
                signaler_capture("Couleurs du miroir", e)
            PANNEAU["miroir"] = {"img": petite, "t": time.time()}
        if tours is None:
            time.sleep(max(0.0, pause - duree))


def _flou(img, passes):
    """Un flou doux (moyenne avec les quatre voisins, les bords prolonges)."""
    import numpy as np
    f = np.asarray(img, float)
    for _ in range(passes):
        p = np.pad(f, ((1, 1), (1, 1), (0, 0)), mode="edge")
        f = (p[1:-1, 1:-1] + p[:-2, 1:-1] + p[2:, 1:-1] + p[1:-1, :-2] + p[1:-1, 2:]) / 5
    return f


def image_miroir(petite, style="image"):
    """Le panneau a partir de la capture reduite : l'image etiree sur tout le
    panneau ; ou, en style « couleurs », tout en couleurs floues et un peu
    plus vives. Une capture de moins de 64 lignes s'etire en hauteur."""
    import numpy as np
    h = petite.shape[0]
    etiree = np.asarray(petite, float)[np.clip((np.arange(64) * h / 64).astype(int), 0, h - 1)]
    if style == "couleurs":
        f = _flou(etiree, 10)
        gris = f.mean(axis=2, keepdims=True)
        return np.clip(gris + (f - gris) * 1.4, 0, 255).astype(np.uint8)
    return np.clip(etiree, 0, 255).astype(np.uint8)


def corriger_miroir(petite, cfg):
    """La capture telle que l'OEIL la voit a l'ecran, puis reglee pour le panneau.

    « Make sure the video game panel view has the right flux color correction
    (and add a specific panel color correction too). » La capture lit l'image
    AVANT la rampe gamma, la ou f.lux (Redshift, SunsetScreen...) la jaunit :
    le soir, le jeu est ambre a l'ecran et bleu sur le panneau. Quand la rampe
    se lit, on lui fait subir la rampe elle-meme, pixel par pixel -- ce que
    l'ecran affiche, au plus juste ; sinon, ce que f.lux doit tenir d'apres
    ses reglages et l'heure (des kelvins). `panneau_miroir_filtre_force`
    l'attenue ou l'exagere. Puis la balance du miroir, a lui seul (la
    guirlande garde la sienne) : chaud/froid, vert/magenta. Windows Night
    Light ne se lit pas : la balance le rattrape a la main. Rien a corriger :
    la capture telle quelle."""
    import numpy as np
    img = None
    force = max(0.0, float(cfg.get("panneau_miroir_filtre_force", 1.0) or 0.0))
    if cfg.get("panneau_miroir_filtre", True) and force > 0:
        lut = rampe_gamma()
        if lut and lut[2][255] / max(1, lut[0][255]) < 0.97:      # le bleu est abaisse : un filtre agit
            tables = np.asarray(lut, float)
            brut = np.asarray(petite, np.uint8)
            vue = np.stack([tables[c][brut[..., c]] for c in range(3)], -1)
            img = brut + (vue - brut) * force
        else:
            k = kelvin_attendu_flux()
            if k:
                img = np.asarray(petite, float) * np.asarray(gains_kelvin(k, 6500.0, force))
    temp = float(cfg.get("panneau_miroir_temp", 0.0) or 0.0)
    teinte = float(cfg.get("panneau_miroir_teinte", 0.0) or 0.0)
    if temp or teinte:
        # comme la balance de la guirlande : au plus +-30 %
        gains = (1.0 + 0.30 * temp + 0.15 * teinte, 1.0 - 0.15 * teinte, 1.0 - 0.30 * temp + 0.15 * teinte)
        img = (np.asarray(petite, float) if img is None else img) * np.asarray(gains)
    if img is None:
        return petite
    return np.clip(np.round(img), 0, 255).astype(np.uint8)


def etat_filtre_miroir(cfg):
    """Une ligne pour la page : ce que le miroir suit du filtre de lumiere bleue."""
    if not cfg.get("panneau_miroir_filtre", True):
        return "Le miroir ne suit pas le filtre de lumiere bleue."
    d = diag_filtre_ecran(cfg)
    if d.get("source") == "filtre":
        return "Filtre lu dans la rampe de l'ecran (~%s K) : le miroir le suit au pixel pres." % d.get("kelvin")
    if d.get("source") == "flux":
        return "f.lux tourne, rampe illisible : ~%s K d'apres ses reglages et l'heure." % d.get("kelvin")
    if d.get("nightlight"):
        return "Windows Night Light ne se lit pas : rechauffe le miroir a la main (chaud/froid)."
    return "Pas de filtre de lumiere bleue en ce moment : les couleurs du jeu, telles quelles."


def miroir_du_moment(cfg, t):
    """La derniere capture, si le miroir est voulu et qu'elle est fraiche ; sinon None."""
    m = PANNEAU.get("miroir")
    if m is None or not miroir_voulu(cfg, t) or not -0.2 <= t - m["t"] <= MIROIR_FRAIS_S:
        return None
    return m


def image_miroir_fondue(m, t, style):
    """Le panneau a l'instant t : la capture `m` mise en forme (une fois par
    capture), et le panneau qui la rejoint en douceur, a sa cadence a lui --
    entre deux captures espacees, les couleurs glissent au lieu de sauter."""
    import numpy as np
    rendu = PANNEAU.get("miroir_rendu")
    if rendu is None or rendu[0] is not m or rendu[1] != style:      # chaque capture est un dict neuf
        rendu = PANNEAU["miroir_rendu"] = (m, style, image_miroir(m["img"], style).astype(float))
    cible = rendu[2]
    f = PANNEAU.get("miroir_fondu")
    if f is None or f["img"].shape != cible.shape or not 0 <= t - f["t"] <= 1.0:
        lisse = cible                                   # il revient (ou le temps a saute) : d'emblee
    else:
        k = 1.0 - math.exp(-(t - f["t"]) / MIROIR_FONDU_S.get(style, 0.3))
        lisse = f["img"] + (cible - f["img"]) * k
    PANNEAU["miroir_fondu"] = {"img": lisse, "t": t}
    return np.clip(np.round(lisse), 0, 255).astype(np.uint8)


def etat_miroir_lisible(cfg, maintenant=None):
    """Une ligne pour la page : ce que fait le miroir en ce moment."""
    t = time.time() if maintenant is None else maintenant
    mode = cfg.get("panneau_miroir", "jeux")
    if mode == "jamais":
        return "Le miroir est coupe."
    if miroir_du_moment(cfg, t) is not None:
        jeu = PANNEAU.get("jeu") if 0 <= t - float(PANNEAU.get("jeu_vu") or 0) <= MIROIR_GRACE_S else None
        rythme = ""
        if PANNEAU.get("miroir_pause_s"):
            rythme = " -- %.1f captures par seconde, %.0f ms chacune" % (
                1.0 / PANNEAU["miroir_pause_s"], float(PANNEAU.get("miroir_cout_ms") or 0))
        return "Le panneau recopie l'ecran%s%s." % (" (%s)" % jeu if jeu else "", rythme)
    return {"jeux": "Pas de jeu au premier plan : le panneau garde son contenu.",
            "plein_ecran": "Ni jeu, ni plein ecran : le panneau garde son contenu.",
            "toujours": "Pas encore de capture (le panneau doit etre branche)."}.get(mode, "")


def _ecran_retenu(cfg, t):
    """Un minuteur qui va sonner, un rendez-vous qui arrive : pas d'ecran, l'heure reste."""
    try:
        rdv = agenda_du_jour(cfg, maintenant=t) if cfg.get("panneau_rdv", True) else []
    except Exception:
        rdv = []
    return cycle_urgent(JARVIS.get("minuteurs"), rdv, t)


def _image_du_contenu(cfg, contenu, t, eclat):
    """Le contenu choisi (l'horloge, son cycle, l'agenda du jour), sans ce qui
    passe par-dessus."""
    rdv = []
    if contenu == "horloge" and cfg.get("panneau_rdv", True):
        try:
            rdv = agenda_du_jour(cfg, maintenant=t)
        except Exception:
            rdv = []
    cycle = None
    if contenu == "horloge" and cfg.get("panneau_cycle", True):
        saut = None
        if PANNEAU.get("musique_saut"):                  # un morceau vient de changer
            PANNEAU["musique_saut"] = None
            saut = "musique" if cfg.get("panneau_cycle_saut", True) else None
        duree, fondu_s = reglages_cycle(cfg)
        cycle = cycle_du_panneau(t, cycle_disponible(t, cfg), cycle_urgent(JARVIS.get("minuteurs"), rdv, t), saut,
                                 duree, fondu_s)
        cycle["sensibilite"] = sensibilite_eq(cfg)
    return image_panneau(contenu, t, minuteurs=JARVIS.get("minuteurs"), eclat=eclat, rdv=rdv, cycle=cycle)


def image_du_panneau(cfg, contenu, t):
    """Ce que le panneau montre a l'instant t : la mire pendant un reglage,
    Jarvis quand il est la, sinon son contenu."""
    if contenu == "eteint":
        return image_panneau("eteint", t)
    if PANNEAU.get("mire"):
        return image_mire()
    eclat = eclat_guirlande() if cfg.get("panneau_suit_eclat", True) else None
    effet = image_maj_du_moment(t, eclat) if cfg.get("panneau_maj", True) else None
    if effet is not None:
        if PANNEAU.get("bienvenue") and PANNEAU["bienvenue"].get("debut") is not None:
            # les dernieres 0,6 s : la bienvenue s'efface dans l'image d'apres
            reste = MAJ_BIENVENUE_S - (t - PANNEAU["bienvenue"]["debut"])
            if reste < 0.6:
                import numpy as np
                dessous = image_panneau(contenu, t, minuteurs=JARVIS.get("minuteurs"), eclat=eclat)
                k = max(0.0, reste / 0.6)
                return np.clip(np.round(effet * k + dessous * (1 - k)), 0, 255).astype(np.uint8)
        return effet
    # le programme du jour passe devant Jarvis : demande (« resume-moi ma
    # journee »), il est actif pendant qu'il le dit
    programme = programme_au_panneau(t)
    if programme is not None:
        img = image_programme(programme["rdv"], t, programme.get("journee"), t - programme["debut"])
        return img if eclat is None else assombrir(img, max(PANNEAU_ECLAT_MIN, eclat))
    etat = etat_jarvis_pour_le_panneau(cfg, t)
    if etat is not None:
        return image_jarvis_du_moment(etat, t, cfg, croix=False)
    # FL Studio au premier plan : son studio passe devant l'horloge
    fl = fl_au_premier_plan(t) if cfg.get("panneau_fl", True) else None
    # le miroir de l'ecran (un jeu au premier plan, par defaut)
    miroir = miroir_du_moment(cfg, t) if fl is None else None
    # un ecran plein panneau, de temps en temps, entre deux vues de l'horloge
    ecran = None
    if fl is None and miroir is None and contenu == "horloge":
        ecran = ecran_du_moment(cfg, t, urgent=lambda: _ecran_retenu(cfg, t))
    if fl is not None:
        img = image_fl_studio(t, fl, eclat)
    elif miroir is not None:
        img = image_miroir_fondue(miroir, t, cfg.get("panneau_miroir_style", "couleurs"))
        if eclat is not None:
            img = assombrir(img, max(PANNEAU_ECLAT_MIN, eclat))
    elif ecran is not None:
        img = image_de_l_ecran(ecran, t, reglages_ecrans(cfg)[1], lambda: _image_du_contenu(cfg, contenu, t, None))
        if eclat is not None:
            img = assombrir(img, max(PANNEAU_ECLAT_MIN, eclat))
    else:
        img = _image_du_contenu(cfg, contenu, t, eclat)
    etat_cc = etat_claude(t) if cfg.get("panneau_claude", True) else None
    if etat_cc is not None:
        dessiner_bulle_claude(img, etat_cc, t, eclat)   # par-dessus, en haut a droite
    discord = PANNEAU.get("discord") if cfg.get("panneau_discord", True) else None
    if discord:
        dessiner_pastille_discord(img, discord, eclat)  # en haut a gauche
    if cfg.get("panneau_maj", True) and MAJ.get("etat") == "telechargement":
        dessiner_telechargement(img, MAJ.get("progression"), t, eclat)
    return img


def fletcher16(donnees):
    """La somme de controle des images « MG », la meme que le croquis v3
    (fletcher16) : (b << 8) | a, a = somme des octets, b = somme des sommes,
    modulo 255. Calculee d'un bloc : b = somme des octets ponderes par leur
    nombre d'occurrences dans les sommes partielles (n - i)."""
    import numpy as np
    o = np.frombuffer(bytes(donnees), np.uint8).astype(np.int64)
    a = int(o.sum()) % 255
    b = int((o * np.arange(len(o), 0, -1, dtype=np.int64)).sum()) % 255
    return (b << 8) | a


VEILLE_LUMINOSITE_BORNES = (4, 96)       # 96 : le PLAFOND du croquis sur l'USB seul
VEILLE_ARRETS_H = (0, 1, 2, 4, 8)


def trame_veille(cfg):
    """« MA » : les reglages des ecrans de veille de la carte (croquis v7), qu'elle
    garde meme debranchee -- 12 octets et leur Fletcher-16 : le format (1),
    actif (bit 0) et le sens du panneau (bits 1-2, des quarts de tour comme
    tourner_panneau : « le sketch display les screen savers avec un angle de
    90 degres » ; le croquis v8 les suit, la v7 les ignore), la luminosite,
    les ambiances (un bit chacune, dans l'ordre d'ECRANS_AMBIANCES), la duree
    d'un ecran (s, celle de « Chaque ecran »), l'arret au bout de (min, 0 :
    jamais), la balance du panneau (0-100)."""
    sans = set(cfg.get("panneau_veille_sans") or [])
    masque = sum(1 << i for i, nom in enumerate(ECRANS_AMBIANCES) if nom not in sans)
    duree = int(reglages_ecrans(cfg)[1])
    try:
        arret = int(round(max(0.0, min(24.0, float(cfg.get("panneau_veille_arret_h", 0) or 0))) * 60))
    except (TypeError, ValueError):
        arret = 0
    lum = max(VEILLE_LUMINOSITE_BORNES[0], min(VEILLE_LUMINOSITE_BORNES[1],
                                               entier(cfg.get("panneau_veille_luminosite", 32), 32)))
    rouge, vert, bleu = (int(round(x * 100)) for x in balance_panneau(cfg))
    quarts = (entier(cfg.get("panneau_rotation", 0), 0) // 90) % 4
    actif = (1 if cfg.get("panneau_veille", True) else 0) | quarts << 1
    d = (bytes([1, actif, lum]) + masque.to_bytes(2, "big")
         + duree.to_bytes(2, "big") + arret.to_bytes(2, "big") + bytes([rouge, vert, bleu]))
    return b"MA" + d + fletcher16(d).to_bytes(2, "big")


def trame_image(donnees, croquis):
    """Une image pour la carte : controlee (« MG » + somme) pour le croquis v3,
    « MF » nue sinon -- la v3 accepte les deux, une version mal lue ne fige rien."""
    if (croquis or 1) >= 3:
        return b"MG" + donnees + fletcher16(donnees).to_bytes(2, "big")
    return b"MF" + donnees


def lire_bilan_carte(lien):
    """Les reponses « STATS recues jetees » de la carte (croquis v3), lues sans
    attendre : ce qui est arrive depuis le dernier tour."""
    n = getattr(lien, "in_waiting", 0) or 0
    if not n:
        return
    PANNEAU["_recu"] = (PANNEAU.get("_recu") or b"") + lien.read(n)
    *lignes, PANNEAU["_recu"] = PANNEAU["_recu"].split(b"\n")
    PANNEAU["_recu"] = PANNEAU["_recu"][-200:]
    for ligne in lignes:
        v = re.search(rb"STATS (\d+) (\d+)", ligne)
        if v:
            PANNEAU.update(carte_recues=int(v.group(1)), carte_jetees=int(v.group(2)))
        v = re.search(rb"VEILLE (\d+) (\d+)", ligne)
        if v:
            PANNEAU["carte_veille"] = (int(v.group(1)), int(v.group(2)))   # elle a ses reglages (v7)


def version_croquis(lien, attente=0.5, calme=0.3):
    """Le croquis de la carte : « MV » -> "MACHI 5". La v1 ne repond rien
    (elle ignore « MV ») : 1. `calme` : une image laissee a moitie par une
    session d'avant doit d'abord expirer cote carte (200 ms), sinon « MV »
    finirait dedans."""
    try:
        lien.reset_input_buffer()
        time.sleep(calme)
        lien.reset_input_buffer()
        lien.write(b"MV")
        fin, recu = time.monotonic() + attente, b""
        while time.monotonic() < fin and b"\n" not in recu:
            n = lien.in_waiting
            recu += lien.read(n) if n else b""
            if not n:
                time.sleep(0.02)
        v = re.search(rb"MACHI (\d+)", recu)
        return int(v.group(1)) if v else 1
    except Exception:
        return 1


# LES SOURCES DU CYCLE, dans leur propre fil : le reseau (la meteo, Spotify)
# et le son ne font jamais attendre le panneau. Elles ne tournent que panneau
# branche, en horloge, cycle coche.

def _lire_url_json(url, timeout=10):
    req = urllib.request.Request(url, headers={"User-Agent": "MachiTool/%s" % VERSION})
    with urllib.request.urlopen(req, timeout=timeout, context=_contexte_ssl()) as r:
        return json.loads(r.read().decode("utf-8"))


def lieu_meteo(cfg, lire=None):
    """Ou prendre la meteo : la ville tapee (Open-Meteo la situe), sinon le lieu
    approximatif de la connexion (ipapi.co). Garde dans la config."""
    lire = lire or _lire_url_json
    ville = str(cfg.get("meteo_ville") or "").strip()
    lieu = cfg.get("meteo_lieu") or {}
    if lieu.get("ville", "") == ville and lieu.get("lat") is not None:
        return lieu
    if ville:
        r = lire("https://geocoding-api.open-meteo.com/v1/search?count=1&language=fr&format=json&name="
                 + urllib.parse.quote(ville))
        trouve = (r.get("results") or [None])[0]
        if not trouve:
            raise LookupError("ville introuvable : %s" % ville)
        lieu = {"ville": ville, "nom": trouve.get("name") or ville, "lat": trouve["latitude"],
                "lon": trouve["longitude"]}
    else:
        r = lire("https://ipapi.co/json/")
        lieu = {"ville": "", "nom": r.get("city") or "", "lat": r["latitude"], "lon": r["longitude"]}
    cfg["meteo_lieu"] = lieu
    try:
        sauver_config(cfg)
    except Exception:
        pass
    return lieu


def rafraichir_meteo(cfg, lire=None, maintenant=None):
    """La meteo du moment (Open-Meteo, gratuit, sans cle) : temperature, ciel,
    jour ou nuit, mini et maxi du jour."""
    lire = lire or _lire_url_json
    lieu = lieu_meteo(cfg, lire)
    r = lire("https://api.open-meteo.com/v1/forecast?latitude=%.4f&longitude=%.4f"
             "&current=temperature_2m,weather_code,is_day&daily=temperature_2m_max,temperature_2m_min"
             "&timezone=auto&forecast_days=1" % (float(lieu["lat"]), float(lieu["lon"])))
    c, d = r.get("current") or {}, r.get("daily") or {}
    premier = lambda k: (d.get(k) or [None])[0]
    PANNEAU["meteo"] = {"temp": float(c["temperature_2m"]), "code": int(c.get("weather_code") or 0),
                        "jour": bool(c.get("is_day", 1)), "min": premier("temperature_2m_min"),
                        "max": premier("temperature_2m_max"), "lieu": lieu.get("nom") or "",
                        "quand": time.time() if maintenant is None else maintenant}
    return PANNEAU["meteo"]


def morceau_fenetre_spotify():
    """Sans Spotify relie : le titre de sa fenetre (« Artiste - Titre » quand
    il joue, « Spotify » en pause). Windows seulement."""
    if os.name != "nt":
        return None
    import win32gui
    import win32process
    trouves = []

    def voir(h, _):
        try:
            titre = win32gui.GetWindowText(h)
            if win32gui.IsWindowVisible(h) and " - " in titre:
                _, pid = win32process.GetWindowThreadProcessId(h)
                if (_nom_du_processus(pid) or "").lower() == "spotify.exe":
                    trouves.append(titre)
        except Exception:
            pass
        return True
    win32gui.EnumWindows(voir, None)
    if not trouves:
        return None
    artistes, _, titre = trouves[0].partition(" - ")
    return {"titre": titre.strip(), "artistes": artistes.strip()}


def morceau_en_cours(cfg):
    """Ce que Spotify joue : son API s'il est relie, sinon sa fenetre."""
    if spotify_connecte(cfg):
        try:
            c = spotify_de(cfg).en_cours()
            return {"titre": c["titre"], "artistes": c.get("artistes") or ""} if c and c.get("lecture") else None
        except Exception:
            pass
    try:
        return morceau_fenetre_spotify()
    except Exception:
        return None


def suivre_musique(cfg, maintenant=None, morceau=None):
    """Un morceau joue : la musique entre dans le cycle ; il vient de changer :
    le cycle y saute, son titre avec."""
    t = time.time() if maintenant is None else maintenant
    m = morceau_en_cours(cfg) if morceau is None else morceau
    if m and m.get("titre"):
        PANNEAU["musique_vue"] = t
        cle = (m["titre"], m.get("artistes") or "")
        if cle != PANNEAU.get("morceau_cle"):
            PANNEAU.update(morceau_cle=cle, morceau=dict(m), musique_saut=t)
    return m


def veiller_sources_panneau(cfg=None, tours=None, maintenant=None):
    """Le fil des sources : la capture du son pour l'egaliseur (et pour la vue
    FL Studio), la meteo tous les quarts d'heure, le morceau toutes les 5 s,
    FL Studio au premier plan ou non. `tours` : pour les tests."""
    cfg = CFG if cfg is None else cfg
    n, meteo_t, spotify_t, discord_t = 0, 0.0, 0.0, 0.0
    while ETAT["en_marche"] and (tours is None or n < tours):
        n += 1
        t = time.time() if maintenant is None else maintenant
        connecte = bool(cfg.get("panneau_actif", True) and PANNEAU.get("etat") == "connecte")
        actif = bool(connecte and cfg.get("panneau_cycle", True) and cfg.get("panneau_contenu", "horloge") == "horloge")
        fenetre = fenetre_active() if connecte else ""
        if connecte and cfg.get("panneau_miroir", "jeux") in ("jeux", "plein_ecran"):
            suivre_jeu(t)                               # le miroir : un jeu ? du plein ecran ?
        studio = False                                  # FL Studio au premier plan : sa vue ecoute le son
        if connecte and cfg.get("panneau_fl", True) and cfg.get("panneau_contenu", "horloge") != "eteint":
            suivre_fl_studio(t, fenetre)
            studio = fl_au_premier_plan(t) is not None
        ecoute = actif or studio
        if ecoute and not SON.get("panneau"):
            SON["panneau"] = True
            demarrer_audio(cfg)
        elif not ecoute and SON.get("panneau"):
            SON["panneau"] = False
            if cfg.get("mode") != "son":
                arreter_audio()
        if actif:
            suivre_presence(t)                          # la maid : veilles-tu ? depuis quand ?
            if float(AUDIO.get("brut") or 0) > 1e-3:
                PANNEAU["musique_vue"] = t              # quelque chose sort des haut-parleurs
            if t >= meteo_t or PANNEAU.get("meteo_a_relire"):
                PANNEAU["meteo_a_relire"] = False
                try:
                    rafraichir_meteo(cfg, maintenant=maintenant)
                    meteo_t = t + METEO_S
                except Exception as e:
                    print("Panneau LED : meteo indisponible (%s)" % type(e).__name__)
                    meteo_t = t + 120
            if t >= spotify_t:
                spotify_t = t + SPOTIFY_S
                suivre_musique(cfg, t)
        if cfg.get("panneau_actif", True) and cfg.get("panneau_discord", True) \
                and PANNEAU.get("etat") == "connecte" and t >= discord_t:
            discord_t = t + DISCORD_RELEVE_S
            suivre_discord(maintenant=t)
        if tours is None:
            time.sleep(1.0)


PANNEAU_SACCADE_S = 1.5 * PANNEAU_PAS_S   # deux images trop espacees : l'oeil voit l'a-coup
PANNEAU_RAPPORT_S = 300                  # le journal dit les saccades au plus toutes les 5 min
FIGER_APRES_S = 60                       # la memoire du demarrage, figee une minute apres le lancement
_RAMASSE = {"debut": 0.0, "max_ms": 0.0}


def _mesurer_ramasse_miettes(phase, info):
    """Les passages complets du ramasse-miettes de Python : ils arretent TOUS
    les fils le temps de parcourir la memoire -- une saccade, s'ils sont longs."""
    if info.get("generation") != 2:
        return
    if phase == "start":
        _RAMASSE["debut"] = time.perf_counter()
    else:
        _RAMASSE["max_ms"] = max(_RAMASSE["max_ms"], (time.perf_counter() - _RAMASSE["debut"]) * 1000)


def figer_la_memoire():
    """Une minute apres le lancement, tout ce que le demarrage a construit
    (l'interface, Jarvis, les reglages...) ne bougera plus guere : le
    ramasse-miettes cesse de le reparcourir a chaque passage complet. Ses
    pauses -- qui figeaient le panneau -- ne portent plus que sur le neuf.
    Rend le nombre d'objets figes."""
    import gc
    gc.collect()
    gc.freeze()
    n = gc.get_freeze_count()
    print("Memoire du demarrage figee : %d objets que le ramasse-miettes ne reparcourt plus." % n)
    return n


def priorite_du_fil(niveau):
    """La priorite Windows du fil qui l'appelle : 2 (THREAD_PRIORITY_HIGHEST),
    -2 (THREAD_PRIORITY_LOWEST)... True si c'est fait."""
    if os.name != "nt":
        return False
    try:
        import ctypes
        k = ctypes.WinDLL("kernel32", use_last_error=True)
        k.GetCurrentThread.restype = ctypes.c_void_p
        k.SetThreadPriority.argtypes = [ctypes.c_void_p, ctypes.c_int]
        return bool(k.SetThreadPriority(k.GetCurrentThread(), int(niveau)))
    except Exception:
        return False


def presser_ce_fil():
    """Le fil du panneau passe devant les autres fils de Windows : reveille a
    l'heure, il n'attend pas qu'un autre ait fini son tour. True si c'est fait."""
    return priorite_du_fil(2)                                         # THREAD_PRIORITY_HIGHEST


def compter_saccades(envois, maintenant, fenetre_s=60.0):
    """Les saccades de la derniere minute : deux images envoyees a plus d'une
    image et demie d'intervalle (`envois` : leurs heures de depart)."""
    recents = [x for x in envois if x > maintenant - fenetre_s]
    return sum(1 for a, b in zip(recents, recents[1:]) if b - a > PANNEAU_SACCADE_S)


def piloter_panneau(cfg=None, tours=None):
    """Le fil du panneau : l'image du moment (l'apercu la montre, branche ou
    non), et, une carte trouvee, la luminosite puis une image toutes les
    1/30 s -- toutes, meme identiques : « j'ai l'impression que c'est pas a
    30 fps » ; le debit tenu s'affiche. Une liaison perdue (debranchee,
    reprise par Arduino) se recherche seule ; une image qui ne passe pas a
    temps (la carte deborde), elle, ne coupe rien. `tours` : pour les tests.

    « Il y a toujours un probleme de stutter, ce n'est pas a 30 fps constant. »
    Le debit moyen y etait, pas la regularite : l'image se calculait a
    l'echeance, puis partait -- quelques millisecondes plus tard, ou bien plus
    quand un autre fil de Machi Tool tenait la main. Maintenant chaque image
    se calcule AVANT son echeance, pour l'instant ou elle sera montree ; a
    l'heure dite, il ne reste qu'a l'envoyer. Le fil passe devant les autres
    (Windows), et Python lui rend la main plus vite. Les saccades qui restent
    se comptent : la page les affiche, le journal dit d'ou elles viennent."""
    cfg = CFG if cfg is None else cfg
    lien, lum, recherche, bilan, veille_envoyee = None, None, 0.0, 0.0, None
    n, prochaine, envois = 0, time.monotonic(), deque(maxlen=PANNEAU_IPS * 3)
    durees = deque(maxlen=PANNEAU_IPS * 2)      # (calcul, envoi, retard au reveil) en s : qui ralentit ?
    departs = deque(maxlen=PANNEAU_IPS * 70)    # les heures de depart de la derniere minute : les saccades
    rapport = time.monotonic() + 60.0
    if tours is None:
        import gc
        presser_ce_fil()
        sys.setswitchinterval(min(sys.getswitchinterval(), 0.002))     # un fil qui attend la main l'a vite
        if _mesurer_ramasse_miettes not in gc.callbacks:
            gc.callbacks.append(_mesurer_ramasse_miettes)

    def jusqu_a_l_echeance():
        """Dort jusqu'a l'echeance de cette image ; rend le retard au reveil (s)."""
        if tours is not None:
            return 0.0
        reste = prochaine - time.monotonic()
        if reste > 0:
            time.sleep(reste)
        return max(0.0, time.monotonic() - prochaine)
    while ETAT["en_marche"] and (tours is None or n < tours):
        n += 1
        contenu = cfg.get("panneau_contenu", "horloge")
        contenu = contenu if contenu in PANNEAU_CONTENUS else "horloge"
        attendu = False
        try:
            debut = time.perf_counter()
            # l'image de l'echeance qui vient, calculee avant elle, pour son instant a elle
            t = time.time() + max(0.0, prochaine - time.monotonic())
            img = image_du_panneau(cfg, contenu, t)
            PANNEAU["image"] = img
            if not cfg.get("panneau_actif", True):
                if lien is not None:
                    try:
                        with PANNEAU_VERROU:
                            lien.write(b"MO")       # decoche : au silence, noir (pas les ambiances)
                    except Exception:
                        pass
                    lien.close()
                    lien = None
                PANNEAU.update(etat="coupe", port=None)
            elif lien is None and time.time() >= recherche:
                recherche = time.time() + PANNEAU_CHERCHE_S
                port = trouver_panneau()
                if port:
                    try:
                        lien = ouvrir_panneau(port)
                        lum = None
                        envois.clear()
                        durees.clear()
                        departs.clear()
                        PANNEAU.update(etat="connecte", port=port, envoyees=0, ips=0.0, _recu=b"",
                                       carte_recues=None, carte_jetees=None, croquis=version_croquis(lien),
                                       saccades=0, carte_veille=None)
                        veille_envoyee = None
                        bilan = time.monotonic() + PANNEAU_BILAN_S
                        print("Panneau LED : connecte sur %s" % port)
                    except Exception:
                        PANNEAU.update(etat="occupe", port=port)
                else:
                    PANNEAU.update(etat="absent", port=None)
            PANNEAU["lien"] = lien
            if lien is not None and PANNEAU.get("fini"):
                pass                               # Machi Tool s'en va : le panneau reste noir
            elif lien is not None:
                voulue = 0 if contenu == "eteint" else int(max(0, min(255, cfg.get("panneau_luminosite", 64))))
                donnees = trame_image(rgb565(tourner_panneau(img, cfg.get("panneau_rotation", 0)),
                                             balance_panneau(cfg)), PANNEAU.get("croquis"))
                calcul = time.perf_counter()
                retard = jusqu_a_l_echeance()      # l'heure dite : il ne reste qu'a l'envoyer
                attendu = True
                depart = time.perf_counter()
                if voulue != lum:
                    with PANNEAU_VERROU:
                        lien.write(b"MB" + bytes([voulue]))
                    lum = voulue
                if (PANNEAU.get("croquis") or 1) >= 7:
                    veille = trame_veille(cfg)      # ses ambiances, PC eteint : a la connexion, et a chaque reglage
                    if veille != veille_envoyee:
                        with PANNEAU_VERROU:
                            lien.write(veille)
                        veille_envoyee = veille
                try:
                    with PANNEAU_VERROU:
                        lien.write(donnees)
                        if (PANNEAU.get("croquis") or 1) >= 3 and time.monotonic() >= bilan:
                            lien.write(b"MS")
                            bilan = time.monotonic() + PANNEAU_BILAN_S
                    lire_bilan_carte(lien)
                    PANNEAU["envoyees"] += 1
                    envois.append(time.monotonic())
                    departs.append(time.monotonic())
                except Exception as e:
                    if type(e).__name__ != "SerialTimeoutException":
                        raise
                    PANNEAU["perdues"] = PANNEAU.get("perdues", 0) + 1   # la carte suit moins vite
                durees.append((calcul - debut, time.perf_counter() - depart, retard))
                PANNEAU["calcul_ms"] = 1000 * max(d[0] for d in durees)
                PANNEAU["envoi_ms"] = 1000 * max(d[1] for d in durees)
                PANNEAU["reveil_ms"] = 1000 * max(d[2] for d in durees)
                if len(envois) >= 2 and envois[-1] > envois[0]:
                    recentes = [x for x in envois if x > time.monotonic() - 2.0]
                    PANNEAU["ips"] = (len(recentes) - 1) / max(1e-3, recentes[-1] - recentes[0]) \
                        if len(recentes) >= 2 else 0.0
                PANNEAU["saccades"] = compter_saccades(departs, time.monotonic())
                if tours is None and time.monotonic() >= rapport:
                    rapport = time.monotonic() + PANNEAU_RAPPORT_S
                    if PANNEAU["saccades"]:
                        print("Panneau LED : %d saccade(s) la derniere minute -- reveil en retard jusqu'a %.0f ms, "
                              "calcul jusqu'a %.0f ms, envoi jusqu'a %.0f ms, ramasse-miettes jusqu'a %.0f ms"
                              % (PANNEAU["saccades"], PANNEAU["reveil_ms"], PANNEAU["calcul_ms"],
                                 PANNEAU["envoi_ms"], _RAMASSE["max_ms"]))
                    _RAMASSE["max_ms"] = 0.0
        except Exception as e:
            print("Panneau LED : liaison perdue (%s)" % type(e).__name__)
            try:
                if lien is not None:
                    lien.close()
            except Exception:
                pass
            lien = None
            PANNEAU.update(etat="absent", port=None, lien=None)
            recherche = time.time() + 1.0
        if tours is None:
            # un rendez-vous fixe toutes les 1/30 s, pas « 1/30 s apres le
            # travail » : sinon 30 i/s deviendraient 27. En retard (une
            # recherche de port), on repart de maintenant sans rattraper.
            if not attendu:
                jusqu_a_l_echeance()
            prochaine += PANNEAU_PAS_S
            if prochaine < time.monotonic():
                prochaine = time.monotonic()
    PANNEAU["lien"] = None
    if lien is not None:
        try:
            lien.close()
        except Exception:
            pass


def eteindre_en_partant():
    """Le panneau, quand Machi Tool s'en va : noir -- sauf pour une mise a
    jour, ou l'anneau de la pose reste le temps que la nouvelle version
    reprenne (la carte s'eteint d'elle-meme cinq secondes sans image)."""
    if MAJ.get("pose_lancee") and MAJ.get("etat") == "a_poser":
        PANNEAU["fini"] = True                   # le fil n'ecrit plus, le panneau garde l'anneau
        lien = PANNEAU.get("lien")
        if lien is not None:
            try:
                with PANNEAU_VERROU:
                    lien.write(b"MO")            # puis le noir, pas les ambiances (croquis v7)
            except Exception:
                pass
        return False
    return eteindre_panneau()


def eteindre_panneau():
    """« Quand Machi Tool s'eteint, eteins automatiquement le panneau (comme la
    guirlande). » Luminosite 0 et une image noire, sur la liaison du fil, puis
    plus rien : le fil n'ecrit plus (PANNEAU["fini"]). Rend True si c'est parti."""
    PANNEAU["fini"] = True
    lien = PANNEAU.get("lien")
    if lien is None:
        return False
    try:
        with PANNEAU_VERROU:
            lien.write(b"MB" + bytes([0]))
            lien.write(b"MF" + bytes(PANNEAU_L * PANNEAU_H * 2))
            lien.write(b"MO")                    # croquis v7 : et pas d'ambiances au silence (les autres l'ignorent)
            lien.flush()
        print("Panneau LED eteint.")
        return True
    except Exception as e:
        print("Panneau LED : extinction impossible (%s)" % type(e).__name__)
        return False


def confier_panneau_a_la_carte(cfg=None):
    """« Les screen savers meme a l'arret du PC » : Windows s'arrete, la carte
    (croquis v7) prend le relais avec ses ambiances -- « MW », ses reglages
    juste avant ; puis le fil n'ecrit plus. Rend True si elle l'a pris ; sinon
    (decoche, ancien croquis, pas de carte), rien n'est envoye."""
    cfg = CFG if cfg is None else cfg
    lien = PANNEAU.get("lien")
    if lien is None or (PANNEAU.get("croquis") or 1) < 7 or not cfg.get("panneau_veille", True):
        return False
    if PANNEAU.get("confie"):
        return True                              # QUERYENDSESSION puis ENDSESSION : une fois suffit
    PANNEAU.update(fini=True, confie=True)
    try:
        with PANNEAU_VERROU:
            lien.write(trame_veille(cfg) + b"MW")
            lien.flush()
        print("Panneau LED : la carte prend le relais avec ses ambiances.")
        return True
    except Exception as e:
        print("Panneau LED : relais impossible (%s)" % type(e).__name__)
        return False


def etat_veille_lisible(cfg):
    """Une ligne pour la page : ce que fera la carte quand le PC s'eteindra."""
    if not cfg.get("panneau_veille", True):
        return "PC eteint, le panneau s'eteint aussi."
    sans = set(cfg.get("panneau_veille_sans") or [])
    n = sum(1 for nom in ECRANS_AMBIANCES if nom not in sans)
    if not n:
        return "Aucune ambiance cochee : PC eteint, le panneau s'eteint aussi."
    if PANNEAU.get("etat") != "connecte":
        return "Les reglages partiront a la carte des qu'elle sera branchee."
    croquis = PANNEAU.get("croquis") or 1
    if croquis < 7:
        return ("La carte a le croquis v%d : televerse la v%d (carte/machi_panneau/machi_panneau.ino) pour "
                "qu'elle dessine les ambiances elle-meme." % (croquis, PANNEAU_CROQUIS))
    if croquis < 8 and (entier(cfg.get("panneau_rotation", 0), 0) // 90) % 4:
        return ("La carte a le croquis v7 : ses ambiances ne suivent pas le sens du panneau. Televerse la v%d "
                "(carte/machi_panneau/machi_panneau.ino)." % PANNEAU_CROQUIS)
    if PANNEAU.get("carte_veille"):
        texte = "La carte a ses reglages : %d ambiance%s quand le PC s'eteindra." % (n, "s" if n > 1 else "")
        if croquis < 9 and "neige" not in sans:
            texte += " (Croquis v%d : sa neige fait encore des colonnes ; la v%d la met en tas.)" % (croquis,
                                                                                                  PANNEAU_CROQUIS)
        return texte
    return "Les reglages partent a la carte..."


def etat_panneau_lisible():
    e, port = PANNEAU.get("etat"), PANNEAU.get("port")
    if not PANNEAU.get("pyserial", True):
        return "Il manque pyserial a cette version de Machi Tool.", ALERTE
    if e == "connecte":
        ips = float(PANNEAU.get("ips") or 0.0)
        texte = ("Branche sur %s  ·  %.0f im/s (reglee %d)" % (port, ips, PANNEAU_IPS) if ips
                 else "Branche sur %s" % port)
        saccades = PANNEAU.get("saccades")
        if ips and saccades is not None:
            # « ce n'est pas a 30 fps constant » : le debit moyen ne dit pas la regularite
            texte += "  ·  %s" % ("aucune saccade" if not saccades else
                                  "%d saccade%s la derniere minute" % (saccades, "s" if saccades > 1 else ""))
        jetees = PANNEAU.get("carte_jetees")
        if jetees:
            # depuis que la carte a demarre : le transfert USB abime-t-il des images ?
            texte += "  ·  %d image%s abimee%s jetee%s par la carte" % ((jetees,) + ("s",) * 3 if jetees > 1
                                                                        else (jetees, "", "", ""))
            recues = PANNEAU.get("carte_recues")
            if recues is not None:
                # « il y a toujours un probleme de stutter » : chaque image jetee est une saccade
                texte += " sur %d (%s %%)" % (recues + jetees, ("%.1f" % (100.0 * jetees / max(1, recues + jetees)))
                                              .replace(".", ","))
        if (PANNEAU.get("croquis") or PANNEAU_CROQUIS) < PANNEAU_CROQUIS:
            texte += ("\nLa carte a un ancien croquis (version %d) : televerse carte/machi_panneau/"
                      "machi_panneau.ino (version %d) : images controlees et lues par blocs (plus d'images "
                      "abimees, plus de saccades), et ses propres ambiances quand le PC s'eteint, dans le "
                      "sens du panneau."
                      % (PANNEAU["croquis"], PANNEAU_CROQUIS))
        elif ips and (ips < PANNEAU_IPS * 0.8 or (saccades or 0) >= 10):
            # « ca tombe a 5 fps parfois » : qui ralentit, la carte ou le PC ?
            calcul, envoi = float(PANNEAU.get("calcul_ms") or 0), float(PANNEAU.get("envoi_ms") or 0)
            reveil = float(PANNEAU.get("reveil_ms") or 0)
            if reveil > max(calcul, envoi):
                texte += ("\nC'est Windows qui le reveille en retard : jusqu'a %.0f ms apres l'heure "
                          "(un programme qui prend tout le processeur ?)." % reveil)
            else:
                texte += ("\nC'est la carte qui suit mal : une image met jusqu'a %.0f ms a partir." % envoi
                          if envoi >= calcul else
                          "\nC'est le PC qui ralentit : une image met jusqu'a %.0f ms a se faire." % calcul)
        return texte, VIF
    if e == "occupe":
        return ("%s est pris par un autre programme (le Serial Monitor d'Arduino, ou test_panneau.py) : "
                "ferme-le, je reessaie toutes les 5 s." % port), ALERTE
    if e == "coupe":
        return "Machi Tool laisse le panneau tranquille (Arduino peut s'en servir).", BRUME
    return ("Pas de panneau branche : la MatrixPortal en USB-C, avec le croquis du guide. "
            "Je la cherche toutes les 5 s."), BRUME


# ---------- apprendre la voix ----------

def apprendre_a_voix_haute(cfg):
    """« Apprends ma voix » / « learn my voice », dit a Jarvis -- demande :
    « fait en sorte qu'on puisse juste Jarvis pour lui parler ». Le modele
    d'openWakeWord ne connait que « Hey Jarvis » ; « Jarvis » tout seul, c'est
    la voix de la personne, apprise. Il l'explique a voix haute, se TAIT, et
    ecoute quatre fois son nom, la guirlande allumee a chaque fois : sa propre
    voix dans l'empreinte serait une empreinte de lui-meme."""
    a = JARVIS.get("apprentissage")
    if a and not a.get("fini"):
        return False
    L = langue_jarvis(cfg)
    dire_et_attendre(phrase("apprendre", L), L)
    time.sleep(0.8)                        # que l'echo de sa voix se taise
    ok = apprendre_voix()
    dire(phrase("appris" if ok else "pas_appris", L), langue=L)
    return ok


GABARITS_PLAFOND = 20         # au-dela, chaque mot entendu coute trop a comparer
# « L'APPELER AVEC BEAUCOUP DE TONS DIFFERENTS », et « plus de tests pour que
# ma voix soit reconnue le plus justement possible ». Cinq fois normalement
# (le noyau de la voix : voir choisir_gabarits dans jarvis.py), puis les tons
# qui s'en ecartent le plus : la question, de loin et fort, bas et en passant.
TONS_APPRENTISSAGE = (
    None, None, None, None, None,
    "Comme une question : « Jarvis ? »",
    "Plus fort, comme depuis l'autre bout de la piece : « JARVIS ! »",
    "Plus bas, en passant, comme dans une phrase : « ...jarvis... »",
)
N_NORMAUX = sum(1 for t in TONS_APPRENTISSAGE if t is None)
# « PLUS DE FACONS DE CALIBRER, pour reconnaitre les differents types de Jarvis
# que je peux dire » : « Calibrer encore » ajoute ces cinq-la aux autres.
TONS_CALIBRATION = (
    "Comme d'habitude, sans y penser",
    "Au milieu d'une phrase : « ... et Jarvis ... »",
    "Fatigue, a moitie articule",
    "D'un peu plus loin du micro",
    "Vite et sec : « Jarvis ! »",
)
_MOTS_COURANTS = {"bonjour", "merci", "voila", "alors", "ouais", "bien", "donc", "cest", "quoi", "comment"}


def _lire_nom(ev):
    """Comment la transcription ecrit ce « Jarvis » -- le son sert a ca et
    n'est garde nulle part."""
    try:
        if ev.get("wav") and etat_dictee()["etat"] == "pret":
            return [m for m in _jv.noms_entendus(transcrire(base64.b64decode(ev["wav"])))
                    if m not in _MOTS_COURANTS]
    except Exception as e:
        print("Jarvis : lecture du nom impossible (%s)" % type(e).__name__)
    return []


def resume_seuils(cfg):
    """« Ta voix varie de 0,12 : reveil direct jusqu'a 0,05, verifie jusqu'a 0,14. »"""
    perso = _jv.seuil_personnel(gabarits_jarvis())
    direct, verifie = _jv.seuils_detection(cfg.get("jarvis_sensibilite", 0.5), perso,
                                           cfg.get("jarvis_tolerant", True))
    return ("%sreveil direct jusqu'a %.2f, verifie jusqu'a %.2f" % (
        "ta voix varie de %.2f : " % perso if perso else "", direct, verifie)).replace(".", ",")


def apprendre_voix(total=len(TONS_APPRENTISSAGE), essais_max=16, ajouter=False, tons=None):
    """« Jarvis », huit fois, dit par la personne -- cinq fois a plat, puis
    sur les tons de TONS_APPRENTISSAGE : « Jarvis ? » monte et traine, et trois
    « Jarvis » dits a plat ne le reconnaissaient pas (voir GABARIT_SAUT dans
    jarvis.py) ; fort ou bas, c'est la meme chose. A lancer dans un fil.

    `ajouter` : des facons de plus, gardees avec celles deja apprises --
    « Ajouter une facon » (une, celle qui ne passe pas) ou « Calibrer encore »
    (les tons de TONS_CALIBRATION). Chacune est jugee a part."""
    if not oreille_vivante():
        JARVIS["apprentissage"] = {"n": 0, "total": total, "fini": True,
                                   "message": "Clique d'abord « Activer Jarvis » : il faut le micro."}
        return False
    appris, essais, niveaux, noms = [], 0, [], []
    JARVIS["apprentissage"] = {"n": 0, "total": total, "fini": False, "message": ""}
    while len(appris) < total and essais < essais_max:
        essais += 1
        liste = tons if tons is not None else (() if ajouter else TONS_APPRENTISSAGE)
        ton = liste[len(appris)] if len(appris) < len(liste) else None
        if ton:
            consigne = "%s (%d/%d)." % (ton, len(appris) + 1, total)
        elif ajouter:
            consigne = "Dis-le maintenant, de la facon qu'il ne reconnait pas."
        else:
            consigne = "Dis « Jarvis » maintenant, comme tu l'appelleras (%d/%d)." % (len(appris) + 1, total)
        JARVIS["apprentissage"].update(n=len(appris), message=consigne)
        poser_led("apprend")
        _GABARIT_RECU["signal"].clear()
        _GABARIT_RECU["evt"] = None
        envoyer_oreille({"cmd": "apprendre"})
        if not _GABARIT_RECU["signal"].wait(7.0):
            envoyer_oreille({"cmd": "annuler"})
            JARVIS["apprentissage"]["message"] = "Je n'ai rien recu du micro. On recommence."
            time.sleep(1.2)
            continue
        ev = _GABARIT_RECU["evt"] or {}
        if ev.get("vecteurs"):
            appris.append(ev["vecteurs"])
            if isinstance(ev.get("niveau"), (int, float)) and ev["niveau"] > 0:
                niveaux.append(float(ev["niveau"]))
            noms += _lire_nom(ev)
            poser_led("fait", 0.5)
            time.sleep(0.8)
        else:
            poser_led("erreur", 0.8)
            JARVIS["apprentissage"]["message"] = "Rate (%s). On recommence." % (ev.get("erreur") or "?")
            time.sleep(1.4)
    if len(appris) < total:
        poser_led(None)
        JARVIS["apprentissage"].update(fini=True, message="Pas assez d'essais reussis. Reessaie au calme.")
        return False
    niveau = sorted(niveaux)[len(niveaux) // 2] if niveaux else None
    ecartes = 0
    if ajouter:
        deja = gabarits_jarvis()
        # Des facons de plus, mais du meme mot : loin de toutes celles apprises,
        # c'est un autre mot (ou un bruit), et il se reveillerait dessus.
        bons = [g for g in appris if not deja or min(
            _jv.distance_gabarit(_jv.normer(d), _jv.normer(g)) for d in deja) <= _jv.ESSAI_ECART_MAX]
        ecartes = len(appris) - len(bons)
        if not bons:
            poser_led("erreur", 1.2)
            JARVIS["apprentissage"].update(
                fini=True, message="Ca ne ressemble a aucune des facons apprises. Reessaie, "
                                   "ou reapprends tout.")
            return False
        appris = (deja + bons)[-GABARITS_PLAFOND:]
        sauver_gabarits(appris, garder_auto=True, niveau=niveau, noms=noms)
    else:
        # le plus grand groupe coherent des essais normaux, puis tout essai
        # assez proche de lui (voir choisir_gabarits) : un essai rate ne fait
        # plus tout jeter
        gardes, ecart, ecartes = _jv.choisir_gabarits(appris, min(N_NORMAUX, total))
        if gardes is None:
            poser_led("erreur", 1.2)
            JARVIS["apprentissage"].update(
                fini=True, message="Tes « Jarvis » ne se ressemblent pas du tout (%.2f) : le micro "
                                   "entend-il bien ta voix ? Rapproche-toi et reessaie au calme." % ecart)
            return False
        appris = gardes[:GABARITS_PLAFOND]
        sauver_gabarits(appris, niveau=niveau, noms=noms)
    envoyer_oreille(config_oreille(CFG))
    poser_led("fait", 1.2)
    jouer_son("fait")
    fin = "Appris (%d facons%s) -- %s. Dis « Jarvis » pour essayer." % (
        len(appris), "" if not ecartes else ", %d essai%s ecarte%s : du bruit" % (
            ecartes, "s" if ecartes > 1 else "", "s" if ecartes > 1 else ""), resume_seuils(CFG))
    JARVIS["apprentissage"].update(n=total, fini=True, message=fin)
    JARVIS["message"] = message_attente()
    return True


def oreille_enfant_depuis_argv():
    i = sys.argv.index(JARVIS_ENFANT_ARG)
    _jv.oreille_enfant(sys.argv[i + 1], sys.argv[i + 2], sys.argv[i + 3])


class Passerelle(http.server.BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *_):
        pass                                   # pas de bruit dans le journal

    # ---------- entetes ----------

    def entetes_cors(self):
        origine = self.headers.get("Origin", "")
        autorisees = CFG.get("api_origines", [])
        if "*" in autorisees:
            self.send_header("Access-Control-Allow-Origin", origine or "*")
        elif origine and origine in autorisees:
            self.send_header("Access-Control-Allow-Origin", origine)
        self.send_header("Vary", "Origin")
        self.send_header("Access-Control-Allow-Headers",
                         "content-type, x-jeton, x-machitool-cle")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Private-Network", "true")
        self.send_header("Access-Control-Max-Age", "600")

    def repondre(self, code, charge):
        corps = json.dumps(charge).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(corps)))
        self.entetes_cors()
        self.end_headers()
        self.wfile.write(corps)

    def do_OPTIONS(self):
        self.send_response(204)
        self.entetes_cors()
        self.send_header("Content-Length", "0")
        self.end_headers()

    # ---------- lecture de la requete ----------

    def origine_permise(self):
        origine = self.headers.get("Origin", "")
        autorisees = CFG.get("api_origines", [])
        return ("*" in autorisees) or (not origine) or (origine in autorisees)

    def jeton_permis(self, corps):
        attendu = CFG.get("api_jeton", "")
        if not attendu:
            return True
        fourni = self.headers.get("X-Jeton", "") or (corps.get("jeton", "")
                                                     if isinstance(corps, dict) else "")
        return secrets.compare_digest(str(fourni), str(attendu))

    def cle_pont_permise(self):
        """La cle du pont, acceptee UNIQUEMENT pour lire /activite.

        Le site tient deja cette cle (pont_cle cote app == passerelleCle cote
        site) : il tire donc le digest sans nouveau secret a recopier. On la
        cantonne a la lecture d'enveloppe — jamais au controle de la lumiere, qui
        reste derriere le jeton local — et la liste d'origines reste le garde-fou."""
        pont = str(CFG.get("pont_cle", "")).strip()
        cle_site = self.headers.get("X-Machitool-Cle", "")
        return bool(pont) and bool(cle_site) and \
            secrets.compare_digest(str(cle_site), pont)

    def lire_corps(self):
        try:
            taille = int(self.headers.get("Content-Length", 0))
            if not taille:
                return {}
            return json.loads(self.rfile.read(taille).decode("utf-8"))
        except Exception:
            return {}

    # ---------- la dictee ----------

    def route_dictee(self, chemin):
        """Le site envoie le son, Machi Tool rend le texte. Meme cle que la
        lecture de l'activite : le site la tient deja."""
        if not (self.jeton_permis({}) or self.cle_pont_permise()):
            return self.repondre(401, {"erreur": "jeton invalide"})
        if not dictee_possible():
            return self.repondre(501, {"erreur": "moteur de dictee absent de cette version"})
        if chemin == "/dictee/preparer":
            if DICTEE["etat"] not in ("preparation", "pret"):
                threading.Thread(target=preparer_dictee, daemon=True).start()
            return self.repondre(202, etat_dictee())
        try:
            taille = int(self.headers.get("Content-Length", 0))
        except ValueError:
            taille = 0
        if taille <= 0 or taille > DICTEE_MAX_OCTETS:
            return self.repondre(413, {"erreur": "son vide ou trop long"})
        octets = self.rfile.read(taille)
        if etat_dictee()["etat"] != "pret":
            return self.repondre(409, etat_dictee())
        try:
            texte = transcrire(octets)
        except ValueError as e:
            return self.repondre(400, {"erreur": str(e)[:200]})
        except DicteeImpossible as e:
            return self.repondre(503, {"erreur": str(e)[:300]})
        except Exception as e:
            print("Dictee : transcription impossible (%s)" % type(e).__name__)
            return self.repondre(500, {"erreur": "transcription impossible (%s)" % type(e).__name__})
        finally:
            octets = None                          # le son ne survit pas a la requete
        # Le texte n'est PAS journalise : c'est ce que la personne vient de dire.
        return self.repondre(200, {"texte": texte})

    # ---------- routes ----------

    def cle_onglets_permise(self):
        """L'extension de Machi Tool : sa propre cle, et une origine
        d'extension (ou aucune). Pas le jeton du serveur local."""
        attendue = str(CFG.get("onglets_cle", "") or "")
        origine = self.headers.get("Origin", "")
        return bool(attendue) and (not origine or origine.startswith("chrome-extension://")) and \
            secrets.compare_digest(str(self.headers.get("X-Onglets-Cle", "")), attendue)

    def route_onglets(self, chemin):
        if not self.cle_onglets_permise():
            return self.repondre(401, {"erreur": "cle d'extension invalide"})
        if chemin == "/onglets/attente" and self.command == "GET":
            c = prochaine_commande_onglets()
            if c is None:
                self.send_response(204)
                self.send_header("Content-Length", "0")
                self.end_headers()
                return None
            return self.repondre(200, c)
        if chemin == "/onglets/resultat" and self.command == "POST":
            resultat_onglets(self.lire_corps())
            return self.repondre(200, {"ok": True})
        return self.repondre(404, {"erreur": "route inconnue"})

    def do_GET(self):
        chemin = self.path.split("?")[0].rstrip("/") or "/"
        if chemin.startswith("/onglets/"):
            return self.route_onglets(chemin)
        if not self.origine_permise():
            return self.repondre(403, {"erreur": "origine non autorisee"})
        if chemin == "/etat":
            r, v, b = ETAT["couleur"]
            forcage = ETAT.get("forcage")
            return self.repondre(200, {
                "version": VERSION,
                "connecte": ETAT["connecte"],
                "couleur": rgb_vers_hex((r, v, b)),
                "rvb": [r, v, b],
                "source": ETAT["regle"],
                "mode": CFG.get("mode", "applications"),
                "force": bool(forcage and time.time() < forcage["expire"]),
                "humeurs": [r_["nom"] for r_ in CFG.get("regles", [])],
            })
        if chemin == "/dictee":
            if not (self.jeton_permis({}) or self.cle_pont_permise()):
                return self.repondre(401, {"erreur": "jeton invalide"})
            return self.repondre(200, etat_dictee())
        if chemin == "/activite":
            # Le site tire le digest du jour quand il veut, avec le jeton de
            # la passerelle locale — pas la cle du pont. Aucune dependance a
            # l'authentification du site : c'est lui qui appelle 127.0.0.1.
            if not (self.jeton_permis({}) or self.cle_pont_permise()):
                return self.repondre(401, {"erreur": "jeton invalide"})
            params = urllib.parse.parse_qs(self.path.partition("?")[2])
            if params.get("tout", ["0"])[0] in ("1", "true", "oui"):
                # Tout l'historique d'un coup : de quoi remettre a jour chaque
                # jour (lever, coucher, ecran) en un seul appel.
                return self.repondre(200, {
                    "jours": tous_les_jours_activite(),
                    "journal_actif": ACTIVITE["active"]})
            digest = dict(resume_activite())
            digest["journal_actif"] = ACTIVITE["active"]
            return self.repondre(200, digest)
        return self.repondre(404, {"erreur": "route inconnue"})

    def do_POST(self):
        chemin = self.path.split("?")[0].rstrip("/") or "/"
        if chemin.startswith("/onglets/"):
            return self.route_onglets(chemin)
        if not self.origine_permise():
            return self.repondre(403, {"erreur": "origine non autorisee"})
        # La dictee AVANT la lecture JSON : son corps est du son, pas du JSON.
        if chemin in ("/dictee", "/dictee/preparer"):
            return self.route_dictee(chemin)
        corps = self.lire_corps()
        if not self.jeton_permis(corps):
            return self.repondre(401, {"erreur": "jeton invalide"})

        duree = float(corps.get("duree", 30))
        duree = max(1.0, min(3600.0, duree))

        # Interrupteur maitre : si BrainDebugger n'a pas le droit de piloter la
        # guirlande, ses ordres de couleur sont recus poliment mais sans effet.
        # On ne pose aucun forcage, et le site le sait par la reponse.
        if chemin in ("/couleur", "/humeur") and not CFG.get("pont_affecte_leds", True):
            return self.repondre(200, {"ok": False, "desactive": True,
                                       "raison": "BrainDebugger n'affecte pas les LEDs"})

        if chemin == "/couleur":
            brut = corps.get("couleur")
            if isinstance(brut, str):
                rvb = hex_vers_rgb(brut)
            elif isinstance(brut, (list, tuple)) and len(brut) == 3:
                rvb = tuple(max(0, min(255, int(c))) for c in brut)
            else:
                return self.repondre(400, {"erreur": "couleur manquante"})
            ETAT["forcage"] = {"couleur": rvb, "expire": time.time() + duree,
                               "nom": corps.get("nom") or "Site web"}
            return self.repondre(200, {"ok": True, "couleur": rgb_vers_hex(rvb),
                                       "duree": duree})

        if chemin == "/humeur":
            nom = corps.get("humeur") or corps.get("nom")
            rvb = couleur_de_regle(CFG, nom)
            if not rvb:
                return self.repondre(404, {
                    "erreur": f"aucune regle nommee {nom!r}",
                    "humeurs": [r_["nom"] for r_ in CFG.get("regles", [])]})
            ETAT["forcage"] = {"couleur": rvb, "expire": time.time() + duree,
                               "nom": str(nom)}
            return self.repondre(200, {"ok": True, "humeur": nom,
                                       "couleur": rgb_vers_hex(rvb), "duree": duree})

        if chemin == "/presence":
            # Le site declare qu'on l'utilise. La duree est courte a
            # dessein : un onglet ferme brutalement ne doit pas laisser la
            # guirlande bloquee sur sa couleur.
            duree_p = max(5.0, min(300.0, float(corps.get("duree", 60))))
            if corps.get("actif", True):
                ETAT["presence"] = {"jusqu_a": time.time() + duree_p}
            else:
                ETAT["presence"] = None
                ETAT["presence_vu"] = 0.0
            # Present sur le site : bonne occasion de lui pousser la
            # journee a jour, sans attendre l'ecriture horaire.
            synchroniser_activite(CFG)
            return self.repondre(200, {"ok": True, "duree": duree_p})

        if chemin == "/relacher":
            ETAT["forcage"] = None
            return self.repondre(200, {"ok": True})

        if chemin == "/claude":
            # un crochet de Claude Code : rien en retour (204) -- ce qu'un crochet
            # ecrit, Claude Code peut le lire
            recevoir_claude_code(corps)
            self.send_response(204)
            self.entetes_cors()
            self.send_header("Content-Length", "0")
            self.end_headers()
            return None

        # ---- BrainDebugger ----

        if chemin == "/rappel":
            titre = str(corps.get("titre") or "BrainDebugger")[:64]
            texte = str(corps.get("texte") or "")[:220]
            if not texte:
                return self.repondre(400, {"erreur": "texte manquant"})
            deposer_rappel(corps.get("id"), titre, texte)
            return self.repondre(200, {"ok": True})

        if chemin == "/humeur-du-jour":
            PONT["humeur"] = {
                "valeur": corps.get("valeur"),
                "libelle": str(corps.get("libelle") or "")[:60],
                "couleur": str(corps.get("couleur") or "")[:9],
                "date": str(corps.get("date") or "")[:32],
            }
            PONT["etat"] = "ok"
            PONT["vu_le"] = time.time()
            PONT["message"] = "Humeur recue du site."
            return self.repondre(200, {"ok": True})

        if chemin == "/journal":
            # Le site est maitre de ses donnees : on remplace, on ne fusionne
            # pas. Une entree effacee la-bas doit disparaitre ici aussi.
            jours = corps.get("jours")
            reperes = corps.get("reperes")
            if isinstance(jours, list):
                PONT["jours"] = [j for j in jours if isinstance(j, dict)][:400]
            if isinstance(reperes, list):
                PONT["reperes"] = [r for r in reperes if isinstance(r, dict)][:400]
            PONT["etat"] = "ok"
            PONT["vu_le"] = time.time()
            PONT["message"] = "Journal recu du site."
            return self.repondre(200, {"ok": True,
                                       "jours": len(PONT["jours"]),
                                       "reperes": len(PONT["reperes"])})

        return self.repondre(404, {"erreur": "route inconnue"})


def recevoir_a_noter(a_noter, maintenant=None):
    """Les journees pas encore notees, telles que BrainDebugger les donne
    (des dates seulement) : gardees dans PONT, avec l'heure du releve."""
    t = time.time() if maintenant is None else maintenant
    date = lambda d: isinstance(d, str) and re.fullmatch(r"\d{4}-\d{2}-\d{2}", d) is not None
    jours = [d for d in (a_noter.get("jours") or []) if date(d)][:31]
    aujourdhui = a_noter.get("aujourdhui") if date(a_noter.get("aujourdhui")) else None
    PONT["a_noter"] = {"jours": jours, "aujourdhui": aujourdhui,
                       "aujourdhui_notee": bool(a_noter.get("aujourdhui_notee")), "recu": t}
    return PONT["a_noter"]


def deposer_rappel(identifiant, titre, texte):
    """Range un rappel et le signale. Les doublons sont ignores : le site
    peut reemettre le meme tant qu'il n'a pas ete acquitte."""
    identifiant = str(identifiant or (titre + texte))[:80]
    if any(r["id"] == identifiant for r in PONT["rappels"]):
        return False
    PONT["rappels"].insert(0, {"id": identifiant, "titre": titre,
                               "texte": texte, "recu": time.time()})
    del PONT["rappels"][20:]
    PONT["etat"] = "ok"
    PONT["vu_le"] = time.time()
    PONT["message"] = titre
    ETAT["rappel_neuf"] = True     # la boucle du panneau le notifiera
    return True


def _plus_vieux_qu_un_jour(iso):
    """Vrai si cet horodatage ISO date de plus de 24 h (ou ne se lit pas)."""
    try:
        t = time.mktime(time.strptime(str(iso)[:19], "%Y-%m-%dT%H:%M:%S"))
        # strptime rend une heure locale : l'ISO du site est en UTC.
        return (time.time() - (t - time.timezone)) > 86400
    except Exception:
        return False


def relever_le_site(cfg):
    """Demande au site ce qu'il a en attente.

    Necessaire parce que le site ne peut rien pousser quand aucun onglet
    n'est ouvert : cette machine n'a pas d'adresse joignable depuis
    Internet. C'est donc l'application qui va voir.

    Contrat attendu cote site, en GET sur <pont_site>/api/machitool/attente :
        {"rappels":  [{"id": "...", "titre": "...", "texte": "..."}],
         "humeur":   {"valeur": 3, "libelle": "...", "couleur": "#RRGGBB"},
         "jours":    [{"date": "2026-08-29", "note": "...", "couleur": "..."}],
         "reperes":  [{"date": "...", "titre": "...", "couleur": "..."}]}
    Toutes les cles sont facultatives. Tant que la route n'existe pas, le
    404 est avale sans bruit.
    """
    base = str(cfg.get("pont_site", "")).strip().rstrip("/")
    if not base:
        return False
    url = base + "/api/machitool/attente?version=" + urllib.parse.quote(VERSION)
    cle = str(cfg.get("pont_cle", "")).strip()
    entetes = {"User-Agent": "MachiToolkit/" + VERSION, "Accept": "application/json"}
    if cle:
        # La cle part de trois facons a la fois : le site n'a qu'a lire
        # celle qui l'arrange, sans qu'on ait a s'accorder d'avance.
        url += "&cle=" + urllib.parse.quote(cle)
        entetes["Authorization"] = "Bearer " + cle
        entetes["X-Machitool-Cle"] = cle

    PONT["etat"] = "releve"
    try:
        requete = urllib.request.Request(url, headers=entetes)
        with urllib.request.urlopen(requete, timeout=12,
                                    context=_contexte_ssl()) as reponse:
            donnees = json.loads(reponse.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        PONT["etat"] = "erreur"
        if e.code == 404:
            PONT["message"] = ("Le site ne propose pas encore de route "
                               "/api/machitool/attente.")
        elif e.code in (401, 403):
            PONT["message"] = (
                "Le site demande une authentification (%s). La route existe "
                "donc bien. Renseigne la cle dans Passerelle : elle part en "
                "Authorization: Bearer, en X-Machitool-Cle et en ?cle=."
                % e.code) if not cle else (
                "Le site refuse la cle (%s). Verifie qu'il attend la meme, "
                "et qu'il la lit dans l'un des trois emplacements envoyes."
                % e.code)
        else:
            PONT["message"] = "Le site a repondu %s." % e.code
        return False
    except Exception as e:
        PONT["etat"] = "erreur"
        PONT["message"] = "Site injoignable : %s" % str(e)[:60]
        return False

    if not isinstance(donnees, dict):
        PONT["etat"] = "erreur"
        PONT["message"] = "Reponse du site illisible."
        return False

    neufs = 0
    for rappel in (donnees.get("rappels") or []):
        if isinstance(rappel, dict) and rappel.get("texte"):
            if deposer_rappel(rappel.get("id"),
                              str(rappel.get("titre") or "BrainDebugger")[:64],
                              str(rappel["texte"])[:220]):
                neufs += 1
    if isinstance(donnees.get("humeur"), dict):
        PONT["humeur"] = donnees["humeur"]
    if isinstance(donnees.get("jours"), list):
        PONT["jours"] = [j for j in donnees["jours"] if isinstance(j, dict)][:400]
    if isinstance(donnees.get("reperes"), list):
        PONT["reperes"] = [r for r in donnees["reperes"] if isinstance(r, dict)][:400]
    if isinstance(donnees.get("a_noter"), dict):
        recevoir_a_noter(donnees["a_noter"])

    # LA DEMANDE DE SYNCHRO. Le site ne peut rien pousser vers cette machine :
    # c'est ici, au releve, qu'on apprend qu'on la lui doit. Deux raisons de
    # partir : quelqu'un l'a demandee depuis le site (« synchroniser », meme
    # depuis un telephone), ou le site n'a rien recu depuis plus d'un jour alors
    # qu'on collecte -- une passerelle muette qui se repare toute seule.
    syn = donnees.get("synchro") if isinstance(donnees.get("synchro"), dict) else {}
    demande = str(syn.get("demande_le") or "")
    if demande and demande != SYNC.get("demande_vue"):
        SYNC["demande_vue"] = demande
        PONT["message"] = "Le site demande la journee : envoi en cours."
        synchroniser_activite(cfg, minimum=0)
    elif syn.get("recu_le") is None or _plus_vieux_qu_un_jour(syn.get("recu_le")):
        synchroniser_activite(cfg, minimum=6 * 3600)

    PONT["etat"] = "ok"
    PONT["vu_le"] = time.time()
    if neufs:
        PONT["message"] = "%d rappel(s) recu(s)." % neufs
    else:
        PONT["message"] = "Site joint, rien de neuf."
    return True


def demarrer_api(cfg):
    arreter_api()
    if not cfg.get("api_active"):
        ETAT["api"] = "arretee"
        return
    try:
        # DANS le try, pas devant : `jeton_courant` ecrit la configuration, et
        # une ecriture qui echoue remontait jusqu'a tuer le demarrage entier.
        jeton_courant(cfg)
        port = entier(cfg.get("api_port", 7373), 7373)
        serveur = http.server.ThreadingHTTPServer(("127.0.0.1", port), Passerelle)
        serveur.daemon_threads = True
        SERVEUR["http"] = serveur
        threading.Thread(target=serveur.serve_forever, daemon=True).start()
        ETAT["api"] = f"a l'ecoute sur 127.0.0.1:{port}"
        print("Passerelle HTTP demarree sur le port", port)
    except Exception as e:
        ETAT["api"] = f"echec : {str(e)[:40]}"
        print("Passerelle HTTP impossible :", e)


def arreter_api():
    if SERVEUR.get("http"):
        try:
            SERVEUR["http"].shutdown()
            SERVEUR["http"].server_close()
        except Exception:
            pass
        SERVEUR["http"] = None
    ETAT["api"] = "arretee"


