    def regler_panneau(self, cle):
        if cle == "panneau_actif":
            self.cfg[cle] = bool(self.var_panneau_actif.get())
        elif cle == "panneau_jarvis":
            self.cfg[cle] = bool(self.var_panneau_jarvis.get())
        elif cle == "panneau_claude":
            self.cfg[cle] = bool(self.var_panneau_claude.get())
        elif cle == "panneau_maj":
            self.cfg[cle] = bool(self.var_panneau_maj.get())
        elif cle == "panneau_fl":
            self.cfg[cle] = bool(self.var_panneau_fl.get())
            if not self.cfg[cle]:
                PANNEAU["fl"] = None
        elif cle == "panneau_discord":
            self.cfg[cle] = bool(self.var_panneau_discord.get())
            if not self.cfg[cle]:
                PANNEAU["discord"] = None
        elif cle in ("panneau_cycle", "panneau_cycle_meteo", "panneau_cycle_musique", "panneau_cycle_bonhomme",
                     "panneau_cycle_saut", "panneau_cycle_chat", "panneau_cycle_maid", "panneau_cycle_notes",
                     "panneau_ecrans"):
            self.cfg[cle] = bool(getattr(self, "var_" + cle).get())
        elif cle == "meteo_ville":
            ville = self.champ_meteo_ville.get().strip()[:60]
            if ville == str(self.cfg.get("meteo_ville") or ""):
                return
            self.cfg[cle] = ville
            PANNEAU["meteo_a_relire"] = True           # le fil la relit tout de suite, pour cette ville
        elif cle == "panneau_rdv":
            self.cfg[cle] = bool(self.var_panneau_rdv.get())
        elif cle == "panneau_suit_eclat":
            self.cfg[cle] = bool(self.var_panneau_suit_eclat.get())
        elif cle == "panneau_rotation":
            self.cfg[cle] = int(self.var_panneau_rotation.get())
        elif cle == "panneau_contenu":
            self.cfg[cle] = self.var_panneau_contenu.get()
        elif cle in ("panneau_miroir", "panneau_miroir_style"):
            self.cfg[cle] = getattr(self, "var_" + cle).get()
            if cle == "panneau_miroir" and self.cfg[cle] == "jamais":
                PANNEAU["miroir"] = None                # coupe : il s'efface tout de suite
        elif cle == "panneau_miroir_filtre":
            self.cfg[cle] = bool(self.var_panneau_miroir_filtre.get())
        elif cle == "panneau_veille":
            self.cfg[cle] = bool(self.var_panneau_veille.get())
        elif cle == "panneau_veille_arret_h":
            self.cfg[cle] = int(self.var_panneau_veille_arret_h.get())
        sauver_config(self.cfg)
        self._peindre_panneau()

    def copier_cle_bulle(self):
        """« MACHITOOL_BULLE_CLE=... » dans le presse-papiers : la ligne a coller
        dans les variables d'environnement de l'environnement Claude Code."""
        cle = cle_bulle_claude(self.cfg)
        if not cle:
            message = "Il faut d'abord la cle de la passerelle (Reglages, BrainDebugger)."
        elif copier_presse_papiers("%s=%s" % (CLAUDE_VARIABLE, cle)):
            message = ("Copie : colle-la dans les variables d'environnement de l'environnement Claude Code, et "
                       "autorise braindebugger-production.up.railway.app dans son acces reseau.")
        else:
            message = "%s=%s" % (CLAUDE_VARIABLE, cle)
        try:
            self.txt_claude_cloud.configure(text=message)
        except Exception:
            pass

    @staticmethod
    def _texte_claude_code():
        return "Debrancher Claude Code" if claude_code_branche() else "Brancher Claude Code"

    def basculer_claude_code(self):
        """Ajoute nos crochets aux reglages de Claude Code -- ou les retire."""
        branche = claude_code_branche()
        try:
            chemin = brancher_claude_code(self.cfg, brancher=not branche)
            message = ("Retire de %s." if branche else
                       "Ajoute a %s : la bulle viendra a ta prochaine demande a Claude Code.") % chemin
        except Exception as e:
            message = str(e)[:240] if isinstance(e, ValueError) else "Impossible : %s" % type(e).__name__
        for widget, texte in ((getattr(self, "bouton_claude_code", None), self._texte_claude_code()),
                              (getattr(self, "txt_claude_code", None), message)):
            if widget is not None:
                try:
                    widget.configure(text=texte)
                except Exception:
                    pass

    @staticmethod
    def _texte_mire():
        return "Cacher la mire" if PANNEAU.get("mire") else "Montrer la mire"

    def basculer_mire(self):
        """La mire sur le panneau : un clic l'allume, le suivant l'eteint."""
        PANNEAU["mire"] = not PANNEAU.get("mire")
        if getattr(self, "bouton_mire", None) is not None:
            try:
                self.bouton_mire.configure(text=self._texte_mire())
            except Exception:
                pass
        self._peindre_panneau()

    def choisir_ecrans(self, noms=None):
        """Les cases des ecrans et des familles (ou « Tous », « Les ambiances et les
        decors ») : la config retient ceux qu'on a decoches -- une famille decochee,
        tous les siens ; le prochain ecran les respecte deja."""
        if noms is not None:
            for nom, v in self.vars_ecrans.items():
                v.set(1 if nom in noms else 0)
            for v, membres in self.vars_familles.values():
                v.set(1 if any(n in noms for n in membres) else 0)
        sans = [nom for nom, v in self.vars_ecrans.items() if not v.get()]
        for v, membres in self.vars_familles.values():
            if not v.get():
                sans += list(membres)
        self.cfg["panneau_ecrans_sans"] = sans
        PANNEAU["ecrans_sac"] = None
        sauver_config(self.cfg)

    def choisir_veille(self):
        """Les cases des ambiances de la carte, PC eteint : la config retient celles
        qu'on a decochees ; le fil du panneau les lui renvoie."""
        self.cfg["panneau_veille_sans"] = [nom for nom, v in self.vars_veille.items() if not v.get()]
        sauver_config(self.cfg)

    def montrer_ecran(self):
        """« Montrer un ecran » : le suivant, tout de suite, sur le panneau (et l'apercu)."""
        demander_ecran()
        ETAT["message"] = "Un ecran arrive sur le panneau."

    def _panneau_reglage_bientot(self, cle, valeur):
        """Une reglette du cycle : le panneau la suit tout de suite, la config
        s'ecrit une fois le geste fini."""
        self.cfg[cle] = valeur
        if getattr(self, "_panneau_sauve", None):
            self.root.after_cancel(self._panneau_sauve)
        self._panneau_sauve = self.root.after(500, lambda: sauver_config(self.cfg))

    def _panneau_balance_bientot(self, cle, v):
        """La balance s'applique a l'image suivante ; la config s'ecrit une fois
        le geste fini. La mire, elle, ne s'allume qu'au bouton."""
        self.cfg[cle] = int(v.get())
        if getattr(self, "_panneau_sauve", None):
            self.root.after_cancel(self._panneau_sauve)
        self._panneau_sauve = self.root.after(500, lambda: sauver_config(self.cfg))

    def _panneau_luminosite_bientot(self):
        """Le fil suit la reglette en direct ; la config s'ecrit une fois le geste fini."""
        self.cfg["panneau_luminosite"] = int(self.var_panneau_luminosite.get())
        if getattr(self, "_panneau_sauve", None):
            self.root.after_cancel(self._panneau_sauve)
        self._panneau_sauve = self.root.after(500, lambda: sauver_config(self.cfg))

    def _peindre_panneau(self):
        """Les apercus (la tuile, la page) : l'image du fil, ou celle qu'il montrerait."""
        img = PANNEAU.get("image")
        if img is None:
            try:
                img = image_panneau(self.cfg.get("panneau_contenu", "horloge"), minuteurs=JARVIS.get("minuteurs"))
            except Exception:
                return
        cle = img.tobytes()
        memo = self.__dict__.setdefault("_apercus_panneau", {})
        for nom in ("apercu_tuile", "apercu_page_panneau"):
            c = getattr(self, nom, None)
            if c is None:
                continue
            try:
                if not c.winfo_exists():
                    continue
            except Exception:
                continue
            if memo.get(nom, (None,))[0] == cle:
                continue
            zoom = max(1, int(c.cget("width")) // PANNEAU_L)
            # master=c : l'image vit dans la fenetre de la toile, pas dans la
            # premiere fenetre Tk ouverte (refaire l'interface en cree une autre).
            photo = self.tk.PhotoImage(master=c, width=PANNEAU_L, height=PANNEAU_H)
            lignes = " ".join("{" + " ".join("#%02x%02x%02x" % tuple(px) for px in rang) + "}" for rang in img)
            photo.put(lignes, to=(0, 0))
            grande = photo.zoom(zoom, zoom)
            c.delete("all")
            c.create_image(0, 0, image=grande, anchor="nw")
            memo[nom] = (cle, grande)
        if getattr(self, "txt_claude_code", None) is not None and CLAUDE_CODE.get("vu"):
            try:
                self.txt_claude_code.configure(text=etat_claude_code_lisible(self.cfg))
            except Exception:
                pass
        if getattr(self, "txt_claude_cloud", None) is not None and CLAUDE_CODE.get("vu_cloud"):
            try:
                self.txt_claude_cloud.configure(text=etat_cloud_lisible(self.cfg))
            except Exception:
                pass
        if getattr(self, "txt_miroir", None) is not None:
            try:
                self.txt_miroir.configure(text=etat_miroir_lisible(self.cfg))
                self.txt_miroir_filtre.configure(text=etat_filtre_miroir(self.cfg))
                self.txt_veille.configure(text=etat_veille_lisible(self.cfg))
            except Exception:
                pass
        if getattr(self, "txt_discord", None) is not None:
            try:
                self.txt_discord.configure(text=_DISCORD.get("lisible") or DISCORD_PAS_ENCORE)
            except Exception:
                pass
        texte, couleur = etat_panneau_lisible()
        if getattr(self, "txt_panneau_etat", None) is not None:
            try:
                self.txt_panneau_etat.configure(text=texte, fg=couleur)
            except Exception:
                pass
        if getattr(self, "etat_tuile_panneau", None) is not None:
            court = {"connecte": "branche \u2014 %s" % PANNEAU.get("port"), "occupe": "port occupe",
                     "coupe": "laisse tranquille"}.get(PANNEAU.get("etat"), "non branche")
            try:
                self.etat_tuile_panneau.configure(text=court, fg=VIF if PANNEAU.get("etat") == "connecte" else BRUME)
            except Exception:
                pass

    def tuile_a_venir(self, parent):
        """Place tenue pour le prochain outil. Une grille a une seule tuile
        se lit comme une page ratee ; avec ce fantome elle se lit comme une
        collection qui commence."""
        tk = self.tk
        carte = tk.Frame(parent, bg=NUIT, highlightthickness=1,
                         highlightbackground=FIL)
        dedans = tk.Frame(carte, bg=NUIT, padx=22, pady=24)
        dedans.pack(fill="both", expand=True)
        tk.Frame(dedans, bg=NUIT, height=34).pack()
        tk.Label(dedans, text="+", bg=NUIT, fg=FIL,
                 font=(self.f_titre, 40)).pack()
        tk.Label(dedans, text="Prochain outil", bg=NUIT, fg=BRUME,
                 font=(self.f_ui, 11)).pack(pady=(14, 4))
        tk.Label(dedans, text="La place est prete", bg=NUIT, fg=FIL,
                 font=(self.f_ui, 9)).pack()
        return carte

